SELECT 'b8f85adc-c3ee-5679-8a0c-3e01715d4f0f','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b8f85adc-c3ee-5679-8a0c-3e01715d4f0f' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f179948e-f0a5-5d7a-9b22-d056fab41a5c','Detector-weighted compression','Compression in which the level detector''s input is deliberately frequency-weighted — filtered or shaped with an emphasis curve — so the processor responds more strongly to some parts of the spectrum than others, while still applying broadband gain reduction to the full signal. Weighting the detector (for example rolling off lows or emphasising sibilance) changes what triggers the compressor without itself equalising the output.','Normally a compressor reacts to the whole sound equally. Detector-weighted compression tilts what it listens to. It can ignore deep bass or clamp hard on harsh highs. The volume still ducks across the whole sound, just triggered differently.','It lets an engineer choose which frequencies drive the gain reduction, so the compressor can stop chasing loud bass or clamp down on sharp highs, giving more musical, frequency-aware control.','A mix engineer high-passes or contours the side-chain so a vocal or bus compressor reacts to the body and sibilance rather than to low-end thumps, smoothing the result.','Compression technique',ARRAY['Detector signal','Sidechain','De-essing','Dynamic equalization','External-sidechain compression','Detector ripple']::text[],ARRAY['Assuming detector weighting equalises the sound; it changes only what the compressor reacts to, not the output tone directly.','Over-filtering the detector so the compressor barely responds, then adding too much gain reduction to compensate.','Confusing detector-weighted compression with dynamic EQ, which changes gain only within the targeted band.']::text[],ARRAY['Rolling off lows in a bus compressor''s side-chain so it stops pumping on the kick.','Emphasising sibilant frequencies in the detector so a compressor acts as a de-esser.','Weighting the detector toward a vocal''s fundamental so it rides level more evenly.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f179948e-f0a5-5d7a-9b22-d056fab41a5c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Detector-weighted compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f179948e-f0a5-5d7a-9b22-d056fab41a5c','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f179948e-f0a5-5d7a-9b22-d056fab41a5c' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9501d722-f694-59c9-84b6-84134ffda9f1','Dry-path latency mismatch','A timing error that occurs when the processed ("wet") path of a parallel or blend setup carries a different signal delay from the unprocessed ("dry") path, so the two are no longer time-aligned when summed. Sources include look-ahead, oversampling, linear-phase or FFT processing, and converter or plugin latency; the misalignment causes comb filtering, hollow or thin tone, and partial cancellation when the paths mix.','Parallel processing blends a treated copy of a sound with the untouched original. If the treated copy is delayed even slightly, the two copies no longer line up. Mixed together, they cancel parts of the sound. The result can sound thin or hollow.','The term identifies why a blended or parallel chain can sound worse than either path alone, pointing to delay compensation as the fix so the wet and dry paths stay time-aligned.','When parallel compression thins out the low end, an engineer checks that plugin delay compensation is active, or manually delays the dry path to match a latency-inducing processor.','Signal alignment',ARRAY['Parallel compression','Plugin delay compensation','Comb filtering','Phase cancellation','Look-ahead','Latency']::text[],ARRAY['Blaming a thin, hollow parallel-compression sound on the compressor when unmatched latency is comb-filtering the mix.','Assuming plugin delay compensation fixes everything; some hardware inserts and external processing report no latency and are not compensated.','Nudging the dry track by ear without measuring the actual processor latency, leaving a residual offset.']::text[],ARRAY['Parallel drum compression that cancels low end because the wet path adds look-ahead delay.','Blending a linear-phase or oversampled processor with a dry signal without delay compensation.','Using an outboard hardware insert whose converter latency is not reported to the mixer''s compensation.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9501d722-f694-59c9-84b6-84134ffda9f1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dry-path latency mismatch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9501d722-f694-59c9-84b6-84134ffda9f1','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9501d722-f694-59c9-84b6-84134ffda9f1' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c098e82a-d588-537f-968f-3752e09e52c2','Dual-time-constant release','A release behaviour in which gain recovery uses two different time constants — a fast one that lets the processor recover quickly from brief transients and a slow one that governs recovery from sustained level changes — so the effective release adapts to the programme. This program-dependent design reduces low-frequency distortion and pumping from transients while keeping long, smooth gain recovery on steady material.','After a loud moment, a compressor slowly brings the volume back up. This design uses two speeds at once. Quick spikes recover fast, but steady loud parts recover slowly. That keeps the sound smooth and cuts down on pumping.','Two time constants let a compressor react cleanly to sharp peaks without the audible pumping or distortion a single fast release causes on sustained sound, giving a more natural, transparent result.','An engineer picks a compressor with program-dependent or "auto" release, or an optical unit, on vocals or the mix bus to get transient control and smooth recovery without chasing release settings.','Time constants',ARRAY['Release time','Attack time','Program-dependent release','Optical compressor','Pumping','RMS detection']::text[],ARRAY['Expecting a single fixed release time on a program-dependent compressor, then being confused when recovery speed changes with the material.','Setting a very fast single release to control peaks and then hearing pumping that a dual-time-constant design would avoid.','Assuming "auto release" is a gimmick rather than a genuine dual- or multi-time-constant, program-dependent circuit.']::text[],ARRAY['Using an optical or auto compressor on lead vocal so fast peaks and slow phrases both recover smoothly.','Mix-bus gluing where a program-dependent release avoids audible pumping.','Taming a dynamic bass line without the low-frequency distortion a single fast release would add.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c098e82a-d588-537f-968f-3752e09e52c2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dual-time-constant release'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c098e82a-d588-537f-968f-3752e09e52c2','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c098e82a-d588-537f-968f-3752e09e52c2' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7e540115-0c81-558c-8085-763d0705e5bf','Dynamic frequency pocketing','A dynamic-processing technique that creates a temporary spectral "pocket" — a dip in one sound''s frequency response — only while a competing element is present, using a dynamic equaliser or frequency-selective compressor, often keyed from that competing source. It reduces frequency masking by clearing spectral room (for example, dipping guitars in the vocal''s range) only when needed, rather than cutting statically.','In a busy mix, two sounds can fight over the same frequencies. Dynamic frequency pocketing carves a small gap in one sound to make room for the other. The gap opens only when the other sound plays. The rest of the time the tone stays full.','It reduces frequency masking between competing elements while preserving each sound''s full tone when the other is absent, giving clarity without a permanent EQ cut.','An engineer sets a dynamic EQ on the guitars, keyed from the vocal, to dip a midrange band only when the vocal sings, keeping the vocal clear without dulling the guitars throughout.','Dynamic EQ',ARRAY['Dynamic equalization','Frequency masking','Sidechain','Detector-weighted compression','Multiband compression','External-sidechain compression']::text[],ARRAY['Using a static EQ cut where a dynamic pocket is needed, dulling the source even when nothing competes with it.','Setting the pocket too deep or too wide, so the dip becomes audible as pumping in the tone.','Forgetting to key the dynamic EQ from the competing source, so the pocket does not track when it is actually needed.']::text[],ARRAY['Dipping a guitar''s mid band under a lead vocal only while the vocal sings.','Clearing low-mid room for a kick by pocketing the bass in that band when the kick hits.','Reducing masking between two synths that share a frequency range.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7e540115-0c81-558c-8085-763d0705e5bf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dynamic frequency pocketing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7e540115-0c81-558c-8085-763d0705e5bf','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7e540115-0c81-558c-8085-763d0705e5bf' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2640ec1d-4068-5beb-ab54-9fd4c3b8bd9e','EQ-into-compression','A signal-chain arrangement in which an equaliser is placed before a compressor, so the compressor acts on the already-equalised signal and — in units whose detector follows the input — is triggered by the boosted or cut spectrum. Because the EQ shapes what the detector "hears," pre-compression EQ changes both the tone and how the compressor responds, unlike EQ placed after compression.','Order matters when you chain effects. Putting EQ before a compressor means the compressor reacts to the new tone. Boost a frequency first, and the compressor clamps down on it harder. Put EQ after, and it only reshapes the already-squashed sound.','Placing EQ before compression lets an engineer control what the compressor reacts to — taming a boosted resonance or making it ride a chosen band — whereas EQ after compression only shapes the final tone.','To stop a compressor over-reacting to boomy low end, an engineer cuts the lows with EQ before it; to make it grab a vocal''s presence, they boost that band pre-compressor.','Signal chain',ARRAY['Detector signal','Detector-weighted compression','Parametric equalizer','Compression','Gain staging','Sidechain']::text[],ARRAY['Not realising that EQ before a compressor changes how hard and where the compressor reacts, not just the tone.','Boosting a frequency before compression and then wondering why the compressor pumps on that band.','Assuming EQ-before and EQ-after a compressor sound the same; the detector reacts only to what comes before it.']::text[],ARRAY['Cutting low end before a vocal compressor so it stops ducking on plosives.','Boosting presence before compression to make the compressor emphasise and even out that band.','Comparing EQ-before versus EQ-after placement to hear how the compressor''s response changes.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2640ec1d-4068-5beb-ab54-9fd4c3b8bd9e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('EQ-into-compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2640ec1d-4068-5beb-ab54-9fd4c3b8bd9e','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2640ec1d-4068-5beb-ab54-9fd4c3b8bd9e' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fb75cbe5-f2ae-55d0-a562-c29552f1b7c6','Edge','An informal timbral descriptor for a hard, aggressive, cutting quality in a sound, generally associated with pronounced upper-midrange and high-frequency energy, sharp transients, or added harmonic distortion. A sound with "edge" tends to stand out and cut through a mix; the term describes a subjective character rather than a measured quantity.','"Edge" describes a sound that is hard, sharp, and aggressive. It usually comes from strong high-mid frequencies, crisp attacks, or a bit of grit. A sound with edge cuts through a mix and grabs attention. Too much can feel harsh.','The word gives engineers a shared way to talk about aggression and cut in a sound, guiding choices such as presence boosts, transient emphasis, or saturation to add it, or the reverse to tame it.','Asked for more "edge" on a guitar or vocal, an engineer adds upper-mid presence, sharpens transients, or drives light saturation; asked for less, they soften those.','Tonal descriptor',ARRAY['Presence','Harmonic distortion','Transient','Emphasis-driven saturation','Brightness','Harshness']::text[],ARRAY['Adding edge with a broad high boost and pushing the sound into harshness instead of controlled bite.','Treating "edge" as a precise setting rather than a subjective quality that depends on source and context.','UNSAFE: Chasing more edge by monitoring louder and louder to hear the highs, raising sound-pressure levels and hearing-damage risk; adjust the sound, not the monitoring level.']::text[],ARRAY['A producer asking for more edge on a rock vocal to help it cut through the guitars.','Adding bite to a synth with transient shaping and light saturation.','Taming excessive edge on a harsh cymbal track.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fb75cbe5-f2ae-55d0-a562-c29552f1b7c6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Edge'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fb75cbe5-f2ae-55d0-a562-c29552f1b7c6','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fb75cbe5-f2ae-55d0-a562-c29552f1b7c6' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '554d8d3a-56fe-5d07-96ae-fa72b933a350','Emphasis-driven saturation','A saturation technique in which the signal is frequency-emphasised (pre-emphasised) before it enters a nonlinear, distortion-producing stage, so the boosted frequencies drive the saturator harder and generate more harmonics there, with optional complementary de-emphasis afterward. It concentrates harmonic generation in a chosen part of the spectrum rather than saturating all frequencies equally.','Saturation adds gentle distortion and harmonics to a sound. Emphasis-driven saturation boosts certain frequencies first, so they distort more than the rest. A matching cut afterward can restore the balance. This puts the grit where you want it.','Pre-emphasis before saturation targets harmonic generation to specific frequencies, letting an engineer add presence or air where wanted while keeping other bands cleaner, much as tape and disc pre-emphasis shaped distortion and noise.','An engineer boosts highs into a saturator to add "air" harmonics, then de-emphasises, or drives a chosen band harder to add bite there without muddying the low end.','Saturation',ARRAY['Saturation','Pre-emphasis','De-emphasis','Harmonic distortion','Exciter return','Edge']::text[],ARRAY['Forgetting the complementary de-emphasis and ending up with an unintentionally bright, harsh result.','Driving the emphasised band so hard that harmonics turn to obvious buzz rather than subtle warmth or air.','Confusing emphasis-driven saturation with plain EQ; the emphasis shapes where distortion forms, not just level.']::text[],ARRAY['Boosting highs into a saturator to add air to a dull vocal, then trimming the boost.','Emphasising a guitar''s midrange before a drive stage to add bite in that band.','Using pre-emphasis to concentrate tape-style harmonics on the top end.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='554d8d3a-56fe-5d07-96ae-fa72b933a350' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Emphasis-driven saturation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '554d8d3a-56fe-5d07-96ae-fa72b933a350','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='554d8d3a-56fe-5d07-96ae-fa72b933a350' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4e252206-3e2a-545b-aaa5-9c6bed478281','Envelope-density increase','An increase in the perceived fullness or "density" of a sound''s amplitude envelope produced by dynamics processing that raises the average (RMS) level relative to the peaks, so quieter portions are brought up and sustain is emphasised. Achieved through compression, limiting, or parallel compression, it reduces dynamic range and makes the sound feel more solid, sustained, and energetic.','A sound''s loudness rises and falls over time; that shape is its envelope. Compression lifts the quiet parts closer to the loud parts. This fills in the envelope and makes the sound feel fuller and more sustained. Engineers call that added fullness density.','Increasing envelope density makes a track sound bigger, more sustained, and more consistent, helping it sit forward and feel powerful — a core reason compression and parallel compression are used.','To make a drum bus or vocal feel fuller and more upfront, an engineer applies compression or parallel compression to lift the sustain and quieter detail without simply raising the peaks.','Compression effect',ARRAY['Parallel compression','Dynamic range','Sustain','RMS detection','Makeup gain','Limiting']::text[],ARRAY['Pushing for density with heavy compression until the sound is squashed, flat, and lifeless.','Confusing density (more average level and sustain) with simply turning the track up, which does not change the envelope shape.','UNSAFE: Judging "bigger" and denser by cranking monitor volume, which raises sound-pressure exposure; compare at a safe, fixed level instead.']::text[],ARRAY['Parallel-compressing drums to add weight and sustain without losing the transients.','Compressing a vocal so quiet syllables stay present and the line feels fuller.','Adding density to a bass so it holds a steadier, more solid level.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4e252206-3e2a-545b-aaa5-9c6bed478281' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Envelope-density increase'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4e252206-3e2a-545b-aaa5-9c6bed478281','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4e252206-3e2a-545b-aaa5-9c6bed478281' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1a63b6a6-ac10-57e6-97c0-e3deb388e27f','Envelope-followed ducking','A ducking process in which one signal''s level is automatically reduced in proportion to the amplitude envelope of a control (key) signal, extracted by an envelope follower, so the ducked signal falls and recovers as the key rises and falls. Common in voice-over and side-chain applications, it ties the amount and timing of level reduction directly to the key signal''s loudness contour.','Ducking turns one sound down whenever another sound plays. Here, a circuit traces the loudness shape of the control sound. The more that control sound rises, the more the other sound drops. When the control sound stops, the level comes back.','Following the key''s envelope makes ducking respond smoothly and in proportion to how loud the control signal is, so music dips just enough under speech and recovers naturally rather than switching on and off.','A broadcast or podcast engineer routes a presenter''s mic as the key into a ducker on the music bus, so the music level follows the voice''s envelope, dipping while they speak.','Ducking',ARRAY['Envelope follower','Sidechain','External-sidechain compression','Detector signal','Ducking','Release time']::text[],ARRAY['Setting release too fast so the music jumps back up between words, causing audible pumping.','Using too much gain reduction, so the music disappears instead of sitting politely under the voice.','Keying the ducker from a noisy or unfiltered signal so background sound triggers unwanted dips.']::text[],ARRAY['Ducking a music bed under a radio presenter''s voice automatically.','Lowering a pad under a lead vocal via side-chain in a mix.','Dipping game or podcast background audio whenever dialogue plays.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1a63b6a6-ac10-57e6-97c0-e3deb388e27f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Envelope-followed ducking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1a63b6a6-ac10-57e6-97c0-e3deb388e27f','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1a63b6a6-ac10-57e6-97c0-e3deb388e27f' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b85222d8-0104-5132-8f50-b7c3d92c2491','Exciter return','The return leg of a send-and-return chain that brings the output of an exciter — a psychoacoustic processor that synthesises high-frequency harmonics to add presence, brightness, and clarity — back into the mix to be blended in parallel with the original signal. Because exciters are typically used in small amounts blended under the dry sound, the exciter return controls how much of the added harmonic content reaches the mix.','An exciter adds new high harmonics to a sound to make it brighter and clearer. It often runs on a side path. The exciter return is where that enhanced signal comes back and mixes in. You blend in just a little to add sparkle.','Handling the exciter''s output on a return lets an engineer blend a controlled amount of added harmonic "sparkle" in parallel, keeping the dry signal intact and dialling enhancement to taste.','An engineer sends a vocal or full mix to an aural exciter and brings it back on a return fader, blending a small amount to add air and presence without changing the core tone.','Parallel processing',ARRAY['Aural exciter','Emphasis-driven saturation','Harmonic distortion','Send and return','Parallel processing','Presence']::text[],ARRAY['Blending in too much exciter return, making the sound harsh, fatiguing, and brittle.','Treating the exciter return as an EQ high boost; it adds generated harmonics, not just level in existing highs.','UNSAFE: Adding brightness by turning up the monitors to hear it, increasing high-frequency sound exposure; set the blend at a safe listening level.']::text[],ARRAY['Adding air to a lead vocal by blending a touch of exciter return.','Bringing presence to a dull full mix on a parallel enhancement return.','Enhancing an acoustic guitar''s sparkle with a small exciter blend.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b85222d8-0104-5132-8f50-b7c3d92c2491' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Exciter return'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b85222d8-0104-5132-8f50-b7c3d92c2491','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b85222d8-0104-5132-8f50-b7c3d92c2491' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'abde6d1d-3246-5fc7-91d3-a5507294a98c','External-sidechain compression','A compression setup in which the level detector is fed from a separate "key" or side-chain input rather than the signal being processed, so the gain reduction applied to the main signal is governed by the dynamics of that external source. It underlies techniques such as kick-triggered pumping of a bass or pad, voice-over ducking, and de-essing keyed from a filtered copy of the signal.','Normally a compressor turns a sound down based on that same sound. External side-chain compression uses a different sound to control it. For example, every kick-drum hit can push the bass down. The bass ducks in time with the kick.','Keying compression from an external source lets one element control another''s level, creating rhythmic ducking, space for a vocal, or triggered effects that internal detection cannot produce.','A producer routes the kick to a compressor on the bass or a synth as its side-chain key, so the part ducks on each kick, carving room and adding a pumping groove.','Sidechain & detection',ARRAY['Detector signal','Sidechain','Envelope-followed ducking','Key input','Detector-weighted compression','Ducking']::text[],ARRAY['Forgetting to switch the compressor to the external key input, so it keeps reacting to its own signal.','Setting attack and release without regard to tempo, so the ducking does not breathe with the groove.','Leaving the key source unfiltered so unintended low-level content triggers gain reduction.']::text[],ARRAY['Ducking a bass or pad with the kick drum for a pumping dance-music groove.','Lowering a music bed under a voice-over via an external key.','De-essing by keying a compressor from a band-passed copy of the vocal.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='abde6d1d-3246-5fc7-91d3-a5507294a98c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('External-sidechain compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'abde6d1d-3246-5fc7-91d3-a5507294a98c','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='abde6d1d-3246-5fc7-91d3-a5507294a98c' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '00b8e3a7-a57d-5785-aede-4c367439dddd','Feed-forward compression','A compressor topology in which the level-detector side-chain derives its control signal from the input signal, ahead of the variable-gain element, and then applies the computed gain reduction to that same signal. Because the detector reads the true incoming level rather than the already-processed output, the gain computer''s response can be specified directly, giving precise, programmable control of ratio, knee and timing; most modern VCA and digital compressors are feed-forward designs.','A compressor turns a sound down when it gets too loud. A feed-forward design listens to the sound coming in, before it changes it. This lets the compressor react in an exact, predictable way.','Feed-forward detection lets the gain computer read the actual input level, so precise ratios, knees and attack/release behaviour can be set; it underlies most modern VCA and digital compressors.','An engineer chooses a feed-forward compressor or mode when tight, predictable control is needed, such as bus or mastering compression where the exact ratio and knee matter.','Compressor topology',ARRAY['Feedback compression','Side-chain','Gain reduction','Threshold','Compression ratio','Attack and release']::text[],ARRAY['Assuming feed-forward and feedback compressors sound identical; where the detector taps the signal changes how gain reduction tracks the audio.','Thinking ''feed-forward'' means look-ahead delay; look-ahead is a separate feature, though a feed-forward topology makes it easy to add.','Believing every vintage compressor is feed-forward; many classic optical and variable-mu units are feedback designs.']::text[],ARRAY['Choosing a clean, precise bus compressor for mastering where a predictable ratio and knee are wanted.','Comparing a modern VCA compressor''s tight grab against a vintage feedback unit''s softer action.','Reading a plug-in manual that offers switchable feed-forward and feedback detection modes.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='00b8e3a7-a57d-5785-aede-4c367439dddd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Feed-forward compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '00b8e3a7-a57d-5785-aede-4c367439dddd','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='00b8e3a7-a57d-5785-aede-4c367439dddd' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1455b65f-aa9f-54c0-88c8-5759ed1afa43','Feedback compression','A compressor topology in which the level-detector side-chain senses the output of the variable-gain element, after gain reduction, rather than the input, forming a control loop that settles toward a target level. Because the detector reacts to already-reduced signal, the effective ratio and timing become program-dependent and self-smoothing, a behaviour many classic optical and variable-mu units use for their gentle, musical character.','This compressor listens to the sound after it has already turned it down. It keeps adjusting in a loop until the level settles. That loop gives a soft, smooth sound that many older compressors are loved for.','Sensing the output makes the compressor self-correcting and smooth, trading exact control for a gentle, program-dependent character often prized on vocals and the mix bus.','An engineer reaches for a feedback-style compressor, such as an optical or variable-mu unit, when they want smooth, forgiving gain reduction rather than surgical control.','Compressor topology',ARRAY['Feed-forward compression','Side-chain','Gain reduction','Compression ratio','Attack and release','Program-dependent release']::text[],ARRAY['Assuming a feedback compressor delivers the exact set ratio; the control loop makes its behaviour program-dependent.','Confusing the detector''s internal control loop with acoustic feedback (howlround); the two are unrelated.','Expecting the same fast, precise transient grab that a feed-forward VCA design provides.']::text[],ARRAY['Using a vintage optical compressor for smooth, natural vocal levelling.','Choosing a feedback-detecting unit on the mix bus for gentle glue.','Comparing how a feedback design eases in against a feed-forward design''s tighter response.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1455b65f-aa9f-54c0-88c8-5759ed1afa43' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Feedback compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1455b65f-aa9f-54c0-88c8-5759ed1afa43','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1455b65f-aa9f-54c0-88c8-5759ed1afa43' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6d85f73d-5c2d-5070-8a1c-67112089a76d','Fine equalization','The practice of making small, precise adjustments to a signal''s frequency balance, typically narrow-bandwidth, low-gain boosts or cuts, to correct or refine tone in detail rather than reshape the overall balance. It is used to remove specific resonances or add subtle sheen without markedly changing the broad tonal character.','Fine equalization means changing the tone of a sound in small, careful steps. Instead of big changes, you nudge a narrow range up or down a little. It fixes tiny problems or adds a bit of polish.','It lets an engineer solve narrow tonal problems and add detailed polish precisely, keeping the overall frequency balance intact.','An engineer uses fine equalization to notch a ringing resonance from a snare or add a gentle high-frequency lift to a vocal, using narrow bands and small gains.','Equalization technique',ARRAY['Frequency carving','Frequency-slotting','Notch filter','Parametric EQ','Q (bandwidth)','Surgical EQ']::text[],ARRAY['Using very high-Q boosts too aggressively, creating ringing or an unnatural, pinched tone.','Trying to fix with fine equalization a problem that is really a level, dynamics or arrangement issue.','Making many tiny cuts and boosts without referencing the whole mix, so small moves add up wrongly.']::text[],ARRAY['Notching a single resonant frequency out of a tom while leaving its body intact.','Adding a narrow, gentle lift for air on a lead vocal.','Cleaning a specific hum or whistle out of a location recording.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6d85f73d-5c2d-5070-8a1c-67112089a76d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fine equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6d85f73d-5c2d-5070-8a1c-67112089a76d','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6d85f73d-5c2d-5070-8a1c-67112089a76d' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd23b9cee-0fea-51f5-8658-cefa8b2448f9','Frequency carving','A mixing technique using complementary equalization to cut a frequency region in one source where a competing source needs to dominate, and the reverse in the other, so instruments sharing a range stop masking one another. Carving a pocket in one signal lets the other''s energy in that band read more clearly in the mix.','When two instruments fight over the same tones, the mix gets muddy. Frequency carving cuts those tones in one part so the other can be heard. Each part gets its own space.','It reduces frequency masking between overlapping sources, letting each part sit clearly in the mix instead of simply raising every level.','An engineer dips the low mids of a rhythm guitar where the vocal or bass lives, carving room so those parts cut through.','Equalization technique',ARRAY['Frequency-slotting','Fine equalization','Masking','Complementary EQ','Frequency-dependent compression','Fundamental-band ducking']::text[],ARRAY['Boosting the competing instrument instead of cutting the masker, which just raises overall level and mud.','Carving so aggressively that the source sounds thin or unnatural on its own.','Carving by numbers without listening in the full mix, where masking actually happens.']::text[],ARRAY['Cutting guitar low-mids to make space for vocal presence.','Dipping a pad''s low end so the bass guitar stays defined.','Creating separation between kick and bass by carving one around the other.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d23b9cee-0fea-51f5-8658-cefa8b2448f9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Frequency carving'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd23b9cee-0fea-51f5-8658-cefa8b2448f9','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d23b9cee-0fea-51f5-8658-cefa8b2448f9' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0e1c2720-c3a4-5817-85e4-c81e85adf377','Frequency-dependent compression','Any dynamics processing in which the amount of gain reduction depends on frequency, so different parts of the spectrum are compressed by different amounts. It is realised by splitting the signal into bands and compressing each independently (multiband compression) or by making a filter''s gain level-dependent (dynamic EQ); de-essing is a common special case.','Normal compression turns the whole sound down at once. Frequency-dependent compression can turn down just one range, like harsh highs, and leave the rest alone. A de-esser that tames loud ''s'' sounds works this way.','It lets an engineer control problem frequencies dynamically, only when they get too loud, without permanently changing the overall tone.','An engineer uses a multiband compressor or dynamic equalizer to tame boomy low notes, or a de-esser to reduce sibilance only when it spikes.','Multiband dynamics',ARRAY['Multiband compression','Dynamic EQ','De-esser','Side-chain','Crossover','Frequency-selective kick–bass ducking']::text[],ARRAY['Confusing frequency-dependent compression, which is level-triggered and dynamic, with static EQ that always cuts.','Using too many bands or extreme settings, producing an unnatural, phasey or lifeless sound.','Setting crossover points carelessly so bands overlap and pump against each other.']::text[],ARRAY['De-essing a vocal that only turns harsh on certain sibilant sounds.','Controlling a boomy note on a bass without dulling the whole part.','Taming a resonant frequency on a full mix only when it jumps out.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0e1c2720-c3a4-5817-85e4-c81e85adf377' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Frequency-dependent compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0e1c2720-c3a4-5817-85e4-c81e85adf377','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0e1c2720-c3a4-5817-85e4-c81e85adf377' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '125908f0-4653-597f-b3e3-b2d7dafbb984','Frequency-selective kick–bass ducking','A side-chain ducking technique in which the kick drum triggers gain reduction on the bass only within a chosen frequency band, typically the low range where they overlap, rather than across the full bandwidth. This clears space for the kick in the shared low end while leaving the bass''s upper harmonics and body largely untouched.','Kick drum and bass often clash in the low notes. This trick turns down only the bass''s low range for a moment each time the kick hits. The rest of the bass keeps playing, so it still sounds full.','It resolves kick-versus-bass masking in the low end while preserving the bass''s midrange presence, giving a tighter low end than full-band ducking.','An engineer side-chains a multiband compressor or dynamic equalizer on the bass from the kick, ducking only the low band on each kick hit.','Side-chain ducking',ARRAY['Side-chain compression','Fundamental-band ducking','Frequency-dependent compression','Multiband compression','Ducking','Dynamic EQ']::text[],ARRAY['Ducking the whole bass instead of just the low band, making the bass audibly dip and pump.','Setting the ducked band too wide, so the bass loses body and warmth.','Over-ducking, so the low end sounds hollow between kick hits.']::text[],ARRAY['Tightening a dense electronic low end where kick and sub-bass share the same octave.','Cleaning a rock mix so the kick punches through a busy bass line.','Using a kick-triggered dynamic equalizer to notch the bass''s sub band rhythmically.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='125908f0-4653-597f-b3e3-b2d7dafbb984' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Frequency-selective kick–bass ducking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '125908f0-4653-597f-b3e3-b2d7dafbb984','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='125908f0-4653-597f-b3e3-b2d7dafbb984' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bd0abe01-37f1-5490-af8f-dfd9f54d39b9','Frequency-selective saturation','Harmonic saturation or distortion applied to only a selected part of the spectrum rather than the whole signal, achieved by band-splitting before the saturator or by filtering the saturated signal. It adds harmonics and perceived loudness or warmth to a target band, for example only the lows or only the highs, without dirtying the rest of the source.','Saturation adds a pleasing bit of grit and extra harmonics to a sound. Doing it to just one range lets you warm the low end or add sparkle up top. The rest of the sound stays clean.','It lets an engineer add harmonic richness, presence or loudness exactly where it helps, while keeping fragile or problem bands clean.','An engineer saturates only the upper band of a bass for pick and string detail that reads on small speakers, leaving the sub band clean and controlled.','Harmonic processing',ARRAY['Saturation','Harmonic distortion','Multiband compression','Frequency-dependent compression','Exciter','Frequency carving']::text[],ARRAY['Saturating the sub-bass band heavily, which can add intermodulation mud and eat headroom.','Assuming band-split saturation is phase-neutral; the crossover filters shift phase between bands.','Adding so much that the intended warmth becomes obvious distortion in the full mix.']::text[],ARRAY['Adding bite to a bass''s midrange so it reads on phone speakers while keeping the sub clean.','Warming only the low-mids of a full mix during mastering.','Brightening cymbals with high-band saturation without harshening the whole kit.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bd0abe01-37f1-5490-af8f-dfd9f54d39b9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Frequency-selective saturation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bd0abe01-37f1-5490-af8f-dfd9f54d39b9','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bd0abe01-37f1-5490-af8f-dfd9f54d39b9' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2ed5da5f-83f7-5fca-9c0a-4761ecfd67d3','Frequency-slotting','A mixing approach in which each instrument is given its own primary frequency region, or slot, through equalization and arrangement so that overlapping sources do not compete for the same band. Complementary boosts and cuts place each part in a defined range, reducing masking and improving separation and clarity.','Think of the frequency range as shelves in a cupboard. Frequency-slotting gives each instrument its own shelf so they do not pile on top of each other. This keeps the mix clear.','It organises a dense arrangement across the spectrum so every element stays audible, reducing masking without endless level increases.','An engineer plans where kick, bass, guitars, keys and vocals each sit, then uses equalization, often complementary carving, to keep each in its slot.','Equalization technique',ARRAY['Frequency carving','Fine equalization','Masking','Complementary EQ','Fundamental-band ducking','Frequency-dependent compression']::text[],ARRAY['Treating slotting as rigid rules instead of listening to how parts actually mask each other.','Over-narrowing every part so the mix sounds thin and small.','Forgetting that arrangement and part choice often solve masking better than EQ alone.']::text[],ARRAY['Planning equalization across a busy pop arrangement so vocal, guitars and synths each cut through.','Separating two guitars by giving one the low-mids and the other the presence range.','Fitting a dense layered production together so nothing disappears.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2ed5da5f-83f7-5fca-9c0a-4761ecfd67d3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Frequency-slotting'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2ed5da5f-83f7-5fca-9c0a-4761ecfd67d3','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2ed5da5f-83f7-5fca-9c0a-4761ecfd67d3' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '58bccfef-5c28-50af-93d7-519a7c2ded9a','Fundamental-band ducking','Side-chain ducking that targets the frequency band containing a source''s fundamental, its lowest and usually strongest partial, reducing level there when a triggering source needs that region. It is commonly used so a kick''s fundamental and a bass''s fundamental do not sound simultaneously in the same narrow low band, tightening the low end.','The fundamental is the main, lowest note you hear in a sound. This technique turns down just that main-note range when another sound needs it. It stops two low sounds from clashing.','It clears the crowded fundamental region between competing low-frequency sources so each is heard clearly in turn, rather than masking the other.','An engineer ducks the bass''s fundamental band from the kick, or the reverse, so the two low sources alternate cleanly in the shared octave.','Side-chain ducking',ARRAY['Frequency-selective kick–bass ducking','Side-chain compression','Ducking','Frequency-dependent compression','Masking','Multiband compression']::text[],ARRAY['Ducking too wide a band, so the whole source dips instead of just the fundamental region.','Confusing the fundamental with its harmonics; ducking the wrong band leaves the clash unsolved.','Over-ducking, leaving an audible hole in the low end.']::text[],ARRAY['Separating kick and bass fundamentals that both sit near the same low frequency.','Making room for a vocal''s fundamental against a competing synth pad.','Tightening a mix where two low sources blur together.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='58bccfef-5c28-50af-93d7-519a7c2ded9a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fundamental-band ducking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '58bccfef-5c28-50af-93d7-519a7c2ded9a','d42dcf1d-a730-488c-9633-28e1218563a4',true
