INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'afffa69b-8bdf-5b8b-82e4-80b4b9bfe45e','Gain-reduction chatter','Rapid, unwanted fluctuation of a dynamics processor''s gain reduction as the detector repeatedly crosses its threshold, producing an audible stuttering or fluttering artifact. It is most common in noise gates, where a signal hovering near the threshold makes the gate open and close in quick succession; hysteresis and suitable hold, attack and release times are used to prevent it.','A gate opens to let sound through and closes to mute it. If the sound sits right at the switching point, the gate flips open and shut very fast. That stutter is called chatter.','Naming this fault lets a technician recognise stuttering gain changes and fix them, usually by adding hysteresis or lengthening the hold and release times.','When a gated tom or vocal stutters on quiet tails, the engineer raises hysteresis or hold time, or resets the threshold, to stop the chatter.','Dynamics artifact',ARRAY['Noise gate','Hysteresis','Hold time','Threshold','Gain reduction','Attack and release']::text[],ARRAY['Setting the gate threshold right at the signal level so it constantly flips open and shut.','Using no hysteresis or hold time, so the gate re-triggers on every tiny fluctuation.','Blaming chatter on a faulty unit when it is really a threshold and timing setup issue.']::text[],ARRAY['A gate on a snare stuttering as the drum''s ring decays past the threshold.','A noise gate on a guitar amp chattering during quiet held notes.','Setting up gates at a live show where mics pick up fluctuating background level.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='afffa69b-8bdf-5b8b-82e4-80b4b9bfe45e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gain-reduction chatter'),'[^a-z0-9]','','g'));
