INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '79984229-8606-5d7f-be42-904bd4e6a2f8','Gain-reduction sharing','A configuration in which two or more channels apply the same gain-reduction control signal, so they are turned down together by an equal amount rather than independently. It is used to preserve stereo image or internal balance, for example by stereo-linking a compressor''s two channels or grouping several channels to one detector, so relative levels stay constant while dynamics are controlled.','The left and right of a stereo track may be turned down by different amounts. Then the sound seems to shift sideways. Gain-reduction sharing makes channels turn down by the same amount together. This keeps the stereo picture steady.','Sharing one control signal keeps balance and stereo image stable during compression and lets a group of sources move as one, instead of drifting apart.','An engineer stereo-links a bus compressor, or side-chains several drum channels to a common detector, so they duck together and the image stays put.','Compressor linking',ARRAY['Stereo linking','Side-chain','Bus compression','Gain reduction','Feed-forward compression','Ducking']::text[],ARRAY['Leaving a stereo compressor un-linked, so uneven gain reduction makes the image wander.','Assuming linked channels can still be balanced independently after the detector; they move together.','Sharing gain reduction across unrelated sources, causing unwanted pumping between them.']::text[],ARRAY['Stereo-linking a mix-bus compressor so the centre image stays solid.','Grouping a drum kit to one compressor so the whole kit breathes together.','Linking channels of a surround stem so gain moves match across the array.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='79984229-8606-5d7f-be42-904bd4e6a2f8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gain-reduction sharing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '79984229-8606-5d7f-be42-904bd4e6a2f8','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='79984229-8606-5d7f-be42-904bd4e6a2f8' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1450fbdc-b802-5b43-9e9a-e4d693cd741a','Glassiness','A subjective timbral descriptor for a bright, hard, clear high-frequency character that suggests a smooth, reflective glass-like sheen. Used positively it denotes crystalline clarity and detail in the treble; used negatively it denotes a brittle, cold or over-bright quality, sometimes a by-product of aggressive high-frequency equalization, compression or digital processing.','Glassiness is a bright, shiny, hard sound in the high notes, like light off glass. A little can sound clear and sparkly. Too much sounds cold and brittle.','The word gives engineers a shared way to describe a specific bright treble character, so they can aim for it or avoid it when shaping tone.','An engineer may add a gentle high shelf or exciter for a pleasing glassy sheen on a pad, or pull back the highs when a vocal turns brittle and glassy.','Timbral descriptor',ARRAY['Grain','Brittleness','Harshness','Air band','Exciter','Fine equalization']::text[],ARRAY['Chasing a glassy sheen with heavy high boosts until the sound becomes harsh and fatiguing.','Assuming glassiness is always desirable; in context it can read as thin or cold.','Confusing pleasant glassy detail with sibilance or distortion in the highs.']::text[],ARRAY['Describing the bright, crystalline top of a synth pad or electric piano.','Noting that heavy limiting has made a mix brittle and glassy.','Communicating a desired sparkly high end to a mastering engineer.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1450fbdc-b802-5b43-9e9a-e4d693cd741a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Glassiness'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1450fbdc-b802-5b43-9e9a-e4d693cd741a','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1450fbdc-b802-5b43-9e9a-e4d693cd741a' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1ccc597c-790f-5808-94e2-5fe783dbb5ac','Grain','A subjective timbral descriptor for a fine, textured roughness in a sound, as if made of small particles rather than a smooth surface. It can be a pleasing analogue-style character from harmonic saturation or tape, or an unwanted artifact from low-level distortion, aggressive processing, or coarse digital quantization.','Grain is a fine, rough texture in a sound, a bit like sandpaper next to smooth glass. A little can add analogue-style character and life. Too much sounds gritty or harsh.','The term lets engineers describe a specific rough texture so they can add it for character or reduce it when it becomes an unwanted artifact.','An engineer may add subtle saturation for pleasing grain on a vocal, or trace grain back to over-compression, distortion or low-bit processing and clean it up.','Timbral descriptor',ARRAY['Glassiness','Saturation','Harmonic distortion','Quantization','Harshness','Frequency-selective saturation']::text[],ARRAY['Adding so much saturation that pleasant grain becomes obvious, harsh distortion.','Confusing digital quantization grain, a fault, with musical analogue grain.','Assuming all grain is bad; some is added deliberately for warmth and character.']::text[],ARRAY['Describing the gritty texture a tape or saturation plug-in adds to a mix.','Diagnosing unwanted grain from over-processing or low-resolution audio.','Asking for a smoother, less grainy vocal from a mastering pass.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1ccc597c-790f-5808-94e2-5fe783dbb5ac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Grain'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
