INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8e369c27-830c-5075-9dc8-97f25e628883','Hinge-point compression','Compression described in terms of the point on the input–output transfer curve where the response changes slope, the hinge point, normally the threshold and its knee, about which the curve bends. Below the hinge the signal passes at unity slope; above it the ratio sets a shallower slope, so the whole gain-reduction behaviour is defined relative to that pivot.','A compressor''s response can be drawn as a line that bends at one point. That bend, the hinge point, is where it starts turning the sound down. Sounds below it pass through; louder sounds get squeezed.','Thinking in terms of the hinge point makes clear where compression begins and how hard it acts, helping an engineer set threshold, knee and ratio to shape dynamics predictably.','An engineer sets the threshold, the hinge, so only peaks above it are compressed, then uses ratio and knee to control how sharply the curve bends there.','Transfer characteristic',ARRAY['Threshold','Knee','Compression ratio','Gain reduction','Transfer function','Soft knee']::text[],ARRAY['Confusing the hinge point (threshold and knee) with make-up gain or output level.','Assuming a hard bend at the hinge; a soft knee rounds the transition over a range of levels.','Setting the hinge too low, so quiet passages are compressed almost as much as loud ones.']::text[],ARRAY['Explaining on a compressor''s transfer graph where gain reduction starts.','Setting threshold and knee so only vocal peaks are controlled.','Comparing a hard-knee sharp hinge with a soft-knee gradual one.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8e369c27-830c-5075-9dc8-97f25e628883' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hinge-point compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8e369c27-830c-5075-9dc8-97f25e628883','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8e369c27-830c-5075-9dc8-97f25e628883' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fd988f3b-aec4-5d6b-aff1-780cd0ad37c2','Hold-and-release compression','A compressor (or limiter) behaviour in which, once the detected level falls back below threshold, the current gain reduction is held constant for a set hold time before the release stage begins returning gain toward unity. The hold interval bridges brief level dips so recovery does not restart during momentary drops, yielding a steadier gain-reduction envelope than release timing alone.','This tool turns down loud sounds. When the loud part ends, it waits a set time before letting the level rise again. That short wait keeps the sound steady instead of jumpy.','It prevents the processor from starting to recover during short gaps in the signal, avoiding the level surging and dipping (pumping or breathing) on material with rapid dips between peaks.','An engineer dials in a hold time so gain reduction stays put through brief gaps between words, notes, or drum hits, then releases smoothly, useful on vocals, bass, and busy drum submixes.','Compression',ARRAY['Release time','Hold time','Attack time','Threshold','Pumping','Gain reduction']::text[],ARRAY['Setting the hold time so long that the compressor never recovers between phrases, choking the level.','Confusing hold, which freezes gain reduction, with release, which is the rate gain returns to unity.','Assuming every compressor offers a hold control; many provide only attack and release.']::text[],ARRAY['Smoothing a vocal that has short gaps between words without the level pumping up in each gap.','Holding limiter gain reduction across a fast run of drum transients before releasing.','Steadying a bass line whose notes leave brief silences that would otherwise trigger early release.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fd988f3b-aec4-5d6b-aff1-780cd0ad37c2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hold-and-release compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fd988f3b-aec4-5d6b-aff1-780cd0ad37c2','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fd988f3b-aec4-5d6b-aff1-780cd0ad37c2' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '50e0cf89-31a2-5247-aa3b-e257991f98ce','Hold-time ducking','Ducking (side-chain gain reduction of one signal driven by the level of a key signal) in which, after the key signal drops below threshold, the attenuation is held for a set hold time before it releases back to full level. The hold keeps the ducked signal down through brief pauses in the key source so the level does not surge up between words or phrases.','Ducking lowers background music when someone talks. Hold-time ducking keeps the music down for a short set time after each word. That stops the music jumping up in the tiny gaps between words.','It exists so the ducked source stays smoothly attenuated across the natural gaps in speech or a lead part, instead of bobbing up and down every time the key signal briefly falls silent.','A broadcast or podcast engineer sets a hold time on a ducker so music stays lowered through pauses in narration, only recovering once the presenter has clearly finished a sentence.','Ducking',ARRAY['Ducking','Side-chain','Key input','Hold time','Release time','Threshold']::text[],ARRAY['Setting no hold time, so the music surges up in every short gap between spoken words.','Setting the hold so long that the music never returns during natural speech pauses.','Confusing the hold time with the release time; hold freezes the duck, release ends it.']::text[],ARRAY['Keeping bed music lowered through pauses in a radio presenter''s speech.','Ducking a music track under voice-over narration in a video edit without the level bobbing.','Holding a synth pad down under a lead vocal across short breath gaps.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='50e0cf89-31a2-5247-aa3b-e257991f98ce' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hold-time ducking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '50e0cf89-31a2-5247-aa3b-e257991f98ce','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='50e0cf89-31a2-5247-aa3b-e257991f98ce' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8bf011ab-f54b-5f0a-9f07-f30a5010e1ae','Honk','A subjective descriptor for an unpleasant, nasal, hollow midrange emphasis or resonance, typically heard in the region of roughly a few hundred hertz up to around one kilohertz, that makes a source sound as if it is speaking through a tube or cupped hands. In processing it can be provoked or exaggerated when heavy compression raises the midrange, or by resonances in instruments, horns, or rooms.','Honk is a nasal, hollow midrange tone, like talking through a tube or cupped hands. It can stand out when heavy compression pushes up the middle of the sound. Engineers usually try to reduce it.','The term gives engineers a shared word for a specific offensive midrange colour so they can identify it by ear and tame it, usually by easing compression or notching the offending band.','Hearing honk on a compressed guitar, horn, or vocal, a technician backs off the compression or sweeps an equaliser to find and cut the resonant midrange band.','Tonal artifact',ARRAY['Pumping','Coloration','Resonance','Midrange','Compression','Gain reduction']::text[],ARRAY['Blaming honk entirely on the microphone when heavy compression or a room resonance is lifting the midrange.','Cutting far too wide a band to remove honk, hollowing out the whole midrange and thinning the source.','Confusing honk (nasal midrange) with harshness (edgy upper mids and highs); they sit in different bands.']::text[],ARRAY['Taming a nasal, honky quality on a heavily compressed electric guitar.','Reducing midrange honk on a saxophone or trumpet that resonates in a small room.','Cleaning up a vocal that sounds boxy and honky after aggressive bus compression.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8bf011ab-f54b-5f0a-9f07-f30a5010e1ae' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Honk'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8bf011ab-f54b-5f0a-9f07-f30a5010e1ae','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8bf011ab-f54b-5f0a-9f07-f30a5010e1ae' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '20f12688-14fe-5e70-831a-74c2cb34a37b','Interlocking compression','An arrangement in which two or more compressor channels are interlinked so that a shared or summed control signal governs their gain reduction, making them act together rather than independently. Linking (interlocking) the channels applies identical gain reduction across them, which on a stereo or multichannel signal preserves the image and balance that independent per-channel compression would shift.','Stereo sound uses a left and a right channel. Interlocking ties their compressors together so both turn down by the same amount. That keeps the sound from drifting to one side.','It exists to stop a loud sound on one channel from pulling only that side down, which would move the stereo image; linking makes both channels reduce gain equally and hold the picture steady.','An engineer engages the stereo-link (interlock) switch on a compressor so a hard hit panned to one side does not shift the whole mix toward the other side.','Compression',ARRAY['Stereo link','Gain reduction','Side-chain','Compressor','Threshold','Bus compression']::text[],ARRAY['Leaving stereo channels unlinked, so a one-sided transient drags the image off centre with each hit.','Assuming linking averages the audio itself; it links only the detection and gain-reduction control.','Interlocking channels that should stay independent, losing wanted separate control of each source.']::text[],ARRAY['Linking the two channels of a bus compressor so the stereo mix stays centred under loud transients.','Interlocking left and right on a stereo drum overhead compressor to hold the image.','Coupling surround channels so gain reduction is applied uniformly across the group.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='20f12688-14fe-5e70-831a-74c2cb34a37b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Interlocking compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '20f12688-14fe-5e70-831a-74c2cb34a37b','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='20f12688-14fe-5e70-831a-74c2cb34a37b' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c6cf7de0-2d75-5db4-ae31-f9979cc22ad3','Inverse ducking','A side-chain process, the opposite of conventional ducking, in which the target signal''s level is raised (or a gate opened to pass it) while a key signal is present, rather than lowered. Also called reverse or upward ducking, it turns a source up in response to a trigger and lets it fall back when the trigger stops.','Normal ducking turns a sound down when a trigger plays. Inverse ducking does the opposite: it turns the sound up while the trigger is there. When the trigger stops, the sound drops back down.','It exists to bring a supporting element forward only when another part is playing, for example lifting a reverb or a layer during a lead phrase and letting it recede in the gaps.','An engineer keys an inverse ducker from a vocal so a doubling layer or effect return rises only while the singer performs, then settles back between lines.','Ducking',ARRAY['Ducking','Side-chain','Key input','Upward compression','Threshold','Gate']::text[],ARRAY['Confusing inverse ducking (level rises with the key) with normal ducking (level falls with the key).','Setting extreme gain changes so the source pumps obviously up and down with the trigger.','Forgetting to filter the key input, so unwanted low-level noise keeps triggering the rise.']::text[],ARRAY['Lifting a reverb or delay layer only while the lead vocal is singing.','Bringing a support synth forward during a guitar phrase and dropping it in the gaps.','Raising a room-mic blend on drums only during loud fills.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c6cf7de0-2d75-5db4-ae31-f9979cc22ad3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Inverse ducking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c6cf7de0-2d75-5db4-ae31-f9979cc22ad3','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c6cf7de0-2d75-5db4-ae31-f9979cc22ad3' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd6ced7aa-5b77-5f17-bad5-36b42cd31b9b','Keyed compression','Compression in which the gain-reduction detector is driven by a separate key (side-chain) signal, or by a filtered version of the input, rather than by the full signal being processed. Routing an external key into the detector makes the compressor respond to something other than the audio passing through it, so one source can control the level of another.','A normal compressor listens to the same sound it turns down. Keyed compression lets it listen to a different sound instead. That other sound decides when the level goes down.','It exists so the compressor can be triggered by a chosen control source, enabling effects such as ducking one track from another or making compression react only to selected frequencies.','An engineer patches a kick drum into a bass compressor''s key input so the bass dips on each kick, or filters the side-chain so the compressor reacts mainly to sibilance or low end.','Side-chain processing',ARRAY['Side-chain','Key input','Ducking','De-esser','Threshold','Compressor']::text[],ARRAY['Confusing the key (side-chain) input with the audio input and routing the signal to the wrong jack.','Forgetting a key-listen or side-chain monitor is engaged, so no audio passes to the output.','Expecting the key signal to be heard; it only controls gain reduction and is not passed to the output.']::text[],ARRAY['Ducking a bass with a kick drum patched into the compressor''s key input.','Filtering the side-chain so the compressor reacts to sibilance for de-essing.','Triggering compression on a pad from a lead vocal for automatic space in a mix.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d6ced7aa-5b77-5f17-bad5-36b42cd31b9b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Keyed compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd6ced7aa-5b77-5f17-bad5-36b42cd31b9b','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d6ced7aa-5b77-5f17-bad5-36b42cd31b9b' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '12f6bf3f-e7ce-5569-9773-71c17df961f5','Keyed expansion','Downward expansion or gating in which the detector that opens and closes the processor is driven by an external key (side-chain) signal rather than the audio being processed. The key decides when the gate or expander passes the through signal, so one source can gate another in time with it.','A gate lets sound through only when it is loud enough. Keyed expansion lets a different sound decide when the gate opens. So one track can switch another track on and off.','It exists so gating can be triggered by a chosen source, letting a technician shape or replace a signal in rhythm with another, or gate an instrument only when a trigger fires.','An engineer keys a gate on a synth pad from a hi-hat pattern so the pad chops in time, or triggers a gate on a tom mic from a clean tom sample to reject spill between hits.','Side-chain processing',ARRAY['Expander','Gate','Side-chain','Key input','Threshold','Keyed compression']::text[],ARRAY['Confusing keyed expansion (an external trigger opens the gate) with normal gating on the signal''s own level.','Leaving the through signal absent, so the gate opens on the key but there is nothing to pass.','Not tightening the range, so the gate leaks the through signal even when the key is silent.']::text[],ARRAY['Chopping a sustained synth pad in time with a hi-hat pattern using a keyed gate.','Gating a tom mic from a clean trigger to reject bleed between tom hits.','Adding a rhythmic tremolo effect by keying a gate from a drum loop.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='12f6bf3f-e7ce-5569-9773-71c17df961f5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Keyed expansion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
