INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5619b97a-3909-5fdb-8499-7f3383ceacb3','Level-dependent release','A compressor release characteristic (also called program-dependent or adaptive release) in which the release time is not fixed but varies with the signal, typically releasing quickly after brief transients and more slowly after sustained loud passages. The detector adapts its recovery to the material so the processor smooths steady content while not clamping down on transient-rich signals.','Release is how fast a compressor lets the level back up. Level-dependent release changes that speed by itself. It recovers fast after short spikes and slowly after long loud parts.','It exists to give smoother, more transparent compression across varied material without the engineer constantly adjusting the release, reducing pumping on transients while keeping sustained sounds steady.','An engineer chooses an auto or program-dependent release mode on a compressor for a dynamic vocal or full mix, letting the unit adapt instead of setting one compromise release time.','Compression',ARRAY['Release time','Program-dependent release','Attack time','Pumping','Compressor','Leveling amplifier']::text[],ARRAY['Assuming auto or program-dependent release removes all pumping; heavy settings can still pump.','Expecting one fixed release value from an adaptive mode; the time changes with the signal.','Fighting an adaptive release with a very fast manual attack and getting distortion on low frequencies.']::text[],ARRAY['Using auto-release on a bus compressor to smooth a mix with mixed transient and sustained content.','Compressing a dynamic lead vocal where fixed release either pumps or sounds sluggish.','Relying on an optical compressor''s natural program-dependent recovery on a bass part.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5619b97a-3909-5fdb-8499-7f3383ceacb3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Level-dependent release'),'[^a-z0-9]','','g'));
