SELECT '5619b97a-3909-5fdb-8499-7f3383ceacb3','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5619b97a-3909-5fdb-8499-7f3383ceacb3' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '64dfb398-f7e2-5302-b18d-9c7b8b377dc9','Level-to-peak compression chain','A serial dynamics arrangement in which a level (average/RMS-sensing) compressor for gentle overall level control feeds a faster peak-sensing compressor or limiter that catches the transients the first stage lets through. Splitting the work between an averaging stage and a peak stage controls both the general loudness and the fast peaks with fewer artifacts than one aggressive processor.','This chain uses two compressors in a row. The first one gently evens out the overall loudness. The second one quickly catches the sharp spikes the first one misses.','It exists to divide dynamic control between slow, average leveling and fast peak catching, so each stage does a modest job and the result sounds more natural than one heavy-handed unit.','A mix or mastering engineer sets a slow RMS-style compressor for broad level and follows it with a fast peak limiter to stop overshoots, each doing only a few decibels of work.','Serial dynamics',ARRAY['Serial compression','RMS detection','Peak detection','Limiter','Compressor','Gain reduction']::text[],ARRAY['Reversing the order or overloading the peak stage so it does all the work and pumps.','Confusing average (RMS) detection, which tracks loudness, with peak detection, which tracks fast spikes.','UNSAFE: Judging the loudness result at high monitor levels for long periods, risking hearing damage; monitor at a safe, calibrated level.']::text[],ARRAY['Leveling a vocal with a gentle RMS compressor, then a fast limiter to catch stray peaks.','Controlling a full mix with an averaging bus compressor into a peak limiter before the master.','Taming a dynamic bass with slow overall compression followed by fast peak limiting.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='64dfb398-f7e2-5302-b18d-9c7b8b377dc9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Level-to-peak compression chain'),'[^a-z0-9]','','g'));
