SELECT '64dfb398-f7e2-5302-b18d-9c7b8b377dc9','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='64dfb398-f7e2-5302-b18d-9c7b8b377dc9' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ea99f44a-f327-5d42-9c4b-3323b07bd367','Leveling amplification','Automatic gain leveling performed by a leveling amplifier, a variable-gain amplifier (classically using an optical gain-reduction element) that gently and continuously evens out programme dynamics with a smooth, generally low-ratio, program-dependent limiting action. Its slow, self-adjusting attack and release smooth long-term level changes rather than tightly clamping individual transients.','A leveling amplifier turns a signal''s volume up and down on its own to keep it even. It works slowly and gently, so the changes are hard to hear. It smooths the overall level rather than grabbing every spike.','It exists to hold a source at a consistent level with a musical, unobtrusive action, valued on vocals and bass where transparent, hands-off level control matters more than tight peak limiting.','An engineer patches a leveling amplifier such as an optical unit across a vocal or bass to smooth its dynamics gently, adjusting gain reduction until the level sits steady in the mix.','Compression',ARRAY['Compressor','Optical compressor','Program-dependent release','Gain reduction','Limiter','Level-dependent release']::text[],ARRAY['Expecting a leveling amplifier to catch fast peaks; its slow action smooths overall level, not transients.','Cranking gain reduction hard on an optical leveler, losing its natural, transparent character.','Assuming its attack and release are fixed; the optical cell''s timing changes with the programme.']::text[],ARRAY['Smoothing a lead vocal''s level gently with an optical leveling amplifier before further processing.','Evening out a bass performance so it sits steadily under the mix.','Using slow, transparent leveling on an acoustic guitar to control dynamics without obvious pumping.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ea99f44a-f327-5d42-9c4b-3323b07bd367' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Leveling amplification'),'[^a-z0-9]','','g'));
