SELECT 'ea99f44a-f327-5d42-9c4b-3323b07bd367','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ea99f44a-f327-5d42-9c4b-3323b07bd367' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fedf754f-059e-50b6-a4c5-afad666665d5','Limit-to-clip chain','A serial peak-control arrangement in which a limiter reduces peaks first and a clipper then flattens any remaining fast overshoots that pass the limiter, together maximising loudness while holding the signal under a ceiling. Sharing the peak work lets the limiter handle most reduction transparently while the clipper shaves brief spikes the limiter would otherwise have to grab hard.','A limiter holds the loudest peaks down to a set ceiling. A clipper chops off any sharp spikes that slip past. Using them in a row lets a track get louder while staying under the limit.','It exists to push loudness further than a limiter alone can cleanly manage, by letting a clipper remove the fastest peaks so the limiter does not have to react so aggressively.','A mastering engineer places a clipper before or after a limiter to trim short transients, gaining loudness on drums or a full mix while keeping peaks below the ceiling.','Limiting',ARRAY['Limiter','Clipping','Brickwall limiter','True peak','Loudness','Peak detection']::text[],ARRAY['Clipping so hard that audible distortion and harshness appear instead of a subtle loudness gain.','Confusing a limiter, which turns gain down smoothly, with a clipper, which flatly cuts the waveform.','UNSAFE: Chasing maximum loudness at high monitor levels for long sessions, risking hearing damage; monitor at a safe, calibrated level.']::text[],ARRAY['Adding loudness to a drum bus by clipping stray transients ahead of a limiter.','Mastering a track to a target loudness with a clipper trimming peaks before the brickwall limiter.','Controlling sharp peaks on a bass so the limiter can work more gently.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fedf754f-059e-50b6-a4c5-afad666665d5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Limit-to-clip chain'),'[^a-z0-9]','','g'));
