SELECT 'fedf754f-059e-50b6-a4c5-afad666665d5','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fedf754f-059e-50b6-a4c5-afad666665d5' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '05a28d80-d023-5566-9bea-b7d7c466212d','Lookahead ducking','Ducking that uses a look-ahead delay, in which the audio path is delayed by a few milliseconds while the side-chain detector reads the key signal ahead of the delayed audio, so the attenuation can be in place before the triggering transient arrives. The anticipation lets the duck engage smoothly and on time rather than lagging behind a fast key onset.','Lookahead delays the sound by a tiny amount. That lets the ducker see a trigger coming before it plays. So the volume is already turned down when the trigger hits.','It exists so ducking can react to sudden triggers without a late, clumsy grab, catching sharp onsets cleanly by preparing the gain reduction slightly in advance.','An engineer enables look-ahead on a ducker keyed by a percussive or spoken trigger so the duck lands exactly on the onset instead of a moment late.','Ducking',ARRAY['Ducking','Lookahead','Side-chain','Key input','Attack time','Latency']::text[],ARRAY['Forgetting that look-ahead adds latency, which must be compensated when tracking or in live use.','Setting look-ahead so long that the duck begins audibly before the trigger sound.','Assuming look-ahead works on live inputs where the future signal is not yet available.']::text[],ARRAY['Ducking music precisely under a sharp spoken cue using a short look-ahead.','Catching a percussive key onset so the duck lands on the beat, not after it.','Smoothing ducking on fast transients in a broadcast bed mix.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='05a28d80-d023-5566-9bea-b7d7c466212d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lookahead ducking'),'[^a-z0-9]','','g'));
