SELECT '05a28d80-d023-5566-9bea-b7d7c466212d','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='05a28d80-d023-5566-9bea-b7d7c466212d' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a8bccb75-de32-5b9a-b49b-35ccf6542c3e','Low-ratio cascading','A serial (cascaded) compression technique in which several compressors are chained, each set to a low ratio so it applies only a small amount of gain reduction, and their modest actions sum to substantial overall control. Spreading the work across stages produces smoother, less audible dynamics control than a single compressor doing all the reduction at a high ratio.','Instead of one compressor squeezing hard, this uses several in a row. Each one turns the level down just a little. Their small amounts add up, and the result sounds more natural.','It exists to achieve strong, transparent level control by letting each stage do gentle gain reduction, avoiding the pumping and harshness a single aggressive compressor can produce.','An engineer chains two or three compressors on a vocal or mix, each doing only a few decibels of gain reduction at a low ratio, for smoother control than one hard compressor.','Serial dynamics',ARRAY['Serial compression','Ratio','Gain reduction','Compressor','Bus compression','Level-to-peak compression chain']::text[],ARRAY['Setting each stage too hard, so the cumulative gain reduction over-compresses and pumps.','Confusing cascading (serial, in a row) with parallel compression (blended alongside the dry signal).','Ignoring the added noise or coloration each extra stage in the chain can contribute.']::text[],ARRAY['Smoothing a dynamic lead vocal with two gentle compressors in series instead of one hard one.','Controlling a mix bus with light gain reduction split across two low-ratio compressors.','Leveling a bass with cascaded low-ratio stages for a natural, even result.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a8bccb75-de32-5b9a-b49b-35ccf6542c3e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Low-ratio cascading'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a8bccb75-de32-5b9a-b49b-35ccf6542c3e','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a8bccb75-de32-5b9a-b49b-35ccf6542c3e' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '72433965-8924-5f20-8fd7-f6d1b9d65b9d','Macrodynamic compression','Compression aimed at macrodynamics, the long-term, section-to-section level variations of a performance or programme (such as verse-to-chorus changes), as distinct from microdynamics, the short-term transient detail. It uses slow attack and release so it rides overall level over seconds without flattening individual transients.','Music has big level changes between sections, like a quiet verse and a loud chorus. Macrodynamic compression smooths those big, slow changes. It works slowly, so it does not squash the small sharp hits.','It exists to even out the broad level differences between passages so a piece sits more consistently, while preserving the punch and detail carried by fast transients.','A mastering engineer applies slow, gentle compression to reduce level jumps between sections of a track, sometimes alongside automation, without dulling transient impact.','Mastering dynamics',ARRAY['Microdynamics','Compressor','Attack time','Release time','Gain reduction','Leveling amplifier']::text[],ARRAY['Using fast attack and release for macrodynamic control, which squashes transients instead of riding sections.','Confusing macrodynamics (long-term, section-level) with microdynamics (short-term transient detail).','Over-compressing the macro level so loud and quiet sections lose all contrast and the music sounds flat.']::text[],ARRAY['Evening out verse-to-chorus level jumps on a mastered song with slow compression.','Smoothing long-term level drift across a live concert recording.','Balancing section-to-section loudness on an album so tracks feel consistent.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='72433965-8924-5f20-8fd7-f6d1b9d65b9d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Macrodynamic compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '72433965-8924-5f20-8fd7-f6d1b9d65b9d','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='72433965-8924-5f20-8fd7-f6d1b9d65b9d' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5ceaa50a-5bc7-55df-af5b-e73c2dca0bed','Manhattan compression','A common nickname for parallel (New York) compression: a technique in which the source signal is split into two paths, one heavily compressed and one left dry, and the two are then blended together. The compressed path raises the level of quieter detail while the dry path preserves the original transients and peaks, increasing density and apparent loudness without the peaks being crushed.','You send a track two ways at once. One copy is squashed hard, the other stays untouched. Mixing them adds weight and keeps the punch. It is just another name for New York, or parallel, compression.','It lets an engineer add body, sustain and apparent loudness to a source while keeping its natural transients, because the untouched dry path carries the peaks that heavy compression would otherwise flatten.','An engineer sets up a parallel bus with an aggressive compressor, then blends that bus under the dry drum or vocal to taste, watching that the summed level does not clip.','Parallel processing',ARRAY['New York compression','Parallel compression','Downward compression','Upward compression','Makeup gain','Aux send']::text[],ARRAY['Thinking it is a distinct process from parallel or New York compression, when all three names describe the same split-and-blend technique.','Phase or timing offset between the dry and compressed paths, which causes comb filtering when the two are summed.','UNSAFE: Chasing the extra density by pushing monitor levels ever higher, raising noise-induced hearing loss risk; keep monitoring within NIOSH/OSHA daily exposure limits.']::text[],ARRAY['Thickening a drum bus while keeping the snare and kick attack intact.','Adding sustain and presence to a lead vocal without audible pumping.','Increasing the apparent loudness of a room-mic bus in a live-to-two mix.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5ceaa50a-5bc7-55df-af5b-e73c2dca0bed' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Manhattan compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5ceaa50a-5bc7-55df-af5b-e73c2dca0bed','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5ceaa50a-5bc7-55df-af5b-e73c2dca0bed' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '94dbacde-55b3-505f-b07a-f07e045e794d','Masking-release processing','Any processing applied specifically to reduce auditory masking, the effect whereby a louder or spectrally overlapping sound renders another harder to hear. Techniques include static or dynamic equalization that carves a frequency pocket for the masked element, and sidechain-triggered gain reduction (ducking) that lowers the masker only while the masked signal is present, so the two coexist more clearly.','Masking is when one sound hides another, like a truck drowning out speech. This processing carves space so both are heard. It might dip the loud sound or scoop a gap in its tone.','It exists to restore clarity and intelligibility in a dense mix by giving each masked element its own audible space, rather than simply turning everything up.','An engineer uses a dynamic equalizer or a sidechained band to dip a guitar''s low-mids only when the vocal sings, so the vocal stays clear without pushing its fader.','Frequency management',ARRAY['Auditory masking','Dynamic equalization','Ducking','Sidechain','Micro-equalization','Mud']::text[],ARRAY['Boosting the masked element instead of reducing the masker, which just raises overall level and can worsen the clash.','Cutting too wide or too deep, so the masker loses its own character while chasing clarity.','Ignoring that masking is strongest between sounds close in frequency, and trying to fix a low-mid clash with a high-frequency move.']::text[],ARRAY['Making a lead vocal sit clearly over a thick synth pad.','Separating a kick drum and bass guitar that share the same low-frequency range.','Keeping dialogue intelligible over a music bed in a broadcast or film mix.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='94dbacde-55b3-505f-b07a-f07e045e794d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Masking-release processing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '94dbacde-55b3-505f-b07a-f07e045e794d','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='94dbacde-55b3-505f-b07a-f07e045e794d' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3ef23fe0-e2f2-5cb6-9262-631dd4570347','Match equalization','An equalization process in which the average frequency spectrum of a target signal is measured and reshaped to approximate the spectrum of a chosen reference. A match-EQ tool captures a reference spectral profile, analyses the target, and generates a multi-band corrective curve that pushes the target''s tonal balance toward that of the reference.','A match EQ, or equalizer, copies the tone balance of one recording onto another. It listens to a track you like, then shapes your track to sound tonally similar. It builds the fix curve for you.','It exists to speed up tonal matching, letting an engineer align the spectral balance of a mix, edit or dialogue take to a reference without dialling every band by ear.','A mastering or post engineer captures the spectrum of an approved reference, then applies the generated curve to a new song or scene so the tonal balance matches across a release or episode.','Equalization',ARRAY['Equalization','Micro-equalization','Reference track','Spectral analysis','Mastering','Tonal balance']::text[],ARRAY['Treating the generated curve as final rather than a starting point, ignoring that the source material and arrangement differ from the reference.','Matching to a poorly chosen or heavily processed reference, which imprints its faults onto the target.','Accepting extreme boosts the curve suggests at frequencies with little content, which raises noise and harshness.']::text[],ARRAY['Aligning the tone of songs recorded in different sessions for one album.','Matching dialogue recorded on different days or microphones within a scene.','Nudging a mix toward a client''s chosen commercial reference during mastering.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3ef23fe0-e2f2-5cb6-9262-631dd4570347' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Match equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3ef23fe0-e2f2-5cb6-9262-631dd4570347','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3ef23fe0-e2f2-5cb6-9262-631dd4570347' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '768f8701-2b7a-5d07-bed8-52a02bf60be9','Micro-equalization','The practice of making very small equalization adjustments, typically fractions of a decibel up to a couple of decibels, to refine tonal balance subtly rather than to correct obvious problems. It is used for final polishing, where cumulative small moves shape the overall balance without audibly altering any single element.','Micro-equalization means tiny tone tweaks, often less than one decibel. Each move is almost too small to notice alone. Together they gently polish how a mix sits. An equalizer, or EQ, sets tone.','It exists for the fine, final stage of tonal shaping, letting an engineer nudge balance without the side effects of large boosts or cuts such as phase shift or obvious coloration.','During mixing or mastering an engineer applies gentle, broad EQ moves of well under a decibel across a bus or the master to settle the tonal balance.','Equalization',ARRAY['Equalization','Match equalization','Tonal balance','Mastering','Q factor','Broadband EQ']::text[],ARRAY['Assuming a change under a decibel does nothing and reaching instead for large boosts that unbalance the mix.','Stacking many small boosts that quietly sum into a large, coloured overall curve.','Making micro moves in solo without checking them in the full mix, where their real effect is judged.']::text[],ARRAY['Final tonal polish on a master bus before delivery.','Gently seating a vocal in a mix without an obvious EQ move.','Matching the subtle tonal feel of tracks across an album.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='768f8701-2b7a-5d07-bed8-52a02bf60be9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Micro-equalization'),'[^a-z0-9]','','g'));
