WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8b3c0508-a951-585f-bd9d-18f8df169d68' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bbf94cb8-cc61-5d37-a143-87db162de862','Parallel blend cancellation','Partial phase cancellation that occurs when a processed (parallel) copy of a signal is summed with the unprocessed dry path while the two are not phase- or time-aligned, so frequencies that are out of phase between the paths subtract rather than add. Latency introduced by the parallel processor, or phase shift from equalization or nonlinear processing, is a common cause, and the result ranges from a hollow, comb-filtered tone to near-complete loss of specific frequencies.','Parallel processing sends a copy of the sound through effects, then mixes it back with the untouched original. If the copy is delayed or phase-shifted, some frequencies fight and cancel out. This can make the mix sound thin or hollow.','Naming this failure mode helps engineers watch for and prevent unwanted level loss and tonal change when combining a wet copy with a dry signal.','An engineer who hears a parallel bus thin out checks for plug-in latency or phase differences, then time-aligns or flips polarity to restore full sound.','Phase and alignment',ARRAY['Parallel-path comb filtering','Phase cancellation','Latency compensation','Polarity','Parallel compression','Comb filtering']::text[],ARRAY['Forgetting that a parallel plug-in adds latency, so the blended copy arrives late and cancels the dry signal.','Judging a parallel blend only in solo, missing the cancellation that appears when dry and wet are summed.','Flipping polarity at random instead of checking whether the loss comes from delay or from a phase-shifting processor.']::text[],ARRAY['A parallel compression bus makes the drums thinner instead of bigger because of uncompensated latency.','Blending a re-amped guitar copy with the direct signal and hearing frequencies drop out.','Setting up parallel processing in a digital audio workstation without delay compensation enabled.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bbf94cb8-cc61-5d37-a143-87db162de862' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parallel blend cancellation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bbf94cb8-cc61-5d37-a143-87db162de862','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bbf94cb8-cc61-5d37-a143-87db162de862' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'edd645c2-10df-57bd-9340-a391c54e4c72','Parallel distortion','A parallel-processing technique in which a distorted or harmonically driven copy of a signal is blended with the unprocessed dry signal, adding harmonics, grit, and perceived loudness while the dry path preserves the original transients, clarity, and dynamic range. Because only a portion of distorted signal is mixed in, the effect adds density and character without the smearing or loss of definition of fully distorting the source.','This sends a copy of the sound into a distortion effect, then mixes it under the clean original. The distorted copy adds grit and harmonics. The clean path keeps the attack and clarity. You get edge without turning the whole sound to mush.','It lets an engineer add aggression, harmonic richness, and apparent loudness to a source while keeping the punch and intelligibility of the untouched signal.','A mixer routes a bass or drum copy to a distortion plug-in and blends it under the dry track to add bite that cuts through a dense mix.','Parallel processing',ARRAY['Parallel saturation','Parallel compression','Harmonic distortion','Parallel-path comb filtering','Blend control','Post-dynamics equalization']::text[],ARRAY['Blending in so much distortion that the clean path is buried and the benefit of parallel processing is lost.','Ignoring phase or latency between the distorted copy and the dry signal, causing cancellation on the blend.','Distorting a very low bass frequency in the parallel path and muddying the low end instead of adding clarity.']::text[],ARRAY['Adding grit to a clean direct-input bass by blending a distorted copy underneath it.','Thickening a drum bus with a parallel distortion channel for a more aggressive rock sound.','Helping a vocal cut through a loud mix by mixing in a lightly distorted parallel copy.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='edd645c2-10df-57bd-9340-a391c54e4c72' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parallel distortion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'edd645c2-10df-57bd-9340-a391c54e4c72','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='edd645c2-10df-57bd-9340-a391c54e4c72' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '89ff441e-4c92-5782-94a2-d9271b0339c1','Parallel limiting','A parallel-processing technique in which a heavily limited copy of a signal is mixed with the dry path, so the limited copy supplies a dense, controlled, sustained body while the dry signal retains the original peaks and transients. It is a form of upward-style parallel dynamics used to add loudness and consistency without the pumping or transient loss of limiting the whole signal.','A limiter clamps down the loudest peaks. Here you send a copy through a hard limiter, then mix it under the untouched original. The copy adds steady, dense body. The dry path keeps the sharp peaks. The sound gets fuller and louder without losing its punch.','It raises the density and apparent loudness of a source while the dry path preserves the transient impact that full-signal limiting would flatten.','A mixer blends a hard-limited copy of a drum bus under the dry drums to add weight and sustain while keeping the crack of the hits.','Parallel processing',ARRAY['Parallel compression','Parallel upward compression','Limiter','Brick-wall limiting','Peak-to-level compression chain','Makeup gain']::text[],ARRAY['Confusing parallel limiting with limiting the whole signal, which removes the transients this technique protects.','Adding so much of the limited copy that the mix pumps and the dry transients are masked.','UNSAFE: Using parallel limiting to push overall loudness, then monitoring at unsafe sound-pressure levels; follow safe listening limits and keep session volumes down.']::text[],ARRAY['Blending a limited copy under a drum bus to add sustain without dulling the attack.','Thickening a vocal by mixing a hard-limited parallel copy beneath the dry take.','Adding loudness and consistency to a bass part while preserving its dynamic pluck.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='89ff441e-4c92-5782-94a2-d9271b0339c1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parallel limiting'),'[^a-z0-9]','','g'));
