SELECT '89ff441e-4c92-5782-94a2-d9271b0339c1','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='89ff441e-4c92-5782-94a2-d9271b0339c1' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c72b6b5a-d06c-50c3-a04d-6508387e43b7','Parallel saturation','A parallel technique in which a saturated copy of a signal — driven into tape-style, tube-style, or transformer-style nonlinearity — is blended with the dry path, adding harmonic content, gentle compression, and warmth while the dry signal preserves clarity and transient detail. Saturation is generally softer and lower-order than hard distortion, so parallel saturation adds subtle density and glue rather than obvious grit.','Saturation is a gentle overdrive that adds warmth and soft harmonics. Here you mix a saturated copy under the clean original. The copy adds warmth and body. The clean path keeps the detail. It thickens the sound without making it obviously distorted.','It adds warmth, harmonic density, and cohesion to a source while keeping the openness and transients of the untouched signal.','An engineer blends a tape- or tube-saturated copy under a dry mix bus to add subtle warmth and glue without dulling the top end.','Parallel processing',ARRAY['Parallel distortion','Harmonic saturation','Tape saturation','Parallel compression','Parallel-path comb filtering','Blend control']::text[],ARRAY['Confusing gentle saturation with hard distortion and driving the parallel path far too hard.','Overlooking that saturation adds low-order harmonics that can build up and mask clarity when blended too high.','Ignoring phase or latency between the saturated copy and the dry path, causing thinning on the blend.']::text[],ARRAY['Adding warmth to a clean digital recording by blending a tape-saturated parallel copy.','Gluing a drum bus together with a subtle parallel saturation channel.','Thickening a bass line while keeping its top-end definition intact.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c72b6b5a-d06c-50c3-a04d-6508387e43b7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parallel saturation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c72b6b5a-d06c-50c3-a04d-6508387e43b7','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c72b6b5a-d06c-50c3-a04d-6508387e43b7' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f4625e5c-49df-5b15-9fae-d6e8e609ff31','Parallel spectral processing','A parallel technique in which a frequency-selective (spectral) process — such as multiband dynamics, dynamic equalization, spectral shaping, or de-noising — is applied to a duplicate signal and blended with the dry path, so the processing acts only on chosen frequency regions while the dry signal preserves the overall balance. Because only a portion of the spectrally processed copy is mixed in, the treatment is subtler and more transparent than applying it to the whole signal.','"Spectral" means working on chosen frequency bands, not the whole sound. Here you process a copy in certain frequency ranges, then blend it under the original. This lets you tame or boost some bands gently. The untouched path keeps the natural balance.','It lets an engineer apply frequency-specific correction or enhancement in a gentle, blendable way, avoiding the artifacts of processing the full signal.','A mixer blends a de-noised or multiband-controlled copy under a dry vocal to reduce harshness or noise by taste without dulling the whole track.','Parallel processing',ARRAY['Multiband compression','Dynamic equalization','Parallel compression','Parallel transient processing','De-esser','Spectral shaping']::text[],ARRAY['Assuming parallel spectral processing affects the whole signal, when it only blends the chosen frequency regions.','Blending the processed copy so high that the intended subtle, frequency-specific effect becomes obvious.','Overlooking phase differences between the filtered copy and the dry path, which can alter the tonal balance.']::text[],ARRAY['Gently reducing sibilance by blending a de-essed parallel copy under a dry vocal.','Taming harsh upper-mids on a guitar bus with a blendable multiband-processed copy.','Adding controlled air to a mix by parallel-processing only the high-frequency band.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f4625e5c-49df-5b15-9fae-d6e8e609ff31' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parallel spectral processing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f4625e5c-49df-5b15-9fae-d6e8e609ff31','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f4625e5c-49df-5b15-9fae-d6e8e609ff31' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd5c1fd0b-50d6-5359-80ee-aa343cc7c865','Parallel transient processing','A parallel technique in which a transient-shaped copy of a signal — with attack and sustain deliberately emphasised or reduced — is blended with the dry path, so the copy adds or controls punch and envelope while the dry signal preserves the natural tone and level. Blending rather than fully processing keeps the effect musical and avoids the thin or unnatural results of aggressive full-signal transient shaping.','A transient shaper changes the attack (the first hit) and the sustain of a sound. Here you shape a copy, then mix it under the original. The copy adds or controls punch. The clean path keeps the natural tone. You get more snap without an unnatural sound.','It lets an engineer add or tame attack and punch in a controllable, blendable way while the dry path keeps the source sounding natural.','A mixer blends an attack-boosted copy under a dry drum track to add punch that cuts through a mix without making the drum sound papery.','Parallel processing',ARRAY['Transient shaper','Attack time','Parallel upward compression','Papery tone','Parallel compression','Envelope']::text[],ARRAY['Boosting attack on the parallel copy so hard that the blended drum turns thin and papery.','Confusing transient shaping, which works on the envelope, with compression, which works from a threshold.','Ignoring latency between the transient-shaped copy and the dry path, smearing the very attack being enhanced.']::text[],ARRAY['Adding punch to a drum bus by blending an attack-boosted parallel copy.','Restoring snap to an over-compressed snare using a parallel transient path.','Controlling boomy sustain on a room mic by blending in a sustain-reduced copy.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d5c1fd0b-50d6-5359-80ee-aa343cc7c865' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parallel transient processing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd5c1fd0b-50d6-5359-80ee-aa343cc7c865','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d5c1fd0b-50d6-5359-80ee-aa343cc7c865' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fc661876-941f-5097-8474-75c4cdf4e092','Parallel upward compression','A parallel-processing approach that produces upward compression — raising the level of quiet passages while leaving loud peaks largely untouched — by heavily compressing a duplicate signal and blending it under the dry path. The compressed copy has a much smaller dynamic range, so mixing it in lifts low-level detail and sustain while the dry path preserves the original transients; the net effect narrows dynamic range from the bottom up.','Upward compression makes the quiet parts louder while leaving the loud parts alone. You squash a copy hard, then mix it under the original. The squashed copy fills in the quiet detail. The clean path keeps the loud hits. The sound gets fuller and more even.','It raises the quiet detail and sustain of a source and evens out its dynamics without clamping the peaks, giving density while preserving transient impact.','An engineer sets up New York-style parallel compression on a drum or vocal bus, blending a hard-compressed copy under the dry signal to bring up body and room without losing punch.','Parallel processing',ARRAY['Parallel compression','Parallel limiting','Upward compression','Downward compression','Makeup gain','Peak-to-level compression chain']::text[],ARRAY['Thinking parallel compression lowers peaks, when blending a compressed copy actually raises the quiet parts.','Leaving plug-in latency uncompensated so the compressed copy cancels the dry signal instead of reinforcing it.','UNSAFE: Letting the raised low-level energy push overall loudness up and monitoring at unsafe sound-pressure levels; keep monitoring within safe listening limits.']::text[],ARRAY['Setting up New York parallel compression on a drum bus to add body and room sound.','Bringing up the quiet detail and sustain of a vocal without squashing its loud peaks.','Adding weight to a bass part while preserving its dynamic attack.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fc661876-941f-5097-8474-75c4cdf4e092' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parallel upward compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fc661876-941f-5097-8474-75c4cdf4e092','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fc661876-941f-5097-8474-75c4cdf4e092' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e75c567f-fdf5-593e-b713-515bfc2ba5d1','Parallel-path comb filtering','Comb filtering that arises when two versions of the same signal travelling through different (parallel) paths are summed with a small relative time delay, producing a series of regularly spaced peaks and notches across the frequency spectrum. In parallel processing the delay typically comes from plug-in latency or from group delay in a processor on one path; the notch spacing is set by the delay, so even a fraction of a millisecond can noticeably colour the blended sound.','Comb filtering happens when a sound mixes with a slightly delayed copy of itself. Some frequencies add up and some cancel, making a pattern of peaks and dips like a comb. In parallel processing the delay usually comes from a plug-in, and it colours the blended sound.','Naming this effect helps engineers recognise and fix the hollow, coloured sound caused by time-misaligned parallel paths, usually by delay compensation.','When a parallel bus sounds hollow or phasey, a technician enables delay compensation or time-aligns the paths to remove the comb-filter notches.','Phase and alignment',ARRAY['Parallel blend cancellation','Comb filtering','Phase cancellation','Latency compensation','Group delay','Parallel compression']::text[],ARRAY['Forgetting that any latency difference between parallel paths creates comb filtering when they are summed.','Trying to fix comb filtering with equalization instead of removing the time delay that causes it.','Assuming a tiny sub-millisecond delay is harmless, when it can place audible notches in the mid and high range.']::text[],ARRAY['A parallel compression bus sounds hollow because of uncompensated plug-in latency.','Blending a mic and a direct-input signal that are slightly out of time on a bass guitar.','Diagnosing a phasey tone on a drum bus that appears only when the wet and dry paths are summed.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e75c567f-fdf5-593e-b713-515bfc2ba5d1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parallel-path comb filtering'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e75c567f-fdf5-593e-b713-515bfc2ba5d1','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e75c567f-fdf5-593e-b713-515bfc2ba5d1' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aa5f5a19-bfbc-5400-ba34-8d913198e7d0','Peak-to-level compression chain','A serial dynamics arrangement that uses more than one gain-control stage, each doing a distinct job: an early, fast stage (a fast compressor or limiter) catches and tames short peaks, while a later, slower stage controls the overall level or rides the average loudness. Splitting the work across stages lets each use gentler settings than a single processor, giving smoother, more transparent control of both transients and long-term level.','This uses two or more compressors in a row, each with a different job. A fast one catches the sharp peaks. A slower one controls the overall volume. Sharing the work lets each use gentle settings. The result is smoother than one compressor doing everything.','It separates fast peak control from slow level control so each stage works gently, avoiding the artifacts of forcing one compressor to do both jobs.','A mastering or mix engineer places a fast peak limiter before a slow leveling compressor so peaks are tamed first and the average level is smoothed second.','Serial dynamics',ARRAY['Order-dependent processing','Serial compression','Limiter','Compressor','Gain staging','Pre-dynamics equalization']::text[],ARRAY['Setting every stage to heavy gain reduction instead of sharing the work so each stage stays gentle.','Reversing the roles by putting a slow leveler before the fast peak catcher, so peaks slip through uncontrolled.','UNSAFE: Chaining stages that raise average loudness and then monitoring at unsafe sound-pressure levels; keep monitoring within safe listening limits.']::text[],ARRAY['A mastering chain with a fast limiter for peaks and a slow compressor for average level.','Tracking a vocal through a fast peak compressor and a slower leveling compressor in series.','Controlling an unpredictable bass performance with staged peak and level compression.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aa5f5a19-bfbc-5400-ba34-8d913198e7d0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Peak-to-level compression chain'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'aa5f5a19-bfbc-5400-ba34-8d913198e7d0','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='aa5f5a19-bfbc-5400-ba34-8d913198e7d0' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ecd27e52-2b7e-5e7d-b41a-aa36e932343b','Pivot equalization','An equalization approach in which the frequency response is tilted about a fixed pivot (centre) frequency, so that a boost on one side of the pivot is accompanied by a complementary cut on the other side (and vice versa). The pivot frequency stays at unity gain while the spectrum rotates around it, letting an engineer shift overall tonal balance brighter or darker with a single control while leaving that anchor frequency unchanged.','A tilt or pivot equalizer rotates the tone around one fixed frequency. Turn it one way and the highs go up while the lows come down. Turn it the other way and it reverses. The pivot frequency stays put. It shifts a sound brighter or darker with one control.','It gives a quick, musical way to rebalance a signal from dark to bright around a chosen anchor frequency, without setting several separate bands.','An engineer uses a tilt or pivot equalizer on a mix bus to nudge the whole balance brighter or warmer around a set pivot frequency in one move.','Equalization',ARRAY['Tilt equalization','Pre-dynamics equalization','Post-dynamics equalization','Shelving filter','Dynamic equalization','Order-dependent processing']::text[],ARRAY['Treating a pivot or tilt equalizer as a single boost, forgetting that it also cuts the opposite side of the pivot.','Ignoring where the pivot frequency sits, so the tilt shifts the tone around the wrong anchor point.','Reaching for many narrow bands when one pivot tilt would rebalance the sound more musically.']::text[],ARRAY['Nudging a whole mix brighter around a fixed pivot frequency with one tilt control.','Warming a harsh master by tilting energy from the highs toward the lows.','Quickly matching the tonal balance of two songs using a tilt equalizer.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ecd27e52-2b7e-5e7d-b41a-aa36e932343b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pivot equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ecd27e52-2b7e-5e7d-b41a-aa36e932343b','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ecd27e52-2b7e-5e7d-b41a-aa36e932343b' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '108ca66a-28dc-56d8-b093-e5438f3ee536','Post-dynamics equalization','Equalization placed after a dynamics processor in a serial chain, so it shapes the tone of the already-compressed, limited, or gated signal without affecting how much gain reduction that processor applied. Because the equalizer no longer feeds the dynamics detector, its boosts and cuts change the final timbre directly and cannot be chased or undone by the compressor''s gain changes.','This is a tone control placed after a compressor or other dynamics effect. It shapes the sound that has already been compressed. Because it comes after, it does not change how much the compressor squashed the signal. It just sets the final tone.','It lets an engineer set the final tonal balance of a processed signal without altering the dynamics behaviour, since the equalizer sits downstream of the detector.','A mixer puts an equalizer after a vocal compressor to add air or remove mud from the compressed sound, knowing it will not change the gain reduction.','Equalization',ARRAY['Pre-dynamics equalization','Order-dependent processing','Compressor','Makeup gain','Gain staging','Dynamic equalization']::text[],ARRAY['Expecting an equalizer placed after a compressor to change the amount of gain reduction, which it cannot.','Boosting heavily after compression and pushing the makeup-gained signal into clipping downstream.','Confusing post-dynamics equalization with pre-dynamics equalization, which does feed the compressor''s detector.']::text[],ARRAY['Adding brightness to an already-compressed vocal without changing its dynamics.','Removing boxiness from a compressed drum bus at the end of the chain.','Shaping the final tone of a limited master bus after the dynamics are set.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='108ca66a-28dc-56d8-b093-e5438f3ee536' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Post-dynamics equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '108ca66a-28dc-56d8-b093-e5438f3ee536','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='108ca66a-28dc-56d8-b093-e5438f3ee536' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3a8bb8bb-78f5-5f30-9b91-b809e392685d','Pre-dynamics equalization','Equalization placed before a dynamics processor in a serial chain, so it changes both the tone of the signal and, crucially, what the following compressor, limiter, or gate detects and acts upon. Boosting a frequency before compression makes that band trigger more gain reduction (a form of frequency-conscious, tonal side-chain shaping), while cutting a band before compression stops it from driving the detector.','This is a tone control placed before a compressor or other dynamics effect. It changes the sound and also changes what the compressor reacts to. Boost a frequency here and the compressor clamps down harder when that frequency is loud. It shapes both tone and how the dynamics respond.','It lets an engineer shape tone while also steering how the following dynamics processor responds to specific frequencies, for example taming a resonant note by pushing it into the compressor.','An engineer high-pass filters or dips a boomy note before a compressor so the low end no longer triggers unwanted pumping in the gain reduction.','Equalization',ARRAY['Post-dynamics equalization','Order-dependent processing','Side-chain','Compressor','De-esser','Gain staging']::text[],ARRAY['Forgetting that boosting a band before a compressor makes that band drive more gain reduction.','Leaving low-frequency energy in before a full-band compressor, causing the bass to pump the whole signal.','Confusing pre-dynamics equalization with post-dynamics equalization, which does not affect the detector.']::text[],ARRAY['High-pass filtering a vocal before compression so plosives do not trigger pumping.','Boosting sibilance into a compressor''s side-chain to act as a de-esser.','Dipping a resonant room note before a drum compressor to stop it driving gain reduction.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3a8bb8bb-78f5-5f30-9b91-b809e392685d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pre-dynamics equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3a8bb8bb-78f5-5f30-9b91-b809e392685d','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3a8bb8bb-78f5-5f30-9b91-b809e392685d' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1a1b8d27-0fb6-5746-89f3-a6eea39eeccf','Pre-emphasis/de-emphasis processing','A complementary pair of fixed equalization curves in which high frequencies are boosted (pre-emphasis) before a noisy recording or transmission stage and cut by an exactly inverse curve (de-emphasis) on the receiving or playback side. The two curves cancel to a flat overall response while the playback high-frequency cut also attenuates noise added by the channel, improving signal-to-noise ratio. Standardised time constants define the curves, for example 50 or 75 microseconds for FM broadcast and the 3180/318/75 microsecond network for RIAA phono.','This is a matched pair of tone controls used to fight hiss. Before a noisy stage, the treble is turned up. On playback, the treble is turned back down by the same amount. That second step also pushes the added hiss down, so the sound is cleaner. FM radio and vinyl records both use this trick.','It exists to raise the signal above channel noise where that noise is worst, then restore a flat response on the far side so the listener hears the original balance with less hiss. Fixed, standardised curves let separate encode and decode devices match exactly.','A technician meets it as the RIAA curve built into a phono stage, the 50 or 75 microsecond FM curves in transmitters and tuners, and the emphasis flag on some early digital and CD masters, and must apply the matching de-emphasis or the top end sounds wrong.','Signal processing',ARRAY['Reciprocal equalization','Companding','Noise reduction','Signal-to-noise ratio','Equalization','RIAA equalization']::text[],ARRAY['Forgetting to switch in de-emphasis for an emphasised source, leaving the playback bright and harsh.','Applying de-emphasis to material that was never pre-emphasised, dulling the high end.','Confusing fixed pre-emphasis and de-emphasis curves with the dynamic, level-dependent companding used by tape noise reduction systems.']::text[],ARRAY['Designing or servicing a phono preamp so its de-emphasis matches the RIAA recording curve.','Aligning an FM broadcast chain to the correct 50 or 75 microsecond emphasis for the region.','Handling an early digital master whose pre-emphasis flag must be honoured on transfer.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1a1b8d27-0fb6-5746-89f3-a6eea39eeccf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pre-emphasis/de-emphasis processing'),'[^a-z0-9]','','g'));
