SELECT '1a1b8d27-0fb6-5746-89f3-a6eea39eeccf','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1a1b8d27-0fb6-5746-89f3-a6eea39eeccf' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6899b20a-6c70-5b4b-82b1-805d32dbf949','Processor ordering','The chosen sequence of signal processors in a chain, since each device acts on the output of the one before it and the result changes with the order. Common decisions include whether equalization precedes or follows compression, where a gate or de-esser sits, and whether saturation comes before or after level control, because a compressor''s detector responds differently to an equalized or already-compressed signal.','This is the order you put effects in a chain. Each effect works on whatever the last one handed it. So equalizing before a compressor gives a different result than after it. Changing the order changes the sound, even with the same settings.','Choosing an order lets the engineer control how processors interact, for example gating out noise before a compressor raises it, or shaping tone before dynamics so the compressor reacts to the tone you want. It exists because dynamics and tone processing are not independent when stacked.','When building a channel strip or plugin chain, a technician decides the order to suit the goal, such as high-pass and gate first, then compression, then corrective and tonal equalization, then limiting, and reorders when a compressor is over-reacting to a resonance.','Signal chain',ARRAY['Signal chain','Compression','Equalization','Gate','Serial clipping','Saturation–compression interaction']::text[],ARRAY['Assuming the order does not matter because the individual settings are unchanged.','Boosting a resonant frequency before a compressor and then wondering why the compressor pumps on that note.','Placing a noise gate after a compressor, so the compressor first lifts the noise the gate was meant to remove.']::text[],ARRAY['Deciding equalizer-before-compressor versus compressor-before-equalizer on a vocal chain.','Sequencing gate, compressor, equalizer and limiter in a live console channel.','Reordering plugins in a mix to stop a compressor triggering on a boosted low-mid resonance.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6899b20a-6c70-5b4b-82b1-805d32dbf949' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Processor ordering'),'[^a-z0-9]','','g'));
