INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9ddc8354-c882-5a7f-880d-2e9a6329baa4','Resonance suppression','The reduction of unwanted resonant peaks, whether from an instrument, a room, or gear, using narrow equalizer cuts or dynamic processing so the peaks no longer dominate the balance. Suppression may be static, a fixed notch, or dynamic, attenuating the peak only when it rings, which preserves the surrounding tone when the resonance is not active.','This means taming a frequency that rings or booms too much. You cut that band so it stops sticking out. A fixed cut lowers it all the time. A smarter, dynamic cut only clamps down when the note actually rings, leaving the rest alone.','It exists to control resonances that make a sound boomy, boxy or harsh, restoring a balanced tone without gutting the whole region. Dynamic suppression exists so the cut acts only when needed, keeping the natural tone the rest of the time.','A technician notches a ringing snare frequency, tames a boomy room mode, or sets a dynamic equalizer to duck a harsh resonance only when it flares, after first finding the frequency by sweeping a boost.','Equalization',ARRAY['Resonance hunting','Resonance-dependent equalization','Equalization','Dynamic equalizer','Q factor','Feedback']::text[],ARRAY['Cutting too wide or too deep, which removes the resonance but leaves the sound thin and lifeless.','Using a permanent notch where a dynamic cut would keep the tone when the resonance is silent.','Suppressing a peak without first finding its exact frequency, so the cut misses the ring.']::text[],ARRAY['Notching a ringing frequency in a snare or tom to clean up a drum kit.','Taming a boomy low-mid room mode on a vocal recorded in an untreated room.','Setting a dynamic equalizer to suppress harshness only when a cymbal peaks.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9ddc8354-c882-5a7f-880d-2e9a6329baa4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Resonance suppression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9ddc8354-c882-5a7f-880d-2e9a6329baa4','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9ddc8354-c882-5a7f-880d-2e9a6329baa4' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '613528d9-e6a0-5fba-8a28-8d36b7911c44','Resonance-dependent equalization','Equalization whose action depends on resonant content in the signal, applying attenuation to a band only when a resonance there exceeds a threshold and backing off when it does not. It is realised by dynamic equalizers and spectral resonance processors that continuously track peaks across many bands, so correction follows the resonances rather than staying fixed.','This is an equalizer that reacts to ringing frequencies as they happen. It watches the sound and only cuts a band when that band rings too much. When the ringing stops, it eases off. So it fixes problems only when they appear, instead of cutting all the time.','It exists to tame resonances that come and go, such as a note that only rings on certain hits, without permanently altering the tone. Making the cut depend on the resonance keeps the natural sound intact whenever the problem is absent.','A technician uses a dynamic equalizer or a spectral resonance suppressor on a vocal or acoustic guitar so harsh or boomy notes are pulled down only as they occur, leaving softer passages untouched.','Equalization',ARRAY['Dynamic equalizer','Resonance suppression','Resonance hunting','Equalization','Multiband compression','Q factor']::text[],ARRAY['Setting the threshold so low that the equalizer clamps constantly and dulls the tone.','Confusing resonance-dependent dynamic equalization with a fixed static notch that always cuts.','Using very fast band action that chatters on transients and adds artefacts.']::text[],ARRAY['Taming occasional harsh vocal notes with a dynamic equalizer keyed to those frequencies.','Suppressing sporadic string resonance on an acoustic guitar only when it rings.','Using a spectral resonance processor to smooth roaming peaks on a bright mix.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='613528d9-e6a0-5fba-8a28-8d36b7911c44' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Resonance-dependent equalization'),'[^a-z0-9]','','g'));
