SELECT '613528d9-e6a0-5fba-8a28-8d36b7911c44','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='613528d9-e6a0-5fba-8a28-8d36b7911c44' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5bf517b8-1c1c-5976-9a94-f4e6286ea0ab','Saturation–compression interaction','The combined effect of saturation and compression when both act on a signal, since each alters level and dynamics in a way that changes how the other behaves. Saturation adds harmonics and softly rounds peaks, which is itself a mild dynamics change, so it reduces the peaks a following compressor sees, while a compressor placed first raises sustained level and drives the saturator harder.','Saturation and compression affect each other when used together. Saturation adds warmth and gently flattens peaks, so it already softens the loudest bits. A compressor after it then has less peak to grab. Swap the order and the result changes, because each one feeds the next a different signal.','Understanding the interaction exists so engineers can combine warmth and level control on purpose, using saturation to round peaks before compression or compression to push the saturator, and choose the order for the tone and control they want. It explains why the two together do more than either alone.','A technician drives a tape or tube saturator before a compressor to tame transients gently and let the compressor work less hard, or compresses first to push a saturator into steadier harmonic colour, listening for the balance of warmth and control.','Dynamics processing',ARRAY['Saturation','Compression','Processor ordering','Serial clipping','Harmonic distortion','Parallel compression']::text[],ARRAY['Overdriving the saturator so hard that the following compressor has almost no peaks left to control.','Ignoring order, so the tonal result changes unexpectedly when saturation and compression are swapped.','UNSAFE: Pushing saturation and compression for ever-greater loudness while monitoring loud to judge it; sustained high monitor levels risk hearing damage, so evaluate at safe levels.']::text[],ARRAY['Driving a tape emulation before a bus compressor to soften drum transients.','Compressing a bass first, then saturating for steady harmonic weight.','Comparing saturation-before-compression versus the reverse on a vocal for tone and control.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5bf517b8-1c1c-5976-9a94-f4e6286ea0ab' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Saturation–compression interaction'),'[^a-z0-9]','','g'));
