SELECT '5bf517b8-1c1c-5976-9a94-f4e6286ea0ab','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5bf517b8-1c1c-5976-9a94-f4e6286ea0ab' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2a65bb6a-6888-52af-9eb3-d221a020d0c1','Self-sidechain compression','Compression in which the detector''s sidechain is fed from the same signal being processed, so the channel controls its own gain, as opposed to external-key sidechaining where a separate signal drives the detector. This internal sidechain is the default topology of a compressor; the sidechain may still be filtered or shaped so the detector responds to a chosen part of that same signal.','A compressor decides how much to turn down by listening to a control signal called the sidechain. In self-sidechain, it listens to the very sound it is squashing. That is the normal way a compressor works. You can still filter what it listens to, so bass, say, triggers it less.','It exists as the standard way a compressor controls level, reacting to its own output so louder input yields more gain reduction. Filtering the internal sidechain lets the engineer stop, for example, strong bass from triggering the whole compressor.','A technician uses the normal internal detection for everyday level control and adds a sidechain high-pass filter so a kick or bass no longer forces the compressor to duck the entire signal, keeping the low end steady.','Dynamics processing',ARRAY['Sidechain','Compression','Ducking','Release-shaped ducking','Detector','Threshold']::text[],ARRAY['Assuming a sidechain always means an external key, when the default sidechain is the signal itself.','Forgetting the sidechain filter is engaged, so the compressor reacts to a filtered version and seems under-active.','Confusing internal self-sidechain compression with external-key ducking driven by a separate track.']::text[],ARRAY['Everyday vocal or bus compression using the compressor''s own internal detection.','Adding a sidechain high-pass so a bassy mix does not pump the whole compressor.','De-essing by filtering the internal sidechain so the compressor reacts to sibilance.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2a65bb6a-6888-52af-9eb3-d221a020d0c1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Self-sidechain compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2a65bb6a-6888-52af-9eb3-d221a020d0c1','d42dcf1d-a730-488c-9633-28e1218563a4',true
