INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '441ee1b6-2556-5e5a-98fd-4719059d215c','Serial clipping','The use of several clipping stages in series, each shaving off a small amount of peak, so that peak level is controlled in gentle steps rather than by one aggressive clip. Spreading the clipping across cascaded stages, often between other processors, keeps each stage''s distortion low, giving more peak reduction for a given audible harshness than a single hard clip.','Clipping chops off the tops of the loudest peaks. Serial clipping does this in several small steps instead of one big cut. Each stage trims just a little. Together they control the peaks while sounding cleaner than one hard chop. It is a common loudness trick in modern mastering.','It exists to squeeze out loudness and control peaks with less obvious distortion, since many gentle clips generate less harshness than one severe clip for the same peak reduction. Staging the clipping lets an engineer push level while keeping the artefacts subtle.','A mastering or mix engineer places light clippers at points in the chain, each trimming a decibel or two, ahead of the final limiter, to raise loudness and hold peaks without the crunch of a single hard clipper.','Dynamics processing',ARRAY['Clipping','Limiting','Processor ordering','Saturation–compression interaction','Headroom','Loudness']::text[],ARRAY['Overusing each stage so the cumulative distortion becomes obvious and harsh.','Forgetting that several stages add up, so total clipping is far more than any one stage suggests.','UNSAFE: Chasing ever-louder masters through serial clipping while monitoring at high levels to judge them, which risks hearing damage; check loudness at safe monitor levels and against metered targets.']::text[],ARRAY['Staging light clippers before a limiter to raise a master''s loudness cleanly.','Trimming drum-bus peaks in small steps so the limiter works less hard.','Comparing one hard clip against several gentle clips for the same peak reduction.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='441ee1b6-2556-5e5a-98fd-4719059d215c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Serial clipping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '441ee1b6-2556-5e5a-98fd-4719059d215c','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='441ee1b6-2556-5e5a-98fd-4719059d215c' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4390cd3f-826e-55b7-80f1-a34a084a2e01','Serial compression','A dynamics technique in which a signal passes through two (or more) compressors connected in series, so each stage applies only a modest amount of gain reduction rather than one unit doing all the work. Splitting the reduction across stages—often a slow, transparent compressor for broad leveling followed by a faster one for peak or character control—yields smoother, less audible compression than a single compressor set to the same total reduction.','Serial compression sends the sound through two compressors, one after the other. Each one turns the volume down just a little. Two gentle squeezes sound smoother than one hard squeeze.','It exists to achieve strong overall level control while keeping each compressor working gently, so the ear hears even, natural dynamics instead of the pumping or dulling a single hard-working compressor can cause.','An engineer sets a leveling-style compressor first to catch slow level changes, then a faster compressor to tame peaks, sharing the total gain reduction so neither stage sounds obvious on a vocal or bass.','Compression technique',ARRAY['Parallel compression','Gain reduction','Compression ratio','Attack time','Release time','Bus compression']::text[],ARRAY['Setting both compressors to heavy gain reduction, which stacks the artifacts instead of sharing the work and over-compresses the signal.','Using two identical compressor settings in series rather than giving each stage a distinct job, such as broad leveling versus peak control.','Assuming serial compression is the same as parallel compression; in series the whole signal passes through both units, not a blended dry-plus-compressed path.']::text[],ARRAY['Smoothing a lead vocal with a slow optical compressor feeding a faster FET compressor.','Controlling a dynamic bass part in two gentle stages before it reaches the mix bus.','Mastering-style leveling where one compressor handles broad dynamics and a second catches remaining peaks.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4390cd3f-826e-55b7-80f1-a34a084a2e01' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Serial compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4390cd3f-826e-55b7-80f1-a34a084a2e01','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4390cd3f-826e-55b7-80f1-a34a084a2e01' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2aa8d968-b42b-5051-a87c-2de32e393e6d','Sidechain audition','A monitoring function that routes a dynamics processor''s sidechain (detection/key) signal to the outputs so the operator can hear exactly what the level detector is responding to, instead of the processed audio. It is used to set sidechain filters, emphasis, or an external key so gain reduction is triggered by the intended content.','A sidechain is the signal a compressor listens to so it knows when to act. Sidechain audition lets you hear that signal by itself. It helps you aim the effect at the right sound, like a singer''s harsh ''sss''.','It exists so an engineer can confirm the detector is keying off the intended frequencies or source, making sidechain filtering and de-essing accurate instead of guesswork.','On a de-esser or compressor the technician engages the listen/key-listen button to solo the filtered sidechain, tunes the filter until only the target is audible, then switches back to process.','Sidechain technique',ARRAY['Sidechain (key input)','Sidechain high-pass filtering','De-esser','Key listen','Sidechain band-pass filtering','External key']::text[],ARRAY['Leaving the processor in sidechain-listen mode and sending that thin, filtered signal to the mix or recording by mistake.','UNSAFE: A boosted or filtered sidechain can jump in level when soloed; keep monitoring moderate, because sustained exposure above about 85 dBA risks hearing damage.','Assuming the auditioned sidechain is what gets recorded; it only feeds the detector, not the audio path.']::text[],ARRAY['Tuning a de-esser by ear so the detector hears only sibilance before processing a vocal.','Setting a sidechain high-pass filter on a bus compressor while listening to the keyed signal.','Confirming an external kick key is triggering a ducking compressor on a bass track.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2aa8d968-b42b-5051-a87c-2de32e393e6d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sidechain audition'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2aa8d968-b42b-5051-a87c-2de32e393e6d','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2aa8d968-b42b-5051-a87c-2de32e393e6d' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '03ac623b-f6df-5bac-b337-fdbb24e48b62','Sidechain band-pass filtering','Placing a band-pass filter in a dynamics processor''s sidechain so the level detector responds only to a chosen frequency band, ignoring content above and below it. Gain reduction is then triggered by energy within that band—for example the sibilance region in a de-esser—while the full-range signal still passes through the audio path.','This puts a filter on the sidechain so the compressor reacts to only one band of frequencies. It ignores the rest. A de-esser uses this to catch harsh ''sss'' sounds and leave the rest alone.','It makes dynamic processing frequency-selective, so the detector reacts to a specific problem band such as sibilance or a resonant note instead of overall level.','A technician sets the sidechain band-pass around 5–10 kHz on a de-esser so only sibilance drives gain reduction, or bands a compressor''s key to tame a specific resonance.','Sidechain filtering',ARRAY['De-esser','Sidechain high-pass filtering','Sidechain low-pass filtering','Sidechain emphasis','Dynamic EQ','Sidechain audition']::text[],ARRAY['Setting the band too wide, so the detector still reacts to level generally instead of the target band.','Confusing sidechain band-pass filtering, which shapes only the detector, with band-pass filtering the audio itself.','Skipping the sidechain audition, so the band is centered on the wrong frequency and misses the sibilance or resonance.']::text[],ARRAY['De-essing a bright vocal by keying gain reduction from the 5–10 kHz sibilance band.','Taming a boomy resonance on a tom by banding the compressor''s sidechain around it.','Building a frequency-conscious compressor on an acoustic guitar that reacts mainly to pick attack.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='03ac623b-f6df-5bac-b337-fdbb24e48b62' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sidechain band-pass filtering'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '03ac623b-f6df-5bac-b337-fdbb24e48b62','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='03ac623b-f6df-5bac-b337-fdbb24e48b62' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4573f6d5-6a03-50eb-81c9-a60e3f45cc11','Sidechain de-emphasis','Attenuating a chosen frequency region within a dynamics processor''s sidechain so the detector becomes less sensitive to that region and triggers less gain reduction from those frequencies. It is the inverse of sidechain emphasis and lets an engineer stop a strong band—often low-frequency energy—from dominating the detector''s response.','This turns down certain frequencies in the sidechain, not in the sound itself. The compressor then reacts less to those frequencies. It stops strong bass, for example, from grabbing the compressor too much.','It exists to keep loud but less important bands from over-triggering the detector, so gain reduction tracks the parts that matter.','An engineer de-emphasizes the low end in a bus compressor''s sidechain so kick and bass stop pumping the whole mix, keeping the compression tied to midrange level.','Sidechain filtering',ARRAY['Sidechain emphasis','Sidechain high-pass filtering','Sidechain tilt filtering','Detector (level detector)','Pumping','Sidechain band-pass filtering']::text[],ARRAY['Cutting so much of a band that the detector ignores real level changes there and lets peaks through.','Confusing de-emphasis of the sidechain with cutting those frequencies from the actual output signal.','Assuming a sidechain high-pass and de-emphasis are identical; a shelf or bell de-emphasis reduces a band without fully removing everything below a corner.']::text[],ARRAY['Reducing low-frequency sensitivity on a mix-bus compressor to stop kick-driven pumping.','Lowering sibilance-band weighting when a de-esser reacts too aggressively.','Keeping a vocal compressor from clamping on plosive energy by de-emphasizing the lows in the key.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4573f6d5-6a03-50eb-81c9-a60e3f45cc11' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sidechain de-emphasis'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4573f6d5-6a03-50eb-81c9-a60e3f45cc11','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4573f6d5-6a03-50eb-81c9-a60e3f45cc11' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '54002a39-689d-538d-9061-4c42513e48f9','Sidechain emphasis','Boosting a chosen frequency region within a dynamics processor''s sidechain so the level detector becomes more sensitive to that region and applies more gain reduction when it is present. Emphasizing the sibilance band, for instance, turns a compressor into a de-esser without altering the audio path itself.','This boosts certain frequencies in the sidechain, not in the sound you hear. The compressor then reacts more strongly to those frequencies. Boosting the harsh ''sss'' band turns a compressor into a de-esser.','It exists to make a compressor react preferentially to a specific band, so problem frequencies get controlled more than the rest of the signal.','A technician boosts around 6–8 kHz in the sidechain to make a compressor clamp down on sibilance, or emphasizes the beater click so a kick compressor follows attack.','Sidechain filtering',ARRAY['De-esser','Sidechain de-emphasis','Sidechain band-pass filtering','Sidechain audition','Frequency-conscious compression','Detector (level detector)']::text[],ARRAY['Over-emphasizing a band so the processor clamps hard and produces an obvious lisp or dulled sound.','Emphasizing the wrong frequency because the sidechain was never auditioned.','Thinking sidechain emphasis boosts those frequencies in the output; it only changes what the detector reacts to.']::text[],ARRAY['Turning a general compressor into a de-esser by boosting the sibilance band in its key.','Making a drum-bus compressor follow snare crack by emphasizing the upper mids in the sidechain.','Frequency-conscious vocal compression that reacts more to harsh consonants.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='54002a39-689d-538d-9061-4c42513e48f9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sidechain emphasis'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '54002a39-689d-538d-9061-4c42513e48f9','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='54002a39-689d-538d-9061-4c42513e48f9' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '273dd8aa-fb49-5ade-a39d-5f5f86f0d0b2','Sidechain high-pass filtering','Inserting a high-pass filter in a dynamics processor''s sidechain so low-frequency energy is removed from the detection path before the level detector, while the full-range signal still passes through the audio path unchanged. Because bass no longer dominates the detector, the compressor stops applying heavy gain reduction on every kick or low note, reducing pumping and preserving low-end level.','This filters bass out of the sidechain, not out of the sound. The compressor then stops reacting so much to kick and bass. This keeps the low end steady and cuts down pumping.','Low frequencies carry the most energy, so without a sidechain high-pass they trigger most of the gain reduction; the filter lets the detector respond to the whole balance instead.','On a mix-bus compressor an engineer sets the sidechain high-pass around 80–150 Hz so the low end no longer drives the compressor, tightening the mix without pumping.','Sidechain filtering',ARRAY['Sidechain de-emphasis','Pumping','Bus compression','Sidechain low-pass filtering','Detector (level detector)','Sidechain audition']::text[],ARRAY['Setting the sidechain high-pass so high that the detector ignores real vocal or midrange level and lets peaks slip through.','Believing the high-pass filters the audio; it only shapes what the detector hears.','Leaving no sidechain high-pass on a full-range bus compressor and then blaming pumping on the wrong control.']::text[],ARRAY['Stopping a kick drum from pumping a whole mix on the master-bus compressor.','Keeping a full-range vocal compressor from over-reacting to plosives and low rumble.','Tightening a bass-heavy electronic track without the compressor clamping on every bass note.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='273dd8aa-fb49-5ade-a39d-5f5f86f0d0b2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sidechain high-pass filtering'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '273dd8aa-fb49-5ade-a39d-5f5f86f0d0b2','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='273dd8aa-fb49-5ade-a39d-5f5f86f0d0b2' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '34f8c461-3d40-5109-8a3f-393a0875b2d4','Sidechain low-pass filtering','Inserting a low-pass filter in a dynamics processor''s sidechain so high-frequency energy is removed from the detection path, making the level detector respond mainly to low- and mid-frequency content. The audio path stays full-range; only the detector''s sensitivity to highs is reduced, so bright transients like cymbals or sibilance trigger less gain reduction.','This filters the high frequencies out of the sidechain only. The compressor then reacts mostly to the lower sounds. Bright, sharp sounds no longer set it off as easily.','It keeps loud high-frequency transients from dominating the detector, so the processor follows the body of the sound instead of every cymbal hit or ''sss''.','A technician low-passes the sidechain so a drum-bus compressor rides the kick and snare body rather than being triggered by hi-hats and cymbals.','Sidechain filtering',ARRAY['Sidechain high-pass filtering','Sidechain band-pass filtering','Detector (level detector)','Pumping','Sidechain audition','De-esser']::text[],ARRAY['Cutting the highs so aggressively that the detector misses genuine loud transients and allows them through.','Confusing a sidechain low-pass, which affects the detector only, with low-passing the actual audio.','Reaching for a low-pass when a band-pass or high-pass would target the problem band more precisely.']::text[],ARRAY['Making a drum-bus compressor follow low-end weight instead of cymbal wash.','Preventing bright acoustic-guitar transients from over-triggering a compressor.','Keeping a program compressor from clamping on high-frequency hiss or sibilance.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='34f8c461-3d40-5109-8a3f-393a0875b2d4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sidechain low-pass filtering'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '34f8c461-3d40-5109-8a3f-393a0875b2d4','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='34f8c461-3d40-5109-8a3f-393a0875b2d4' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '06faef68-d019-5658-8397-73bdb9ee15e0','Sidechain tilt filtering','Applying a tilt filter—one that boosts one end of the spectrum while cutting the other around a central pivot frequency—to a dynamics processor''s sidechain, so the detector''s sensitivity is skewed toward either high or low frequencies. Tilting toward the highs makes the processor behave more like a bright-transient controller; tilting toward the lows makes it follow low-end level, all without changing the audio path.','A tilt filter turns one end of the frequency range up and the other end down at the same time. On the sidechain it aims the compressor more at the highs or more at the lows. The sound itself stays untouched.','It gives one gentle control that shifts what the detector pays attention to across the whole spectrum, instead of separate high-pass and low-pass settings.','An engineer tilts the sidechain toward the highs so a vocal compressor reacts a bit more to consonants, or toward the lows so a bus compressor rides the low end.','Sidechain filtering',ARRAY['Sidechain high-pass filtering','Sidechain low-pass filtering','Sidechain emphasis','Tilt EQ','Detector (level detector)','Sidechain de-emphasis']::text[],ARRAY['Using a steep tilt and unintentionally making the detector track only one extreme of the spectrum.','Assuming the tilt changes the output tone; on the sidechain it only reshapes the detector''s response.','Confusing a broad tilt with a narrow band-pass; a tilt affects the whole spectrum, not one band.']::text[],ARRAY['Gently biasing a bus compressor toward low-end control with a downward tilt on the key.','Making a vocal compressor slightly more responsive to sibilance with an upward sidechain tilt.','Balancing detector sensitivity on a full-mix compressor without stacking separate filters.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='06faef68-d019-5658-8397-73bdb9ee15e0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sidechain tilt filtering'),'[^a-z0-9]','','g'));
