SELECT '06faef68-d019-5658-8397-73bdb9ee15e0','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='06faef68-d019-5658-8397-73bdb9ee15e0' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fca92c11-3ac8-57e7-bf68-f1df92297dce','Smeared tone','A sound whose transient definition and clarity have been blurred, so note attacks and detail are softened and the tone seems indistinct or washed together. In dynamics processing it commonly results from transient smearing—an over-slow attack, excessive gain reduction, or heavy limiting that rounds off the initial peaks that give a sound its edge and articulation.','A smeared tone is a sound that has lost its sharp edges and detail. The start of each note gets softened, so everything blurs together. Too much compression or limiting is a common cause.','The term names an audible fault so engineers can recognize when processing has dulled transients and back off attack, ratio, or limiting to restore clarity.','When a compressed drum or acoustic guitar sounds dull and lifeless, the technician identifies transient smearing and lengthens the attack or reduces gain reduction to bring back punch.','Processing artifact',ARRAY['Transient','Attack time','Over-compression','Limiting','Pumping','Transient designer']::text[],ARRAY['Fixing a smeared tone by adding brightness with EQ instead of correcting the attack time or gain reduction that caused it.','Assuming a faster attack always helps; too fast can also dull transients and smear the tone.','Blaming the source or microphone when the smearing was introduced by heavy dynamics processing.']::text[],ARRAY['A drum bus that sounds flat and lifeless after a slow-attack compressor rounds off the hits.','An acoustic guitar losing pick definition under heavy limiting.','A full mix that turns mushy when the master compressor is pushed too hard.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fca92c11-3ac8-57e7-bf68-f1df92297dce' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Smeared tone'),'[^a-z0-9]','','g'));
