SELECT 'fca92c11-3ac8-57e7-bf68-f1df92297dce','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fca92c11-3ac8-57e7-bf68-f1df92297dce' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0f494998-be16-5b2f-a532-6612df7a0d8e','Spectral balancing','The process of adjusting the relative level of energy across the frequency spectrum so that low, mid, and high regions sit in an intended balance, with no band unduly dominating or lacking. It can be done statically with equalization or dynamically with multiband compression, dynamic EQ, or spectral-shaping tools that respond to how the balance changes over time.','Spectral balancing means setting the right amount of low, middle, and high frequencies. The goal is a tone where nothing sticks out or goes missing. It can be fixed, or it can move with the music.','It exists to give a mix or master an even, translatable tonal balance so it sounds right on many playback systems and no frequency range fatigues the listener.','A mastering engineer compares against a reference track and a spectrum analyzer, then applies gentle EQ or dynamic EQ to correct an over-bright or bass-heavy balance.','Spectral processing',ARRAY['Dynamic EQ','Multiband compression','Tonal balance','Spectral masking control','Equalization','Reference track']::text[],ARRAY['Chasing a flat analyzer curve instead of a musically appropriate balance for the genre.','Balancing on one set of speakers or headphones without checking translation elsewhere.','Using wide static EQ boosts where a dynamic approach would fix only the moments that need it.']::text[],ARRAY['Mastering a mix that is too bright to translate on consumer earbuds.','Matching the tonal balance of an album''s songs so they sit together.','Correcting a boomy low-mid buildup on a bus with dynamic EQ.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0f494998-be16-5b2f-a532-6612df7a0d8e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral balancing'),'[^a-z0-9]','','g'));
