SELECT '0f494998-be16-5b2f-a532-6612df7a0d8e','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0f494998-be16-5b2f-a532-6612df7a0d8e' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '157eee18-a8a3-57f7-9454-d6f4b210a4e2','Spectral centroid shifting','Deliberately moving a signal''s spectral centroid—the magnitude-weighted mean frequency of its spectrum, which correlates strongly with perceived brightness—so the sound is heard as brighter or darker. Raising high-frequency energy or reducing low-frequency energy shifts the centroid upward; the reverse shifts it downward, and dynamic tools can move it in response to level.','The spectral centroid is the balance point of a sound''s frequencies. It tracks how bright a sound feels. Shifting it up makes the sound brighter; shifting it down makes it darker.','It gives a measurable handle on brightness, so engineers can brighten or darken a source predictably and even automate that change with dynamics.','An engineer raises the centroid of a dull vocal by adding presence, or uses a spectral or dynamic tool to keep a track''s brightness consistent as it gets louder or softer.','Spectral processing',ARRAY['Spectral balancing','Brightness','Equalization','Dynamic EQ','Spectral drive shaping','Tilt EQ']::text[],ARRAY['Assuming brightness depends only on high-frequency boost; cutting the lows also raises the centroid.','Pushing the centroid up so far that the sound becomes harsh and fatiguing.','Treating the spectral centroid as an exact pitch rather than an overall balance point of the spectrum.']::text[],ARRAY['Brightening a dull vocal so it cuts through a dense mix.','Keeping a synth''s perceived brightness steady as its dynamics change.','Darkening an overly bright cymbal track by lowering its high-frequency weighting.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='157eee18-a8a3-57f7-9454-d6f4b210a4e2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral centroid shifting'),'[^a-z0-9]','','g'));
