INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9b546c44-792d-5f45-a340-4c50b90b03b7','Spectral drive shaping','Applying harmonic drive or saturation in a frequency-dependent way, so different parts of the spectrum receive different amounts or characters of distortion and the added harmonics are shaped rather than applied uniformly. It is typically achieved with multiband saturation or by filtering before and after a drive stage so, for example, low frequencies stay clean while the upper mids are excited.','This adds warmth or grit to some frequency ranges more than others. For example, the bass can stay clean while the middle gets some bite. It shapes where the drive lands in the spectrum.','It lets an engineer add richness or aggression only where it helps, avoiding the muddy low-end distortion that full-range drive can create.','A technician drives the upper mids of a bass guitar for presence while keeping the sub clean, or saturates only the high band of a drum bus for air.','Spectral processing',ARRAY['Saturation','Harmonic distortion','Multiband compression','Spectral balancing','Dynamic EQ','Harmonic exciter']::text[],ARRAY['Driving the low band hard and turning the low end to mud instead of keeping it tight.','Adding broadband drive when only one band needed excitement.','Ignoring the level rise that saturation adds and misjudging the balance afterward.']::text[],ARRAY['Exciting the presence range of a bass so it reads on small speakers while the sub stays clean.','Adding air by saturating only the top band of a drum bus.','Giving a vocal edge in the upper mids without distorting its lows.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9b546c44-792d-5f45-a340-4c50b90b03b7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral drive shaping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9b546c44-792d-5f45-a340-4c50b90b03b7','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9b546c44-792d-5f45-a340-4c50b90b03b7' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b25475b0-ec5d-5a65-bba1-bdef3514f7d2','Spectral masking control','Managing auditory masking—where a louder sound renders a quieter sound at nearby frequencies harder to hear or inaudible—so that spectrally overlapping sources remain intelligible in a mix. It is typically done with dynamic equalization or frequency-selective sidechain processing that dips the masking source''s energy in the contested band only when the masked source is present.','Masking is when a loud sound hides a quieter one at similar frequencies. Spectral masking control keeps both sounds clear. It gently dips the louder sound''s frequencies so the quieter one can be heard.','It exists to keep overlapping instruments, like a vocal and guitar or a kick and bass, from hiding each other, improving clarity without simply turning everything up.','An engineer sets a dynamic EQ on a guitar, keyed from the vocal, so the guitar''s mids dip only while the vocal sings, freeing space for the words.','Spectral processing',ARRAY['Auditory masking','Dynamic EQ','Sidechain (key input)','Spectral balancing','Frequency masking','Ducking']::text[],ARRAY['Solving masking with large static cuts that thin the source even when the masked part is silent.','Cutting the masked, quieter source instead of dipping the louder masking source.','Assuming more level fixes masking; raising both sources keeps them competing in the same band.']::text[],ARRAY['Freeing vocal intelligibility by ducking a rhythm guitar''s mids only while the vocal is present.','Separating kick and bass by dipping the bass around the kick''s fundamental on each hit.','Keeping a piano from masking a lead vocal in a dense pop mix.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b25475b0-ec5d-5a65-bba1-bdef3514f7d2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral masking control'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b25475b0-ec5d-5a65-bba1-bdef3514f7d2','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b25475b0-ec5d-5a65-bba1-bdef3514f7d2' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8b66978f-00a3-5848-834c-9af32cd51e16','Spectral pocketing','Carving a complementary dip—a pocket—in one source''s spectrum at the frequencies where another source needs to sit, so the second source occupies that space clearly. The pocket can be a static EQ cut or, more musically, a dynamic dip created by frequency-selective sidechain processing that opens only when the featured source is playing.','Spectral pocketing carves a small gap in one sound''s frequencies. Another sound then fits neatly into that gap. It is like clearing a seat so the important part has room.','It exists to make room for a key element, often the vocal, by getting competing sources out of its way in the frequency range where it lives.','An engineer dips synths and guitars around 2–4 kHz where the vocal''s presence sits, often dynamically so the pocket appears only while the vocal sings.','Spectral processing',ARRAY['Spectral masking control','Dynamic EQ','Complementary EQ','Sidechain (key input)','Ducking','Spectral balancing']::text[],ARRAY['Cutting a pocket so deep and wide that the supporting source sounds hollow.','Placing the pocket at the wrong frequency because the featured source''s key range was never identified.','Using a permanent static pocket where a dynamic one would preserve the source when the vocal is silent.']::text[],ARRAY['Making room for a lead vocal by dipping the 2–4 kHz region of a busy guitar bed.','Carving a dynamic pocket in a pad so a lead synth speaks through.','Clearing space for a snare''s crack in a dense drum bus.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8b66978f-00a3-5848-834c-9af32cd51e16' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral pocketing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8b66978f-00a3-5848-834c-9af32cd51e16','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8b66978f-00a3-5848-834c-9af32cd51e16' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e43496ee-5279-587c-bf19-9105a1aa4758','Spectral pumping','An audible, frequency-dependent form of pumping in which a dynamics processor''s gain reduction modulates the tonal balance of the signal rather than only its overall level. It typically arises when strong low-frequency events drive wideband gain reduction that momentarily ducks the whole spectrum, or when the bands of a multiband processor recover at different rates, so the perceived spectrum rhythmically brightens and darkens.','Pumping is when a compressor makes a sound get quieter and louder in a steady rhythm. Spectral pumping means the tone shifts too, not just the volume. Loud bass notes can make the whole sound dip and then brighten again.','The term names a specific compression artifact so engineers can hear it, trace it to its cause, and dial it out. Recognising spectral pumping guides choices of attack, release, sidechain filtering, or multiband settings that keep the tonal balance steady.','When a mix-bus compressor makes the highs seem to breathe in time with the kick drum, an engineer high-pass filters the compressor''s sidechain, slows the release, or switches to multiband so loud lows stop ducking the whole spectrum.','Dynamics Artifact',ARRAY['Pumping','Split-band compression','Sidechain filter','Release time','Two-band compression','Spectral weighting']::text[],ARRAY['Blaming spectral pumping on the source or the monitors instead of the compressor''s release and sidechain settings.','Trying to fix pumping by lowering the ratio alone, when high-pass filtering the sidechain removes the low-frequency trigger more cleanly.','UNSAFE: Chasing subtle pumping by monitoring at very high volume for long periods, risking hearing damage; use safe listening levels and take regular breaks.']::text[],ARRAY['A drum-bus compressor whose release makes the cymbals appear to swell after every kick hit.','A mastering limiter that darkens then brightens the mix in time with prominent bass notes.','A broadcast processor whose bands recover unevenly, causing the voice to shift tone under a music bed.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e43496ee-5279-587c-bf19-9105a1aa4758' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral pumping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e43496ee-5279-587c-bf19-9105a1aa4758','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e43496ee-5279-587c-bf19-9105a1aa4758' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '888e560d-f5b6-5269-8504-639a4f605c01','Spectral target curve','A reference frequency-magnitude profile that a matching or adaptive processor drives a signal toward, so the output''s average spectrum approaches the shape of the target. In tonal-balance and match-EQ tools the target curve may be derived from a reference track, a genre average, or a chosen ideal, and the processor applies EQ or multiband gain to reduce the difference between the signal''s spectrum and the curve.','A spectral target curve is a target shape. It shows how loud each part of a sound should be, from low to high. A matching tool measures your track and nudges its tone toward that shape. It works like a template for the frequency balance.','It gives adaptive EQ and multiband tools a concrete goal, turning a vague idea of balance into a measurable spectrum to aim at. This lets engineers match a reference or hit a genre norm consistently.','A mastering engineer loads a reference song as the target curve, then lets a match-EQ or tonal-balance meter show where their mix is too dark or bright and corrects those bands.','Tonal Balance',ARRAY['Tonal matching','Match EQ','Tonal tilt','Spectral weighting','Reference track','Tonal anchoring']::text[],ARRAY['Matching a target curve exactly and stripping the mix of its character; the curve is a guide, not a rule.','Building the target from a poorly mastered or wrong-genre reference, then chasing a flawed spectrum.','Forgetting that a target curve shows the average spectrum, not moment-to-moment dynamics or arrangement problems.']::text[],ARRAY['Mastering to match the tonal balance of a client''s reference track.','Using a tonal-balance meter''s target region to check that a mix translates across playback systems.','Setting a genre target curve when mastering in an unfamiliar style.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='888e560d-f5b6-5269-8504-639a4f605c01' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral target curve'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
