SELECT '267d5e89-7394-5a73-a0d3-ffe3122d7724','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='267d5e89-7394-5a73-a0d3-ffe3122d7724' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b00cdfce-2bd5-5907-90a4-00712c0d55ed','Tonal anchoring','A mixing practice of establishing and holding a stable tonal reference, so that the spectral balance of a mix or of a key element stays consistent while other elements are adjusted around it. The anchor may be a foundational instrument whose tone is fixed early, or a processing choice such as EQ, multiband dynamics, or a target curve that keeps an element''s frequency balance steady over time.','When mixing, it helps to pick one sound whose tone you trust and keep it steady. Everything else is then balanced against that anchor. It is like tuning a whole band to one reference note.','It stops the mix''s tonal balance from drifting as more elements are added and tweaked, giving a consistent reference point. This keeps decisions grounded instead of chasing a moving target.','An engineer dials in the lead vocal, or the kick and bass, first, fixes that tone as the anchor, then balances guitars and keys so the overall spectrum stays even.','Tonal Balance',ARRAY['Tonal matching','Spectral target curve','Reference track','Tonal tilt','Gain staging','Split-band compression']::text[],ARRAY['Choosing an unstable or poorly recorded element as the anchor, so the whole mix inherits its tonal problems.','Constantly re-EQing the anchor, which defeats the purpose of a fixed reference.','Anchoring only by ear at one loud level; check the balance at low and moderate levels too.']::text[],ARRAY['Setting the kick-and-bass relationship first, then building the rest of the mix around it.','Keeping a lead vocal''s tone fixed as a reference while balancing the backing tracks.','Using a reference track to anchor the target tonal balance for a session.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b00cdfce-2bd5-5907-90a4-00712c0d55ed' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tonal anchoring'),'[^a-z0-9]','','g'));
