SELECT 'b00cdfce-2bd5-5907-90a4-00712c0d55ed','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b00cdfce-2bd5-5907-90a4-00712c0d55ed' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'be6ca8bf-0fac-5a28-ac7d-81dfc7f4d8c3','Tonal matching','The process of adjusting one signal''s spectral balance so that it resembles that of a reference, typically by measuring both spectra and applying corrective EQ (match EQ) or multiband gain to reduce the difference. It is used to make tracks, sections, or takes sound consistent, or to move a mix toward the tonal character of a reference recording.','Tonal matching makes one sound''s tone copy another''s. A tool measures both and then changes the first to match. It is like matching the colour of new paint to a wall you already have.','It creates consistency between sources, or moves a mix toward a trusted reference, and so saves guesswork. This is why match-EQ and tonal-balance tools exist.','An editor uses match EQ to make dialogue recorded on two different days sound like one consistent scene, or a mastering engineer nudges a mix toward a reference track''s balance.','Tonal Balance',ARRAY['Match EQ','Spectral target curve','Tonal anchoring','Reference track','Tonal tilt','Spectral weighting']::text[],ARRAY['Applying a full match and introducing harsh, unnatural EQ curves; blend the match in to taste.','Matching to a reference in a different genre or context, which forces an inappropriate balance.','Trusting tonal matching to fix arrangement or dynamics problems that EQ cannot solve.']::text[],ARRAY['Matching dialogue takes recorded on different days into one seamless scene.','Bringing a mix''s tone closer to a client''s reference track during mastering.','Making layered guitar overdubs share a consistent tonal signature.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='be6ca8bf-0fac-5a28-ac7d-81dfc7f4d8c3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tonal matching'),'[^a-z0-9]','','g'));
