SELECT 'be6ca8bf-0fac-5a28-ac7d-81dfc7f4d8c3','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='be6ca8bf-0fac-5a28-ac7d-81dfc7f4d8c3' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2beeec2a-8bbd-54f2-96e6-de89ec816eb2','Tonal tilt','A broadband spectral adjustment that simultaneously raises one end of the frequency range while lowering the other about a central pivot frequency, tilting the overall balance brighter or darker. It is produced by a tilt (or tilt-shelf) filter, effectively a linked pair of low and high shelves moving in opposite directions, and shifts perceived warmth or brightness with a single control.','Tonal tilt gently leans a sound brighter or darker. As it lifts the highs, it lowers the lows by the same amount, pivoting around a middle point. It works like a see-saw for tone.','It offers a fast, gentle way to shift the whole tonal balance with one control instead of separate boosts and cuts. This makes broad brightness or warmth moves easy and smooth.','To brighten a dull mix, an engineer applies a slight upward tilt so highs rise and lows ease back, changing the overall balance without notching individual bands.','Tonal Balance',ARRAY['Shelving EQ','Tonal matching','Spectral target curve','Tonal anchoring','Split-band saturation','Spectral weighting']::text[],ARRAY['Applying a large tilt and unintentionally gutting the low end while chasing brightness.','Confusing a tilt with a simple high shelf; a tilt also lowers the opposite end of the spectrum.','Forgetting the pivot frequency, which sets where the balance point of the tilt sits.']::text[],ARRAY['Making a broad brightness move on a mix bus with a single tilt control.','Warming an overly bright master by tilting slightly down toward the highs.','Balancing the overall tone of a stem before more detailed EQ.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2beeec2a-8bbd-54f2-96e6-de89ec816eb2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tonal tilt'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2beeec2a-8bbd-54f2-96e6-de89ec816eb2','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2beeec2a-8bbd-54f2-96e6-de89ec816eb2' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9660a6b6-5a7b-51b6-8e3a-a6b9a368e63c','Transient recovery','The preservation or restoration of a signal''s transient (attack) detail that dynamics processing would otherwise soften. It is achieved by choosing slower attack times that let initial peaks pass, by parallel processing that blends back the uncompressed transient, or by transient-shaping or program-dependent release that restores peak energy after gain reduction.','The sharp start of a sound, like a drum hit, is called a transient. Compression can dull that punch. Transient recovery brings the punch back, often by letting the first spike through or by blending in the raw sound.','It keeps the impact and clarity of attacks alive when heavy dynamics control would flatten them. This matters wherever punch and definition are wanted, such as on drums and percussive parts.','After compressing a drum bus, an engineer lengthens the attack or blends in a dry parallel path so the stick attack still cuts through, then adds transient shaping if needed.','Transient Processing',ARRAY['Attack time','Parallel compression','Transient shaper','Transient-triggered ducking','Release time','Split-band compression']::text[],ARRAY['Using a very fast attack that erases transients, then wondering why the drums sound dull.','Trying to recover transients with makeup gain, which raises level without restoring the attack shape.','Over-restoring transients until the result sounds spiky and fatiguing.']::text[],ARRAY['Keeping drum punch after gluing a mix bus with a compressor.','Blending parallel compression so a bass keeps its pick attack.','Using a transient shaper to rebuild snap lost to tracking compression.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9660a6b6-5a7b-51b6-8e3a-a6b9a368e63c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transient recovery'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9660a6b6-5a7b-51b6-8e3a-a6b9a368e63c','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9660a6b6-5a7b-51b6-8e3a-a6b9a368e63c' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '10c60269-36b0-5dea-b6db-1d43dcd7fd43','Transient-triggered ducking','A sidechain technique in which short bursts of gain reduction (ducking) on a target signal are triggered by the transients of a control source rather than by its sustained level. A transient- or peak-sensitive detector responds to the attacks of the source, so the target dips briefly on each hit and quickly recovers, as when a bass is ducked only on the kick drum''s transient.','Ducking means one sound briefly turns another down. Transient-triggered ducking reacts only to sharp hits, not steady sound. So each kick-drum hit makes the bass dip for a moment, then come right back.','It carves brief space for percussive events without pulling the target down for long, keeping loudness and groove intact. This is why it is favoured for kick-versus-bass clarity.','An engineer keys a bass compressor from the kick, set to react to transients, so the bass ducks a few decibels on each kick hit and recovers before the next note.','Sidechain Dynamics',ARRAY['Sidechain compression','Ducking','Transient recovery','Key input','Attack time','Release time']::text[],ARRAY['Setting a slow release so the target stays ducked too long and the groove sags.','Keying from a full-range source so sustained energy, not just transients, triggers the dip.','Ducking too deeply, which turns a subtle clarity move into an obvious pumping effect.']::text[],ARRAY['Ducking a bassline only on each kick transient to keep the low end clear.','Dipping a pad briefly under a snare hit so the snare cuts through.','Creating rhythmic space in a dense electronic mix keyed from the drum transients.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='10c60269-36b0-5dea-b6db-1d43dcd7fd43' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transient-triggered ducking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '10c60269-36b0-5dea-b6db-1d43dcd7fd43','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='10c60269-36b0-5dea-b6db-1d43dcd7fd43' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3fc1a77e-bd14-511f-a5c3-7497ae1a0b75','Two-band compression','A form of multiband (split-band) compression that uses a single crossover to divide the signal into just two frequency bands, a low band and a high band, each compressed independently before recombination. It offers separate dynamic control of the lows versus the highs, for example taming a heavy low end without affecting the treble, with fewer controls and less phase disturbance than many-band designs.','Two-band compression splits a sound into just two parts, low and high, at one crossover point. Each part is compressed on its own. So you can calm a boomy low end without touching the highs.','It provides the core benefit of multiband control, treating lows and highs separately, while staying simple and adding fewer artifacts than splitting into many bands. This suits gentle mastering and bus work.','On a mix bus, an engineer sets the low band to steady an uneven bass and leaves the high band nearly flat, keeping the top end open.','Multiband Dynamics',ARRAY['Split-band compression','Crossover','Wideband compression','Tonal tilt','Makeup gain','Split-band saturation']::text[],ARRAY['Placing the crossover inside an important instrument''s range so it gets split awkwardly between bands.','Assuming two bands are always cleaner; a badly placed crossover still causes phase and tonal shifts.','Over-compressing the low band and thinning the mix''s weight and warmth.']::text[],ARRAY['Steadying a mix''s low end separately from its treble during mastering.','Controlling a bass guitar''s lows without dulling its finger noise and highs.','Applying gentle bus compression with independent low and high control.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3fc1a77e-bd14-511f-a5c3-7497ae1a0b75' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Two-band compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3fc1a77e-bd14-511f-a5c3-7497ae1a0b75','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3fc1a77e-bd14-511f-a5c3-7497ae1a0b75' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5ac0a599-b74d-5d2b-8c7b-b92d1880a5a9','Veil','A subjective descriptor for a perceived loss of clarity, openness, or high-frequency detail, as though a thin cloth were placed over the sound, reducing its transparency and immediacy. In dynamics and tonal processing a veil can result from over-compression, dulled transients, phase smear, or a build-up of low-mid energy that masks fine detail.','A veil is when a sound loses its clear, open quality. It feels like a thin cloth is covering it, hiding the fine detail. Too much compression or muddy low mids can add this dull, covered feeling.','The word gives engineers a shared way to name and discuss a loss of clarity so they can hunt down its cause. Naming the fault is the first step to lifting it.','Hearing a veil over a mix, an engineer checks for over-compression, phase issues, or excess low-mid build-up, then eases the processing or clears the masking frequencies.','Sonic Descriptor',ARRAY['Woolliness','Masking','Transient recovery','Transparency','Over-compression','Tonal tilt']::text[],ARRAY['Fixing a veil by boosting highs, which adds harshness while the real cause, masking or over-compression, remains.','Assuming a veil is always an equipment fault when it often comes from processing choices.','Confusing a dull monitoring chain or room with a veil that is actually in the mix.']::text[],ARRAY['Describing why a heavily compressed mix has lost its openness.','Diagnosing lost clarity after stacking several processors on a bus.','A/B comparing a processed and unprocessed track to hear an added veil.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5ac0a599-b74d-5d2b-8c7b-b92d1880a5a9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Veil'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5ac0a599-b74d-5d2b-8c7b-b92d1880a5a9','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5ac0a599-b74d-5d2b-8c7b-b92d1880a5a9' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '69ff085f-349e-50a3-bbd0-b3b5d05866f2','Wet-path phase rotation','The intentional application of an all-pass phase-rotation stage to only the processed (wet) signal path of a dynamics or parallel-processing chain, altering the phase of the wet signal versus the unprocessed (dry) path. Because an all-pass filter shifts phase across frequency without changing magnitude, rotating the wet path changes how wet and dry sum, and can symmetrise an asymmetrical waveform so a compressor or limiter reacts more evenly.','A phase rotator shifts the timing of the waves in a sound. It does not change how loud the sound is. Here it is put on only the treated copy. That changes how the copy blends with the first one. Engineers use it to even out uneven waves. A compressor can then grab them more evenly.','It exists to reshape a waveform''s phase so peaks sit more symmetrically, letting dynamics processing act more consistently, and to manage how a wet path combines with the dry signal. Applying it only to the wet path keeps the dry signal untouched.','On a parallel or broadcast chain, an engineer inserts a phase rotator on the compressed path so an asymmetrical vocal or brass waveform is tamed more evenly, without altering the dry blend.','Phase Processing',ARRAY['All-pass filter','Phase rotation','Parallel compression','Wet/dry mix','Transient recovery','Split-band compression']::text[],ARRAY['Expecting phase rotation to change tone; an all-pass filter shifts phase but leaves the magnitude response flat.','Rotating both wet and dry paths equally, which cancels the intended wet-versus-dry difference.','Ignoring that combining a phase-rotated wet path with the dry signal can cause partial comb-filter cancellation.']::text[],ARRAY['Symmetrising an asymmetrical vocal waveform before a broadcast limiter for more even control.','Adjusting the phase of a parallel-compressed path to change how it sums with the dry signal.','Evening out a brass or reed part whose lopsided waveform makes a compressor react unevenly.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='69ff085f-349e-50a3-bbd0-b3b5d05866f2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wet-path phase rotation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '69ff085f-349e-50a3-bbd0-b3b5d05866f2','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='69ff085f-349e-50a3-bbd0-b3b5d05866f2' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '25e7a459-39ce-5021-9cea-dfcd3565c0f0','Woolliness','A subjective descriptor for excessive, poorly defined energy in the lower midrange, roughly the low hundreds of hertz, that makes a sound thick, muddy, and lacking in definition or tightness. In dynamics processing woolliness can arise or worsen when low-band compression or saturation blurs transients and swells sustained low-mid content.','Woolliness is when a sound has too much thick, low-middle tone. It gets muddy and loses its clear edges, like wearing a heavy wool sweater. The low mids blur together instead of staying tight.','The term names a specific low-mid muddiness so engineers can target it with EQ or cleaner dynamics settings. A shared word speeds up spotting and fixing the problem.','Finding a mix woolly, an engineer cuts a few decibels in the low mids, tightens the low-band compression, or eases saturation there to restore definition.','Sonic Descriptor',ARRAY['Veil','Muddiness','Low mids','Split-band compression','Split-band saturation','Masking']::text[],ARRAY['Cutting the true low end to fix woolliness when the problem sits higher, in the low mids.','Adding more low-band compression, which can thicken and blur rather than tighten.','Mistaking a boomy room or untreated monitoring for woolliness in the recording.']::text[],ARRAY['Cleaning up a muddy overlap between bass and guitar in the low mids.','Diagnosing why a dense mix sounds thick and undefined.','Reducing low-mid build-up after multiband processing adds weight.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='25e7a459-39ce-5021-9cea-dfcd3565c0f0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Woolliness'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '25e7a459-39ce-5021-9cea-dfcd3565c0f0','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='25e7a459-39ce-5021-9cea-dfcd3565c0f0' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9b658c75-8cd6-5c44-a84a-2f45f75a2897','Above-bell miking','A close-miking placement in which the microphone sits above the bell of a wind or brass instrument and is angled down toward the tone holes and keywork rather than pointing straight into the bell''s mouth. It captures a blend of bell radiation and tone-hole radiation, giving a fuller, less harsh tone while still offering good level and stage separation.','The microphone is placed above the horn''s bell, tilted down toward the finger holes. It picks up sound from the bell and the holes at once. This gives a warmer, more natural tone than aiming straight into the bell.','It exists to avoid the harsh, midrange-heavy sound and loud blast you get by aiming into the bell, while keeping the level and isolation that close miking provides. Blending bell and tone-hole sound yields a more balanced, playable tone.','On a loud stage a saxophone or trumpet player uses a clip or stand mic set just above the bell and tilted toward the keys, so the engineer gets separation without the honky bell sound.','Wind Instrument Miking',ARRAY['Across-bell miking','Bell-axis miking','Bell-blast avoidance','Proximity effect','Polar pattern','Off-axis coloration']::text[],ARRAY['Aiming the mic straight down into the bell, which produces a harsh, honky, midrange-heavy tone.','Placing the mic so close that valve, key, and breath noise become obvious in the recording.','UNSAFE: Leaning in to monitor a loud brass or reed bell at close range without hearing protection; peaks can exceed 140 dB SPL (sound pressure level) and damage hearing.']::text[],ARRAY['Miking a saxophone on a loud stage where a clip mic rides above the bell aimed at the keys.','Recording a trumpet section where engineers want level and separation without bell harshness.','Live worship or theatre pits where wind players need isolation from nearby monitors.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9b658c75-8cd6-5c44-a84a-2f45f75a2897' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Above-bell miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9b658c75-8cd6-5c44-a84a-2f45f75a2897','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9b658c75-8cd6-5c44-a84a-2f45f75a2897' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a0eaac9f-1ecb-519c-b355-28ce9166b1dc','Acoustic-guitar bridge miking','A close-miking placement in which the microphone is aimed at or near the bridge and lower bout of an acoustic guitar rather than at the sound hole or the 12th fret. This position emphasizes body resonance and lower-midrange warmth while avoiding the exaggerated boom that comes from miking directly over the sound hole.','The microphone points at the bridge, where the strings meet the guitar''s body. This spot gives a warm, full tone with plenty of body. It avoids the boomy, muddy sound you get right over the round hole.','It exists to capture the guitar''s warmth and body without the low-frequency buildup that the sound hole radiates, giving a tone that sits well in a mix. It also offers a different flavor to blend with a fret-side mic.','A studio engineer places a small-diaphragm condenser a short distance from the bridge, often paired with a 12th-fret mic, to blend body warmth with string detail.','Guitar Miking',ARRAY['Bass-side bridge miking','Sound-hole miking','12th-fret miking','Proximity effect','3:1 rule','Small-diaphragm condenser']::text[],ARRAY['Confusing the bridge position with the sound hole and ending up with a boomy, bass-heavy tone.','Placing a directional mic so close that proximity effect over-boosts the low end.','Pairing a bridge mic and a fret mic without checking phase, which thins or hollows the combined sound.']::text[],ARRAY['Recording a solo fingerstyle guitar where warmth and body are wanted.','Blending a bridge mic with a 12th-fret mic for a full, detailed acoustic sound.','Reducing sound-hole boom on a dreadnought guitar by moving the mic toward the bridge.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a0eaac9f-1ecb-519c-b355-28ce9166b1dc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Acoustic-guitar bridge miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a0eaac9f-1ecb-519c-b355-28ce9166b1dc','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a0eaac9f-1ecb-519c-b355-28ce9166b1dc' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '453417b3-de2e-53d1-bd89-ef4048668fd5','Across-bell miking','A placement in which the microphone is positioned to the side of a brass or wind bell so the diaphragm looks across the mouth of the bell rather than straight down its axis. Working off the bell''s axis tames the bright, aggressive on-axis highs and reduces bell blast while preserving level and separation.','The microphone sits to the side and looks across the mouth of the bell, not into it. Aiming into the bell sounds bright and harsh. Looking across it softens that edge while still capturing a strong signal.','It exists to control the harsh high-frequency beam and sudden loud blast that a brass bell throws straight ahead, giving a smoother tone. Off-axis placement trades some brightness for a more usable, less fatiguing sound.','An engineer angling a mic across a trumpet or trombone bell, often up to about 45 degrees off axis, softens the highs when the on-axis sound is too edgy.','Wind Instrument Miking',ARRAY['Bell-axis miking','Above-bell miking','Bell-blast avoidance','Off-axis coloration','Proximity effect','Polar pattern']::text[],ARRAY['Assuming off-axis placement alone removes harshness, when mic choice and headroom also matter.','Angling so far off axis that the tone becomes dull and loses presence and projection.','UNSAFE: Placing your ear or an unprotected mic capsule directly in a brass bell''s on-axis blast, where peaks exceed 140 dB SPL (sound pressure level).']::text[],ARRAY['Taming a bright trumpet by angling the mic across the bell instead of into it.','Recording a trombone where straight-on placement sounds too aggressive.','Live brass sections that need level and separation without piercing highs.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='453417b3-de2e-53d1-bd89-ef4048668fd5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Across-bell miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '453417b3-de2e-53d1-bd89-ef4048668fd5','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='453417b3-de2e-53d1-bd89-ef4048668fd5' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a8ea84e6-e730-56c7-bd02-a0bb28597e08','Amp reamping','A studio technique in which a previously recorded dry direct signal, usually a DI (direct injection) guitar or bass track, is played back out of the interface, passed through a reamp box, and fed into a real instrument amplifier so it can be re-amplified and re-miked. The reamp box converts the balanced, line-level output back to the unbalanced, high-impedance, instrument-level signal an amp input expects.','You record a clean guitar or bass straight into the interface, with no amp. Later you send that clean track back out through an amplifier and record it with a microphone. A reamp box matches the signal so the amp behaves like a real instrument is plugged in.','It exists so tone decisions, such as amp, settings, and mic choice, can be made or redone after tracking, without asking the player to perform again. It also lets one clean take drive several different amp sounds.','A mix engineer runs a saved DI guitar track out through a reamp box into a cranked amp, mics the cabinet, and dials in the tone that fits the finished mix.','Amp Recording',ARRAY['Direct injection','DI box','Impedance matching','Cabinet miking','Ground loop','Proximity effect']::text[],ARRAY['Feeding a line-level output straight into an amp without a reamp box, causing impedance and tone mismatch.','Forgetting to record a clean DI track during tracking, so there is nothing to reamp later.','UNSAFE: Lifting the amplifier''s safety ground to chase a ground-loop hum instead of using the reamp box''s isolated ground lift; a floating chassis is a shock hazard.']::text[],ARRAY['Re-recording guitar tones during mixdown after the band has left the studio.','Driving several different amps from one clean bass DI to compare sounds.','Fixing a poorly captured amp take by reamping the saved direct signal.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a8ea84e6-e730-56c7-bd02-a0bb28597e08' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Amp reamping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a8ea84e6-e730-56c7-bd02-a0bb28597e08','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a8ea84e6-e730-56c7-bd02-a0bb28597e08' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f56134d9-c7c3-588c-b698-69276701a8a1','Bass audibility enhancement','Processing that makes low-frequency content perceptible on loudspeakers and earbuds that cannot reproduce the true fundamental, by generating or emphasizing harmonics of that fundamental. The ear reconstructs the pitch of the missing fundamental from its harmonic series, a psychoacoustic effect known as the missing or virtual fundamental, so the bass is heard even when the lowest frequency is absent.','Small speakers and earbuds cannot really play very low bass notes. This trick adds higher tones that belong to the bass note. Your ear fills in the low note it cannot actually hear, so the bass still seems present.','It exists so bass lines translate on phones, laptops, and small speakers that roll off deep low end. By adding harmonics, it preserves the sense of pitch and weight without needing real subsonic energy.','A mix engineer uses a psychoacoustic bass enhancer on a bass or kick to keep the groove audible on phone speakers, checking that it still sounds clean on full-range monitors.','Low-Frequency Processing',ARRAY['Missing fundamental','Harmonic generation','Bass fundamental stabilization','Bass-band splitting','Harmonic distortion','Fundamental frequency']::text[],ARRAY['Overusing harmonic enhancement until the bass sounds buzzy or distorted on good systems.','Assuming added harmonics replace real low end; full-range systems still need the true fundamental.','Checking the effect only on one speaker instead of across small and full-range playback.']::text[],ARRAY['Making a bass line audible on laptop and phone speakers during a mix.','Adding perceived weight to a kick drum on club or broadcast systems with limited low end.','Restoring apparent bass to material that was high-pass filtered too aggressively.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f56134d9-c7c3-588c-b698-69276701a8a1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bass audibility enhancement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f56134d9-c7c3-588c-b698-69276701a8a1','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f56134d9-c7c3-588c-b698-69276701a8a1' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd9d2d7c7-a64f-5695-9086-fcd8040269d1','Bass fundamental stabilization','The use of processing to keep the fundamental frequency of a bass instrument even and controlled in level so the low end stays solid from note to note. It typically combines gentle compression, targeted equalization, and sometimes low-frequency mono-summing to stop the fundamental from jumping in loudness across the fretboard or between notes.','Some bass notes ring out much louder than others because of the room and the instrument. Stabilizing the fundamental evens them out. This keeps the low notes steady and even, so no single note booms out.','It exists because uneven note-to-note bass level makes a mix feel lumpy and hard to master. Steadying the fundamental gives a consistent low end that holds up across playback systems.','An engineer tames a bass part where the low E jumps out by using compression, a narrow cut on the loud note, and keeping the deep low end in mono.','Low-Frequency Processing',ARRAY['Fundamental frequency','Bass audibility enhancement','Bass-band splitting','Compression','Mono bass','Resonance control']::text[],ARRAY['Cutting or compressing so hard that the bass loses life and sounds flat and lifeless.','Blaming the instrument for uneven notes when the room and monitors are coloring the low end.','Leaving deep low frequencies out of phase or in wide stereo, which weakens the fundamental.']::text[],ARRAY['Evening out a bass guitar whose open strings boom louder than fretted notes.','Preparing a bass stem for mastering so the low end stays consistent.','Controlling a synth bass whose fundamental level shifts between patches or notes.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d9d2d7c7-a64f-5695-9086-fcd8040269d1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bass fundamental stabilization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd9d2d7c7-a64f-5695-9086-fcd8040269d1','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d9d2d7c7-a64f-5695-9086-fcd8040269d1' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7155f3d0-1f34-596e-82c2-7d6e2db63c1f','Bass-band splitting','Dividing a bass signal into two or more frequency bands with a crossover so each band can be processed separately before being recombined. A common form keeps the low band clean for weight and stability while distortion, saturation, or amp tone is applied only to the upper band for definition and audibility.','The bass sound is split into a low part and a higher part. The deep low part is kept clean and solid. The higher part can be distorted or shaped so the bass cuts through, then the two are mixed back together.','It exists so you can add grit or presence to a bass without turning the deep low end to mush. Splitting the bands lets each range get the treatment it needs.','An engineer splits a bass DI at a crossover, leaves the lows clean, distorts the highs so the part is heard on small speakers, then blends the bands.','Low-Frequency Processing',ARRAY['Crossover','Multiband compression','Parallel processing','Bass audibility enhancement','Direct injection','Amp reamping']::text[],ARRAY['Setting the crossover too high, so distortion reaches the deep lows and muddies the sub range.','Losing level or phase alignment when recombining the bands, thinning the bass.','Distorting the whole bass instead of just the upper band, which weakens the low-end weight.']::text[],ARRAY['Splitting a bass into clean lows and a distorted top for a rock or metal mix.','Blending a clean DI low band with a miked amp band that carries the grit.','Multiband processing of a synth bass to control lows and add presence separately.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7155f3d0-1f34-596e-82c2-7d6e2db63c1f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bass-band splitting'),'[^a-z0-9]','','g'));
