WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7155f3d0-1f34-596e-82c2-7d6e2db63c1f' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6346153c-46c2-5b9a-b911-535d39643c3d','Bass-side bridge miking','A close-miking placement on an acoustic guitar in which the microphone is aimed at the bridge on the bass-string side of the lower bout. This position emphasizes the low strings and the body''s low-midrange warmth, giving a fuller, rounder tone than a treble-side or sound-hole placement.','The microphone points at the bridge on the thick-string side of the guitar. This side gives more low, warm tone from the bass strings. It sounds fuller and rounder than aiming at the thin-string side.','It exists to bring out the warmth and low-string body of an acoustic guitar, useful when a part needs to sound rich and full. It also gives a contrasting tone to blend with a brighter treble-side or fret mic.','An engineer aims a small-diaphragm condenser at the bass side of the bridge to add warmth, then blends it with a 12th-fret mic for balance.','Guitar Miking',ARRAY['Acoustic-guitar bridge miking','12th-fret miking','Sound-hole miking','Proximity effect','3:1 rule','Small-diaphragm condenser']::text[],ARRAY['Placing the mic too close to the sound hole side and picking up boomy low-frequency buildup.','Relying on the bass side alone, so the recording lacks string and pick detail.','Combining it with a second mic without checking phase, which hollows out the tone.']::text[],ARRAY['Warming up a thin-sounding acoustic guitar by favoring the bass side of the bridge.','Building a two-mic acoustic setup that pairs a warm bass-side mic with a bright fret mic.','Recording fingerstyle parts that need strong low-string body.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6346153c-46c2-5b9a-b911-535d39643c3d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bass-side bridge miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6346153c-46c2-5b9a-b911-535d39643c3d','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6346153c-46c2-5b9a-b911-535d39643c3d' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd374f8d9-9107-581d-afc7-4ce4be6ff832','Bassoon bocal-side miking','A close-miking placement for bassoon in which the microphone favors the upper, bocal (crook) side of the instrument, near the wing joint and upper tone holes rather than the bell. Because the bassoon radiates most of its sound from the tone holes rather than the bell, aiming toward the upper tone holes captures a natural, present tone.','A bassoon does not send its sound out of the bell like a trumpet. Most sound comes from the finger holes along the body. This placement points the mic toward the upper holes, near the curved metal crook, for a natural tone.','It exists to capture the bassoon''s true voice, which comes from the tone holes, instead of the thin, uneven sound you get pointing at the bell. Favoring the upper holes gives presence and clarity.','An engineer places a mic roughly 15 to 20 cm from the upper tone holes on the bocal side, aiming at the holes rather than into the bell.','Woodwind Miking',ARRAY['Bassoon boot-joint miking','Tone-hole radiation','Above-bell miking','Proximity effect','Polar pattern','Spot microphone']::text[],ARRAY['Pointing the mic into the bell, which gives a thin, unnatural, and uneven tone.','Placing the mic so close that key and pad noise dominate the sound.','Using a very tight cardioid up close, which captures an unnaturally focused, boxy tone.']::text[],ARRAY['Spot-miking a bassoon in an orchestral session for extra presence.','Close-miking a bassoon in a chamber recording where the tone-hole side gives the most natural sound.','Recording solo bassoon where clarity of the upper register is important.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d374f8d9-9107-581d-afc7-4ce4be6ff832' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bassoon bocal-side miking'),'[^a-z0-9]','','g'));
