WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d374f8d9-9107-581d-afc7-4ce4be6ff832' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0231e76b-9536-5be1-bc70-cf34cfa87bba','Bassoon boot-joint miking','A close-miking placement for bassoon in which the microphone is aimed at the lower body around the boot joint, where the instrument''s tube doubles back and many lower tone holes cluster. Because the bassoon radiates from its tone holes rather than the bell, a mic roughly one-third of the instrument''s length up from the bell, aimed at these holes, captures a balanced, natural tone.','The boot joint is the U-shaped section at the bottom of a bassoon. Many finger holes sit here. Aim the mic at this area, about a third of the way up from the bell. That gives a full, natural bassoon sound.','It exists to capture the bassoon''s rich lower body from where the sound actually leaves the instrument, avoiding the thin tone of bell placement. It gives a balanced blend of the lower tone holes.','An engineer positions a mic about 15 to 20 cm away, roughly a third of the way up from the bell toward the boot joint, aiming at the tone holes.','Woodwind Miking',ARRAY['Bassoon bocal-side miking','Tone-hole radiation','Above-bell miking','Spot microphone','Proximity effect','Polar pattern']::text[],ARRAY['Aiming into the bell instead of the tone holes, producing a thin and unnatural sound.','Getting so close that mechanical key noise and breathing overwhelm the tone.','Assuming the bassoon projects from the bell like a brass instrument, and mispositioning the mic.']::text[],ARRAY['Spot-miking the lower register of a bassoon in an orchestral recording.','Close-miking a bassoon for a chamber session where the boot-joint area gives a full tone.','Reinforcing a bassoon on stage with a clip mic aimed at the lower body.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0231e76b-9536-5be1-bc70-cf34cfa87bba' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bassoon boot-joint miking'),'[^a-z0-9]','','g'));
