SELECT '0231e76b-9536-5be1-bc70-cf34cfa87bba','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0231e76b-9536-5be1-bc70-cf34cfa87bba' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e03fd2b6-9291-5d9d-b7bb-f82662a93900','Batter-side kick microphone','A microphone placed on the batter-head (beater) side of a kick drum, the head the drummer strikes, to capture the attack and click of the beater impact. Compared with a resonant-side or outside placement it emphasizes attack and definition but tends to pick up more bleed from the rest of the kit.','The batter head is the drum head the pedal beater hits. A mic on this side hears the sharp click of the beater. It captures strong attack, but also picks up more spill from nearby drums.','It exists to capture the punch and click of the kick, which helps the drum cut through a dense mix. Engineers often blend it with a resonant-side or sub mic that supplies the low-end weight.','An engineer positions a mic inside the drum facing the batter head near the beater to get click and attack, then blends it with an outside mic for body.','Drum Miking',ARRAY['Resonant-head kick microphone','Kick-drum port hole','Beater attack','Proximity effect','Phase alignment','Gate']::text[],ARRAY['Expecting the batter-side mic alone to deliver deep low end, when it mainly captures attack.','Ignoring phase when combining it with a resonant-side or sub mic, thinning the low end.','UNSAFE: Working inside or right at a kick drum, which can peak above 150 dB SPL (sound pressure level) at close range, without hearing protection.']::text[],ARRAY['Adding beater click to a rock kick by placing a mic near the batter head.','Building a two-mic kick setup with a batter mic for attack and an outside mic for weight.','Getting definition from a kick that sounds dull and boomy on its own.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e03fd2b6-9291-5d9d-b7bb-f82662a93900' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Batter-side kick microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e03fd2b6-9291-5d9d-b7bb-f82662a93900','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e03fd2b6-9291-5d9d-b7bb-f82662a93900' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8829b7fb-59e3-567e-8150-e7864b06c2e3','Bell-axis miking','A placement in which the microphone is aimed straight down the central axis of a brass or wind bell, directly on-axis with its opening. It yields the brightest, most direct sound and the highest level and separation, but also the harshest highs and the greatest risk of bell blast.','The microphone points straight into the middle of the bell. This gives the brightest, loudest, and most direct sound. It can also be harsh, because the bell throws its sharpest highs straight ahead.','It exists when maximum level, attack, and isolation are the priority, such as a loud stage, accepting a brighter and more aggressive tone. On-axis placement captures the bell''s most focused high-frequency output.','An engineer aims a mic on-axis at a trumpet bell for a bright, cutting lead sound on a loud stage, often adding a pad or high-SPL mic to handle the level.','Wind Instrument Miking',ARRAY['Across-bell miking','Bell-edge miking','Bell-blast avoidance','Off-axis coloration','Proximity effect','Polar pattern']::text[],ARRAY['Using on-axis placement when a warm tone is wanted, then fighting harshness later.','Overloading the mic or preamp with the high on-axis level instead of using a pad or high-SPL mic.','UNSAFE: Positioning your head beside an on-axis brass bell, where peaks exceed 140 dB SPL (sound pressure level), without ear protection.']::text[],ARRAY['Capturing a bright, cutting trumpet lead on a loud stage.','Recording a brass section where separation and attack matter more than warmth.','Reinforcing solo brass that must project over a loud band.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8829b7fb-59e3-567e-8150-e7864b06c2e3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bell-axis miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8829b7fb-59e3-567e-8150-e7864b06c2e3','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8829b7fb-59e3-567e-8150-e7864b06c2e3' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6d2a0091-1007-519a-80bc-88f3b66d3eec','Bell-blast avoidance','The practice of preventing the harsh, overloud burst of sound produced when a microphone is aimed straight into a brass bell during loud passages. It is achieved by placing the mic off the bell''s axis, increasing distance, angling the capsule, and choosing a microphone with enough headroom to handle high peak sound pressure levels.','Point a mic straight into a loud brass bell and you get a harsh, blasting sound. Bell-blast avoidance means stopping that. You move the mic off to the side, add distance, or angle it so the blast is softened.','It exists to protect both the sound quality and the microphone from the intense, focused blast a brass bell throws forward at high volume. Managing it keeps the tone smooth and avoids overload.','An engineer angles the mic across or above the bell, backs it off, or engages a pad so loud brass hits stay clean instead of harsh and distorted.','Wind Instrument Miking',ARRAY['Across-bell miking','Bell-axis miking','Above-bell miking','Pad','Off-axis coloration','Proximity effect']::text[],ARRAY['Fixing bell blast only with equalization instead of moving the mic off axis first.','Ignoring the microphone''s maximum sound pressure level and overloading it on loud hits.','UNSAFE: Monitoring a brass bell blast at close range without hearing protection; peaks exceed 140 dB SPL (sound pressure level).']::text[],ARRAY['Recording a loud trumpet where straight-on placement distorts on peaks.','Live brass sections that overload close mics during fortissimo passages.','Capturing a big-band horn line without harsh, blasting highs.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6d2a0091-1007-519a-80bc-88f3b66d3eec' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bell-blast avoidance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6d2a0091-1007-519a-80bc-88f3b66d3eec','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6d2a0091-1007-519a-80bc-88f3b66d3eec' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '432d7d06-2b57-5a65-858c-43cad263567c','Bell-edge miking','A placement in which the microphone is aimed at the rim or edge of a brass or wind bell rather than its center. Because the harshest, most focused high frequencies beam straight out of the bell''s center, aiming at the edge softens those highs while keeping good level and projection.','The microphone points at the outer rim of the bell, not the middle. The sharpest, harshest highs shoot out of the center. Aiming at the edge tames those highs while still catching a strong sound.','It exists to balance brightness and warmth, giving less harshness than dead-center placement but more presence than a fully off-axis position. It is a middle-ground bell technique.','An engineer aims a mic at the edge of a trumpet or saxophone bell to keep presence and cut while rounding off the piercing on-axis highs.','Wind Instrument Miking',ARRAY['Bell-axis miking','Across-bell miking','Bell-flare proximity miking','Off-axis coloration','Proximity effect','Polar pattern']::text[],ARRAY['Confusing edge placement with dead-center placement and keeping the harshness you meant to reduce.','Moving too far past the edge, so the tone loses presence and projection.','Forgetting that the highest frequencies beam narrowly, so small aim changes shift the tone a lot.']::text[],ARRAY['Softening a bright trumpet by aiming at the bell rim instead of the center.','Balancing presence and warmth on a saxophone bell.','Recording brass where a fully off-axis mic sounds too dull.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='432d7d06-2b57-5a65-858c-43cad263567c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bell-edge miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '432d7d06-2b57-5a65-858c-43cad263567c','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='432d7d06-2b57-5a65-858c-43cad263567c' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9e5e7b87-45a4-5189-a740-992ad0046f22','Bell-flare proximity miking','A very close placement in which the microphone sits right at the flare of a brass or wind bell, only centimetres away. It delivers maximum level and separation but brings strong proximity effect with directional mics, a harsh on-axis tone, and a high risk of bell blast and overload.','The microphone is placed right at the edge of the flared bell, only a few centimetres away. This gives the loudest, most isolated sound. Being so close also boosts the bass and makes the tone harsh and easy to overload.','It exists for loud stages and situations that demand the most level and isolation, such as clip-on horn mics. The trade-off is a colored, bass-boosted, harsh tone that usually needs correction.','A live engineer uses a clip mic mounted at the bell flare of a trumpet to get level and separation, then rolls off excess low end and harshness.','Wind Instrument Miking',ARRAY['Bell-edge miking','Bell-axis miking','Bell-blast avoidance','Proximity effect','Off-axis coloration','Pad']::text[],ARRAY['Ignoring the strong proximity bass boost, leaving a boomy, unnatural low end.','Overloading the mic or preamp on loud peaks instead of using a pad or high-SPL capsule.','UNSAFE: Placing an ear near a brass bell flare at close range, where peaks exceed 140 dB SPL (sound pressure level), without hearing protection.']::text[],ARRAY['Clip-on horn mics mounted at the bell for loud live shows.','Getting maximum separation from a brass section on a crowded stage.','Miking a single horn that must be isolated from loud nearby instruments.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9e5e7b87-45a4-5189-a740-992ad0046f22' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bell-flare proximity miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9e5e7b87-45a4-5189-a740-992ad0046f22','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9e5e7b87-45a4-5189-a740-992ad0046f22' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd43b353c-74f0-550e-bc12-06ecacf9cdca','Bell-shadow placement','A close-miking approach for brass and woodwind instruments in which the microphone is set off the central axis of the bell, in the region shielded from the bell''s most directional high-frequency radiation (the bell''s acoustic shadow), to tame on-axis harshness while preserving body and blend. Because a flared bell becomes progressively more directional as frequency rises, an off-axis position attenuates the brightest, most strident components without a large increase in distance.','A trumpet or clarinet bell beams its harshest highs straight ahead. Bell-shadow placement moves the mic off to the side, out of that beam. The sound stays full but less shrill. Think of stepping out of a spotlight''s direct glare.','It softens a bell''s aggressive on-axis treble without moving the mic far away, so level and body are preserved. It works because flared bells radiate high frequencies in a narrow forward beam that eases off to the sides.','When a trumpet reads shrill straight-on, an engineer angles the mic off the bell axis, into the bell shadow, to smooth the highs while keeping close-mic presence.','Brass/Wind Miking',ARRAY['Off-axis placement','Proximity effect','Polar pattern','Bell–tone-hole balance','Clarinet bell-overemphasis','Instrument directivity']::text[],ARRAY['Confusing bell-shadow placement with simply moving farther away; the point is the off-axis angle, not distance.','Going so far off-axis that the tone turns dull and loses attack.','UNSAFE: Putting your ear or the mic directly in front of a loud brass bell at close range to judge tone; woodwind and brass peaks can exceed 140 dB SPL and threaten hearing, so keep clear and use hearing protection.']::text[],ARRAY['Taming a bright trumpet in a close-miked horn section.','Recording a clarinet where straight-on bell aim sounds strident.','Live-miking a saxophone bell that reads harsh through the PA.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d43b353c-74f0-550e-bc12-06ecacf9cdca' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bell-shadow placement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd43b353c-74f0-550e-bc12-06ecacf9cdca','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d43b353c-74f0-550e-bc12-06ecacf9cdca' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '82ba86f0-6384-512d-8260-ed9936de9a6e','Bell–tone-hole balance','In woodwind miking, the deliberate balancing of sound captured from the instrument''s bell against sound radiating from its open tone (finger) holes, since a woodwind''s timbre is a blend of both sources whose relative contribution changes with the notes played. Placement and aim — typically toward the keys, roughly a third of the tube length up from the bell and about 15–20 cm away — set this balance.','A clarinet or oboe makes sound from two places: the open finger holes and the bell. Bell–tone-hole balance means aiming the mic to blend both fairly. Most notes come from the holes. Aiming only at the bell throws the tone off.','It yields an even, natural woodwind tone across the range, because most notes speak from the tone holes while only the lowest notes lean on the bell. Getting it right avoids an uneven, honky, or thin sound.','An engineer places the mic about 15–20 cm out, a third of the way up from the bell, aimed at the keys, to blend tone-hole and bell output rather than favoring either.','Woodwind Miking',ARRAY['Bell-shadow placement','Clarinet bell-overemphasis','Off-axis placement','Proximity effect','Instrument directivity','Polar pattern']::text[],ARRAY['Aiming straight into the bell, which overrepresents the lowest notes and the harshest highs and unbalances the tone.','Assuming all woodwind sound comes from the bell like a trumpet; most notes radiate from the open holes.','Placing the mic so close to moving keys that key-click and pad noise dominate.']::text[],ARRAY['Close-miking a clarinet for a jazz combo so all registers sound even.','Miking an oboe or bass clarinet where low notes lean on the bell.','Positioning a clip-on woodwind mic to blend holes and bell on stage.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='82ba86f0-6384-512d-8260-ed9936de9a6e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bell–tone-hole balance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '82ba86f0-6384-512d-8260-ed9936de9a6e','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='82ba86f0-6384-512d-8260-ed9936de9a6e' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '64650fe1-e7c0-5588-909a-9520529e9d85','Body-and-neck stereo miking','A two-microphone technique for an acoustic stringed instrument, typically guitar, in which one microphone is placed near the body (lower bout / behind the bridge) and a second near the neck (around the 12th–14th fret), the pair panned to build a stereo image that combines the body''s warmth and low end with the neck''s articulation and string detail. Mic spacing should respect the 3:1 rule to limit comb filtering when the pair is summed to mono.','This uses two mics on one acoustic guitar. One sits near the body for warmth and low notes. The other sits near the neck for string detail. Panning them apart makes a wide stereo sound. Keep them spaced so they still work in mono.','It captures two complementary areas of the instrument so the recording sounds both full and detailed and can be spread across the stereo field. Splitting the sources lets the engineer balance warmth against articulation.','On a solo acoustic guitar, an engineer aims one mic near the 12th fret and another at the lower bout behind the bridge, then pans them apart for a wide, detailed track.','Guitar Miking',ARRAY['Neck miking','Sound-hole miking','3:1 rule','Stereo miking','Proximity effect','Comb filtering']::text[],ARRAY['Placing the two mics too close together and ignoring the 3:1 rule, causing comb filtering when summed to mono.','Pointing a mic straight at the sound hole, which captures a boomy, unnatural low-end resonance.','Panning hard left and right without checking mono compatibility for broadcast or a club PA.']::text[],ARRAY['Recording a fingerstyle acoustic guitar as a wide stereo feature.','Tracking singer-songwriter guitar that must also fold down to mono.','Capturing a bright, detailed nylon-string guitar for a duo.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='64650fe1-e7c0-5588-909a-9520529e9d85' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Body-and-neck stereo miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '64650fe1-e7c0-5588-909a-9520529e9d85','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='64650fe1-e7c0-5588-909a-9520529e9d85' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2141db67-953e-5f8b-8edc-a535edcfb23c','Bow-contact-point miking','A close-miking approach for bowed string instruments in which the microphone is aimed at the point where the bow contacts the strings, between the bridge and the fingerboard, the region that most directly reflects bowing style and its harmonic content. Because timbre shifts from bright and edgy near the bridge (sul ponticello) to mellow near the fingerboard (sul tasto), the aim captures the player''s articulation and attack.','A bow makes different tones depending on where it touches the string. Near the bridge sounds bright and scratchy. Near the fingerboard sounds soft. This technique aims the mic at that contact spot to catch the playing detail.','It emphasizes bow articulation and attack, giving a present, detailed string sound that tracks how the player bows. It exists because the contact point strongly shapes the harmonic content.','On a close-miked violin, an engineer points the mic toward the bow''s contact area to capture bite and articulation, then adjusts distance to manage bow noise.','String Miking',ARRAY['Bow-noise balance','Bow-side miking','Bridge-axis miking','Bridge-above miking','Proximity effect','Off-axis placement']::text[],ARRAY['Miking right over the bridge and getting a thin, glassy, scratchy tone that exaggerates bow noise.','Placing the mic so close it captures mostly rosin scratch and loses the body''s warmth.','Forgetting that the contact point moves as the player changes bowing style, so a fixed aim favors one articulation.']::text[],ARRAY['Recording an expressive solo violin where bow articulation is the feature.','Close-miking a cello passage that alternates near-bridge and near-fingerboard bowing.','Capturing an aggressive bowed double bass line for a folk track.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2141db67-953e-5f8b-8edc-a535edcfb23c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bow-contact-point miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2141db67-953e-5f8b-8edc-a535edcfb23c','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2141db67-953e-5f8b-8edc-a535edcfb23c' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6c3102bc-2b96-5aaa-8ca8-fff9ba74da1f','Bow-noise balance','The control of how much bow-and-string noise — rosin scratch, hair contact, and articulation transients — is captured relative to the instrument''s tonal body, managed through mic distance, angle, and placement between bridge and body. Closer, more bridge-facing positions increase bow noise, while positions farther from the contact point or more toward the body reduce it.','A bow dragging across strings adds a scratchy, hissy noise on top of each note. Bow-noise balance means placing the mic to get enough of that grit but not too much. Move the mic closer for more scratch, farther for less.','It sets how present and lifelike the string attack sounds without the recording being swamped by scratch and hair noise. Balancing it keeps articulation while preserving a musical tone.','If a close-miked violin sounds too scratchy, an engineer moves the mic slightly toward the body or off the bridge axis to cut bow noise while keeping presence.','String Miking',ARRAY['Bow-contact-point miking','Bow-side miking','Bridge-axis miking','Bridge-above miking','Proximity effect','Off-axis placement']::text[],ARRAY['Confusing natural bow noise with a fault and trying to remove all of it, leaving a lifeless tone.','Miking straight at the bridge or contact point, capturing excess scratch, then blaming the instrument.','Fixing bow noise only with EQ afterward instead of correcting placement first.']::text[],ARRAY['Taming rosin scratch on an intimate solo cello recording.','Balancing bite against smoothness on a close-miked fiddle in a bluegrass mix.','Setting a clip-on violin mic on stage so bow noise does not dominate.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6c3102bc-2b96-5aaa-8ca8-fff9ba74da1f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bow-noise balance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6c3102bc-2b96-5aaa-8ca8-fff9ba74da1f','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6c3102bc-2b96-5aaa-8ca8-fff9ba74da1f' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '08da36a5-18a0-50ae-a5fd-d74cc2fc5583','Bow-side miking','Placement of a microphone on the bow side of a bowed string instrument — the side across which the bow travels — rather than the opposite fingerboard/neck side, capturing more bow attack, articulation, and contact detail. It contrasts with body- or neck-side placements that emphasize warmth and resonance.','A violin has a bow side and a quieter far side. Bow-side miking puts the mic where the bow moves. This catches more attack and playing detail. The other side sounds warmer and smoother.','It gives a more articulate, present string sound by favoring the area of strongest bow-string interaction. Engineers pick it when they want bite and detail rather than a rounder body tone.','For a lead fiddle that must cut through a mix, an engineer mics the bow side to capture attack, accepting a little extra bow noise.','String Miking',ARRAY['Bow-contact-point miking','Bow-noise balance','Bridge-axis miking','Bridge-above miking','Off-axis placement','Proximity effect']::text[],ARRAY['Placing the mic in the bow''s path so it gets struck or catches wind from bow strokes.','Expecting a warm, rounded tone from bow-side placement, which naturally emphasizes attack.','Ignoring the extra bow noise this side captures and not adjusting distance to suit.']::text[],ARRAY['Miking a solo violin that must sound articulate and forward.','Recording a string quartet where each instrument needs presence and separation.','Live-miking a fiddle for a bright, cutting sound in a band.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='08da36a5-18a0-50ae-a5fd-d74cc2fc5583' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bow-side miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '08da36a5-18a0-50ae-a5fd-d74cc2fc5583','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='08da36a5-18a0-50ae-a5fd-d74cc2fc5583' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '555d9ae9-b815-51d1-bd0e-a894e0bc7591','Breath editing','The post-production practice of reducing, attenuating, or removing breath sounds between phrases in vocal or wind-instrument recordings using cuts, fades, clip-gain automation, or dedicated de-breath processing. The aim is to control distracting or excessively loud breaths while retaining enough natural breathing to keep the performance believable.','Singers and wind players breathe between phrases, and mics pick that up. Breath editing turns those breaths down or removes the loudest ones. Engineers keep some breaths so the take still sounds human.','It cleans up distracting inhale noises and stops them from triggering compressors or masking the start of phrases, while preserving natural phrasing. It exists because close mics exaggerate breaths.','In a lead-vocal comp, an engineer uses clip-gain dips or short fades to lower loud breaths, or a de-breath plug-in, rather than deleting them and leaving unnatural gaps.','Editing',ARRAY['Clip gain','Comping','Fades','De-essing','Gain automation','Noise reduction']::text[],ARRAY['Removing every breath, which makes phrasing sound robotic and unnatural.','Hard-cutting a breath and leaving an abrupt silence or a click instead of a short fade.','Editing breaths so aggressively that the following note attacks get clipped.']::text[],ARRAY['Cleaning up a close-miked lead vocal before mixing.','Reducing loud inhales on a solo flute or saxophone track.','Preparing a voiceover or audiobook where breaths distract from the words.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='555d9ae9-b815-51d1-bd0e-a894e0bc7591' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Breath editing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '555d9ae9-b815-51d1-bd0e-a894e0bc7591','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='555d9ae9-b815-51d1-bd0e-a894e0bc7591' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bc6209f3-0f7f-5cf3-b909-cd5b11e69bc7','Bridge-above miking','Placement of a microphone above the bridge of a bowed or plucked string instrument, looking down toward the bridge and top plate, to capture a balanced blend of string articulation and body radiation from a position that stays clear of the bowing arm. The elevated angle favors the bridge/top region where string energy transfers into the soundboard.','This puts the mic above the bridge, pointing down at it. The bridge is where the strings'' energy passes into the body. From up here the mic catches string detail and body tone, and stays out of the bow''s way.','It captures the lively bridge and top-plate area while keeping the mic clear of the player, giving a balanced, articulate tone. The height also helps avoid the bowing arm and reduces direct scratch.','On a cello or violin, an engineer clamps or stands a mic above the bridge angled down, balancing string bite and body warmth without fouling the bow.','String Miking',ARRAY['Bridge-axis miking','Bow-side miking','Bow-contact-point miking','Bow-noise balance','Off-axis placement','Proximity effect']::text[],ARRAY['Placing the mic so high it loses body warmth and sounds thin and distant.','Leaving the mic in the path of the bowing arm so it is bumped mid-take.','Aiming straight down onto the strings and capturing excessive bow scratch.']::text[],ARRAY['Close-miking a cello in an orchestra where space and bleed are tight.','Recording a violin solo that needs a balance of bite and body.','Miking a double bass from above the bridge for articulate low end.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bc6209f3-0f7f-5cf3-b909-cd5b11e69bc7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bridge-above miking'),'[^a-z0-9]','','g'));
