SELECT 'bc6209f3-0f7f-5cf3-b909-cd5b11e69bc7','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bc6209f3-0f7f-5cf3-b909-cd5b11e69bc7' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8774c434-3bad-5bf4-83c9-895bba21d407','Bridge-axis miking','Aiming a microphone along the axis of the instrument''s bridge — the line running perpendicular to the top plate through the bridge — on a bowed or plucked string instrument, targeting the point where string vibration couples into the soundboard for a direct, articulate pickup of the instrument''s primary radiation. It emphasizes the bridge/top interaction over off-axis body resonances.','The bridge sits on the instrument''s top and passes string vibrations into the wood. Bridge-axis miking lines the mic up straight with the bridge. This gives a direct, detailed pickup of where the sound really starts.','It provides a focused, articulate capture centered on the bridge, the instrument''s main sound-transfer point, giving strong string detail. Engineers use it when they want presence and clarity.','An engineer sets a small-diaphragm mic on the bridge axis of a violin at a chosen distance for a detailed, present tone, then adjusts the angle to tame scratch.','String Miking',ARRAY['Bridge-above miking','Bow-contact-point miking','Bow-side miking','Bow-noise balance','Off-axis placement','Proximity effect']::text[],ARRAY['Placing the mic so close on the bridge axis that proximity effect and scratch dominate.','Assuming on-axis is always best, when off-axis can sound smoother on a bright instrument.','Ignoring how bridge-axis aim exaggerates bow noise on aggressive passages.']::text[],ARRAY['Capturing an articulate solo violin line.','Close-miking a cello for separation in a chamber session.','Recording a plucked upright bass where bridge detail matters.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8774c434-3bad-5bf4-83c9-895bba21d407' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bridge-axis miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8774c434-3bad-5bf4-83c9-895bba21d407','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8774c434-3bad-5bf4-83c9-895bba21d407' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7c110ec7-f88c-5442-8757-bae8258f1e1d','Cabinet reamping','A reamping workflow in which a previously recorded dry direct (DI) instrument signal — usually electric guitar or bass — is played back from the interface, converted by a reamp box from balanced line level and low impedance back to unbalanced instrument level and high impedance, fed into a guitar or bass amplifier, and the driven speaker cabinet is miked and re-recorded. This separates the recorded performance from the amp/cabinet tone, so that tone can be chosen or changed after tracking.','When you record electric guitar, you can also capture a clean direct signal. Cabinet reamping plays that clean signal back through a real amp and speaker later. A mic records the speaker. So you can pick the amp sound after the take, without replaying it.','It splits the performance from the amp tone, so engineers can audition amps, cabinets, and mic placements without asking the player to re-perform. A reamp box exists to restore the high impedance and instrument level an amp input expects.','After tracking a clean DI, an engineer sends it from the interface through a reamp box into a chosen amp, mics the cabinet, and prints several tones to compare.','Guitar/Amp Recording',ARRAY['Direct injection (DI)','Reamp box','Impedance matching','Cabinet miking','Speaker miking','3:1 rule']::text[],ARRAY['Feeding a line-level output straight into an amp input without a reamp box, causing an impedance mismatch, tone loss, and noise.','UNSAFE: Opening a tube amplifier chassis or hot-patching connections with the amp powered; tube amps store lethal high voltages, so power down, unplug, and follow the maker''s safety procedure before touching internals.','Recording the DI too hot so the reamped signal overloads the amp''s input unnaturally.']::text[],ARRAY['Changing a scratch guitar tone to a heavier amp sound in the mix.','Auditioning several amps and cabinets from one recorded bass DI.','Re-miking a guitar cabinet to fix a dull tone without recalling the player.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7c110ec7-f88c-5442-8757-bae8258f1e1d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cabinet reamping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7c110ec7-f88c-5442-8757-bae8258f1e1d','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
