INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6fb20413-23ee-5c22-bdd2-3e6cbb80d7e8','Cajón sound-hole miking','Placement of a microphone at or just outside the cajón''s rear sound hole (port), the opening on the back of the box that radiates the instrument''s low-frequency bass tone produced by striking the center of the front playing surface. It captures the deep body resonance and is commonly combined with a second mic on the front tapa for slap detail.','A cajón is a wooden box drum you sit on and slap. The hole in the back lets out the deep bass thump. Sound-hole miking puts a mic at that hole to catch the low end. Players often add a second mic on the front for the sharp slap.','It captures the cajón''s bass and body resonance that the rear port projects, giving weight and low-end power. It exists because the front face and rear port emphasize different parts of the sound.','An engineer places a dynamic or large-diaphragm mic a short distance from the rear sound hole for low end, blending it with a front mic for the slap.','Percussion Miking',ARRAY['Cajón tapa miking','Kick-drum miking','Boundary microphone','Proximity effect','Off-axis placement','Low-frequency resonance']::text[],ARRAY['Pushing the mic deep inside the port and capturing a boomy, one-note thump with no definition.','Relying on the rear mic alone and losing the slap and snare-wire detail from the front.','Ignoring proximity effect, which exaggerates the low end right at the port.']::text[],ARRAY['Miking a cajón for an acoustic singer-songwriter set to get solid low end.','Blending front and rear mics on a flamenco or pop cajón in the studio.','Reinforcing a cajón''s bass in a live acoustic act.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6fb20413-23ee-5c22-bdd2-3e6cbb80d7e8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cajón sound-hole miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6fb20413-23ee-5c22-bdd2-3e6cbb80d7e8','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6fb20413-23ee-5c22-bdd2-3e6cbb80d7e8' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0c7244ed-b214-5080-a93a-48501a93fa63','Cajón tapa miking','Placement of a microphone in front of the cajón''s tapa — the thin front playing plate — to capture the slap, snap, and internal snare-wire buzz produced when the player strikes the top edge and center of the face. It emphasizes attack and high-frequency detail and is commonly paired with a rear sound-hole mic for bass.','The tapa is the thin front board of a cajón that the player hits. Tapa miking points a mic at that board to catch the sharp slap and snare buzz. A second mic at the back hole adds the deep bass.','It captures the crisp attack and snare-wire rattle from the playing surface, giving the cajón its snap and definition. It exists to separate the high-detail front sound from the bass-heavy rear port.','An engineer aims a cardioid mic a short distance from the top of the tapa for slap and snare, blending it with a rear-port mic for low end.','Percussion Miking',ARRAY['Cajón sound-hole miking','Snare-drum miking','Proximity effect','Off-axis placement','Transient response','Low-frequency resonance']::text[],ARRAY['Aiming at the dead center of the tapa only, missing the snare-wire snap that lives near the top edge.','Placing the mic so close it gets struck by the player''s hands.','Relying on the front mic alone and ending up with a thin, bass-light cajón.']::text[],ARRAY['Capturing crisp slaps on a flamenco cajón in the studio.','Miking the front plate for attack in an acoustic pop session.','Reinforcing cajón snap through a PA at an unplugged gig.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0c7244ed-b214-5080-a93a-48501a93fa63' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cajón tapa miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0c7244ed-b214-5080-a93a-48501a93fa63','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0c7244ed-b214-5080-a93a-48501a93fa63' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6abbd489-b7ce-5d0c-a138-c23f5d0afc77','Cap-edge miking','A cymbal close-miking placement aimed at the cap (bell/cup) and its adjoining edge — where the raised center meets the bow — rather than the outer rim, capturing a brighter, more focused ping, stick definition, and bell articulation with less low-frequency wash and less of the air turbulence found at the outer edge.','A cymbal has a raised center called the cap or bell. Cap-edge miking points the mic near that center instead of the outer rim. This gives a brighter, more defined ''ping.'' The outer rim gives more low wash and air noise.','It emphasizes attack and bell ping for a defined cymbal sound and avoids the wind blast and boom that come from aiming at the outer edge. It exists to shape cymbal tone through placement.','To get a defined ride sound, an engineer aims the mic toward the cap and its edge rather than the rim, capturing the stick ping while reducing low-frequency wash.','Percussion Miking',ARRAY['Hi-hat miking','Overhead miking','Off-axis placement','Cymbal wash','Transient response','Proximity effect']::text[],ARRAY['Aiming straight at the outer cymbal edge, which captures excess low wash and an air-blast pop.','UNSAFE: Working with an ear right next to loud cymbals at close range; cymbal peaks are very high and can damage hearing, so keep monitoring levels safe and use hearing protection.','Placing the mic where a swinging cymbal can strike it during hard playing.']::text[],ARRAY['Getting a defined ride ping in a jazz drum recording.','Close-miking a specific crash for accent hits.','Reducing wash and boom on a bright cymbal in a dense mix.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6abbd489-b7ce-5d0c-a138-c23f5d0afc77' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cap-edge miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6abbd489-b7ce-5d0c-a138-c23f5d0afc77','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6abbd489-b7ce-5d0c-a138-c23f5d0afc77' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7a5f9877-4570-5daf-8658-891c9fb945fd','Cello floor-boundary microphone','The use of a boundary (pressure-zone) microphone placed flush on the floor near a cello, so the instrument''s directly radiated and floor-reflected sound arrive in phase at the surface-mounted capsule. Because the capsule sits within the boundary layer, it avoids the comb filtering a delayed floor reflection would cause and gains roughly 6 dB of pressure buildup, capturing a full, low-coloration cello tone.','A boundary mic is a flat mic that sits on a surface like the floor. Placed near a cello, it uses the floor instead of fighting its echo. This avoids the hollow, filtered sound a floor bounce usually adds. The result is a full, even cello tone.','It removes the comb-filter coloration a floor bounce would add to a raised mic and uses the boundary''s pressure gain for a strong, natural low end. It exists to turn a reflecting surface into an advantage.','For a seated cellist, an engineer lays a boundary mic on the floor a short distance ahead of the endpin to capture a warm, even tone with minimal comb filtering.','String Miking',ARRAY['Boundary microphone','Comb filtering','Pressure-zone microphone','Bridge-axis miking','3:1 rule','Proximity effect']::text[],ARRAY['Raising the mic slightly off the floor, reintroducing the delayed reflection and comb filtering it was meant to avoid.','Placing it on a resonant or rattly floor that adds footfall and structural noise.','Expecting isolation from an omnidirectional boundary mic in a room with other instruments.']::text[],ARRAY['Miking a solo cello recital from the stage floor.','Capturing a cello in a chamber group where mic stands are intrusive.','Reinforcing a seated cellist with minimal visible hardware.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7a5f9877-4570-5daf-8658-891c9fb945fd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cello floor-boundary microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7a5f9877-4570-5daf-8658-891c9fb945fd','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7a5f9877-4570-5daf-8658-891c9fb945fd' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c5013531-172d-55df-a8ae-bd9f59d0d93c','Clarinet bell-overemphasis','A tonal fault in clarinet miking in which placing or aiming the microphone too close to the bell overrepresents the bell''s output and yields an uneven, unnatural timbre. On a clarinet only the lowest notes (all tone holes closed) and the highest harmonics radiate strongly from the bell, while most notes speak from the open tone holes, so bell-biased placement produces a bottom-heavy, honky, or register-dependent sound.','On a clarinet, most notes come out of the open finger holes, not the bell. Only the lowest notes really use the bell. If you aim the mic at the bell, those notes jump out and the tone sounds uneven. This mistake is called bell-overemphasis.','Naming this fault helps engineers spot and avoid it by aiming toward the tone holes for an even tone. Understanding it explains why a clarinet is not miked like a trumpet.','When a close-miked clarinet sounds honky and uneven, an engineer moves the mic up toward the tone holes and off the bell axis to even out the registers.','Woodwind Miking',ARRAY['Bell–tone-hole balance','Bell-shadow placement','Off-axis placement','Proximity effect','Instrument directivity','Polar pattern']::text[],ARRAY['Miking a clarinet like a trumpet, straight into the bell, and getting an uneven, register-dependent tone.','Assuming louder low notes at the bell mean better placement, when they actually signal overemphasis.','Trying to fix the imbalance with EQ instead of correcting the mic placement.']::text[],ARRAY['Diagnosing why a close-miked clarinet sounds honky in a jazz session.','Setting a clip-on clarinet mic that must sound even across all registers.','Teaching a student why bell placement fails on a clarinet.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c5013531-172d-55df-a8ae-bd9f59d0d93c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Clarinet bell-overemphasis'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c5013531-172d-55df-a8ae-bd9f59d0d93c','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c5013531-172d-55df-a8ae-bd9f59d0d93c' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9eb4932e-b4c2-55b6-81ed-ae56e7735d56','Clarinet register-hole balance','A close-miking balance in which the microphone is positioned to capture the clarinet''s tone-hole radiation and its bell output in even proportion, keeping timbre consistent as different holes open across the chalumeau and clarion registers. Because the clarinet radiates sound from whichever finger and register holes are open for a note as well as from the bell, a mic aimed only at the bell exaggerates the lowest notes; aiming toward the fingering holes about a third of the way up from the bell at roughly 15-20 cm yields a balanced blend.','A clarinet makes sound come out of its open finger holes, not just the bell. Point the mic at the holes, not straight down the bell. This keeps low and high notes at an even volume.','It exists to give an even, natural tone across the clarinet''s range, preventing a boomy low register or a thin, bell-heavy sound when the instrument is close-miked.','A recordist places the mic near the finger holes about a third up from the bell, listens for even note-to-note level as the player crosses registers, and fine-tunes the angle to blend hole and bell sound.','Woodwind Miking',ARRAY['Proximity effect','Polar pattern','Spot microphone','Off-axis coloration','Clip-on instrument microphone']::text[],ARRAY['Aiming the microphone straight into the bell, which over-emphasises the lowest notes and gives an unnatural, uneven scale.','Placing the mic so close that key and finger noise (mechanical clatter) dominates the tone.','Treating the clarinet as a single point source and using one distant bell mic in a loud ensemble, which invites bleed and thin tone.']::text[],ARRAY['Close-miking a clarinet in a jazz combo where stage volume rules out a distant room mic.','Clip-on miking an orchestral clarinet section for a live broadcast.','Recording a solo clarinet in a studio and balancing tone-hole and bell radiation for a natural timbre.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9eb4932e-b4c2-55b6-81ed-ae56e7735d56' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Clarinet register-hole balance'),'[^a-z0-9]','','g'));
