INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4fe28986-4680-54b0-975c-f0906960bd09','Conga head-zone miking','A percussion close-miking approach that positions the microphone relative to specific zones of the conga head - the centre for deep bass tones and near the rim for open tones and slaps - so the mic captures the intended balance of the drum''s tonal palette. Congas produce distinct sounds (bass, open tone, slap, muff) depending on where and how the head is struck, so head-zone placement targets the register the recordist wants while a directional pattern keeps neighbouring drums out.','A conga makes different sounds in different spots on its skin. The middle gives a deep boom, and the edge gives ringing open tones and sharp slaps. Aim the mic at the zone whose sound you want.','It lets one close mic emphasise the desired tone - punchy slap, singing open tone, or deep bass - while keeping bleed from the other drums low.','A live engineer angles a cardioid mic just over the rim of each conga, a few centimetres above and tilted slightly toward the centre, to catch open tones and slaps while rejecting the neighbouring drum.','Percussion Miking',ARRAY['Close miking','Cardioid','3:1 rule','Bleed','Polar pattern','Proximity effect']::text[],ARRAY['Placing the mic dead-centre over the head, which captures muffled bass but loses the slap and open-tone detail players rely on.','Setting adjacent congas'' mics too close together, so each captures its neighbour and invites phase problems.','UNSAFE: Standing close to loud hand percussion for long periods without hearing protection; sustained high sound-pressure levels can damage hearing.']::text[],ARRAY['Miking a percussionist''s conga set for a live salsa band.','Studio-tracking congas where the producer wants a bright, slap-forward sound.','Reinforcing a hand-drum solo so open tones cut through a dense mix.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4fe28986-4680-54b0-975c-f0906960bd09' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Conga head-zone miking'),'[^a-z0-9]','','g'));
