INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0f1b4c45-dda4-557a-985e-b043647a5f6a','Consonant matching','In double-tracking, the practice of performing or editing two takes so their consonants and other transient articulations line up in time, making the layered parts fuse into one tight, wider-sounding voice or instrument. Mismatched consonant timing between takes produces audible flamming or smearing, so aligning the sharp attacks is what sells a convincing double.','You record a part twice and stack the takes. The sharp sounds, like the letters t, k, and s, must line up. They must hit at the same moment. If they do not, the double sounds sloppy. Matching those sounds makes two takes feel like one.','It exists to make double-tracked or layered parts tight and wide instead of smeared, so the two performances reinforce rather than fight each other.','A vocalist watches the waveform or listens back while re-singing a double, and the engineer nudges or comps the take so the t and s sounds land with the lead.','Double-Tracking',ARRAY['Double-tracking','Double-tracked acoustic spread','Comping','Transient','Timing alignment','Stereo width']::text[],ARRAY['Focusing only on pitch while ignoring consonant timing, so the double still sounds loose.','Quantising or time-stretching so aggressively that the double loses natural feel and sounds robotic.','Assuming a copied and detuned single take is a true double; a copy cannot create the timing variation that widens a real double.']::text[],ARRAY['Tightening a double-tracked lead vocal in a pop production.','Aligning two rhythm-guitar takes panned hard left and right.','Editing backing-vocal stacks so their word endings land together.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0f1b4c45-dda4-557a-985e-b043647a5f6a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Consonant matching'),'[^a-z0-9]','','g'));
