SELECT '0f1b4c45-dda4-557a-985e-b043647a5f6a','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0f1b4c45-dda4-557a-985e-b043647a5f6a' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f2ebc6c3-0dbe-570d-99d7-382e7828f88d','Cymbal rejection miking','A close-miking approach that positions and orients a directional microphone on a drum (snare, tom, or hi-hat) so its least-sensitive angle - the polar pattern''s null or rear rejection - points at nearby cymbals, minimising cymbal bleed into the drum''s channel. It combines cardioid or supercardioid rejection with close distance and the 3:1 rule to keep cymbal wash out of the drum mic.','Cymbals are loud and leak into the drum mics, which makes mixing harder. You aim the deaf side of a directional mic toward the cymbals. That way the mic hears the drum but rejects most of the cymbal.','It gives cleaner drum channels so an engineer can process each drum without amplifying cymbal wash, reducing phase and comb-filtering problems.','An engineer tilts a supercardioid snare mic so its null faces the hi-hat, keeps the mic close to the head, and follows the 3:1 rule so cymbal spill sits well below the drum.','Drum Miking',ARRAY['Cardioid','Supercardioid','Polar pattern','3:1 rule','Bleed','Off-axis rejection']::text[],ARRAY['Aiming the null wrongly - a supercardioid rejects best off its rear axis, not directly behind - so cymbals still bleed in.','Backing the mic off the drum to reduce cymbal spill, which lowers the drum level and actually worsens the drum-to-cymbal ratio.','Relying on a noise gate to hide heavy cymbal bleed instead of solving it with placement first.']::text[],ARRAY['Close-miking a snare in a loud rock kit to keep hi-hat spill down.','Isolating tom mics on a live stage so cymbals do not trigger tom gates.','Recording drums in a small room where cymbals otherwise dominate every close mic.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f2ebc6c3-0dbe-570d-99d7-382e7828f88d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cymbal rejection miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f2ebc6c3-0dbe-570d-99d7-382e7828f88d','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f2ebc6c3-0dbe-570d-99d7-382e7828f88d' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2bd0fbd5-0901-50ee-ba78-6b873028c439','Cymbal-plane miking','A cymbal-miking placement in which the microphone is set roughly in the plane of the cymbal - looking across its edge rather than down onto its face - so it sits off the axis of the cymbal''s strongest, most sibilant radiation and away from the burst of air the cymbal pushes as it swings. This tames harsh wash and wind noise while still capturing stick attack and edge tone.','A cymbal throws its harshest, brightest sound and a puff of air straight off its face. Put the mic level with the cymbal''s edge instead of over its top. Facing the edge softens the harsh wash and stops wind thumps.','It exists to capture a cymbal''s attack and shimmer without the piercing top end or the low-frequency wind noise that on-axis, face-on placement produces.','When overheads sound harsh, an engineer lowers the mic to the cymbal''s edge height and points it across the rim, cutting splash and air blasts while keeping the ping of the stick.','Cymbal Miking',ARRAY['Overhead microphone','Off-axis rejection','Cymbal-under miking','Cymbal rejection miking','Wind noise','Polar pattern']::text[],ARRAY['Pointing the mic straight down onto the cymbal''s face, capturing the harshest highs and the air blast.','Placing the mic so far off-axis that stick attack and definition disappear, leaving only wash.','Ignoring the wind gust a swinging cymbal makes, then blaming the resulting thumps on the microphone.']::text[],ARRAY['Taming harsh ride-cymbal top end in a bright-sounding room.','Miking a crash edge-on to avoid wind noise from the cymbal''s swing.','Recording jazz cymbals where shimmer matters more than aggressive splash.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2bd0fbd5-0901-50ee-ba78-6b873028c439' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cymbal-plane miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2bd0fbd5-0901-50ee-ba78-6b873028c439','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2bd0fbd5-0901-50ee-ba78-6b873028c439' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '154c2cf8-c09d-5ce3-a507-716edddd6a8a','Cymbal-under miking','A technique that places a microphone beneath a cymbal, pointing upward at its underside, to capture that cymbal''s tone in relative isolation from the rest of the kit. It trades away stick attack and some of the top cymbal''s warmth - the underside attenuates the leading transient and high-frequency warmth - so it is used for isolation or a darker cymbal sound rather than a bright, attack-forward result.','This puts the mic below a cymbal, aimed up at its bottom. It hears that one cymbal more and the other drums less. The trade-off is a softer, less clicky attack and a darker tone.','It exists to isolate a single cymbal or get a darker, wash-heavy sound when a top-side mic would pick up too much of the whole kit.','On a crowded stage an engineer clips a mic under the ride, pointing up, to feed a cleaner ride channel, accepting the softer attack that under-placement gives.','Cymbal Miking',ARRAY['Cymbal-plane miking','Overhead microphone','Polarity','Phase','Bleed','Cymbal rejection miking']::text[],ARRAY['Expecting crisp stick attack from an under-cymbal mic; the underside attenuates the leading transient and top-end warmth.','Forgetting to check polarity against the overheads, since an underside mic can be out of phase with the top mics.','UNSAFE: Working with your head close under loud cymbals during setup without hearing protection; close-range cymbal peaks reach very high sound-pressure levels.']::text[],ARRAY['Isolating a ride cymbal on a loud live stage.','Adding a darker, under-side cymbal texture to a studio drum sound.','Feeding a dedicated cymbal channel where top overheads pick up too much snare and toms.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='154c2cf8-c09d-5ce3-a507-716edddd6a8a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cymbal-under miking'),'[^a-z0-9]','','g'));
