INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f7a39d5e-c290-513a-9ca9-c7dd958f9637','DI–amplifier split','A signal-routing setup in which a direct injection (DI) box splits an instrument''s output so one path feeds the player''s amplifier while a separate, isolated path feeds the mixing console. The DI provides a balanced, low-impedance feed to the desk and usually a ground-lift switch to break ground loops between the amp and the PA, letting a miked amp and a clean DI be captured together.','A DI (direct injection) box lets one instrument feed two places at once. One output goes to the player''s amp, and the other goes to the mixing desk. A ground-lift switch stops the hum caused when the two systems fight over ground.','It exists so the amp and the console can each receive the instrument signal without loading it down or creating a hum-inducing ground loop, and so a mixer can blend a clean DI with a miked amp.','A stage tech runs a bass into a DI, sends the thru or link output to the bass amp and the balanced XLR to the snake, and flips the ground lift if hum appears.','Signal Routing',ARRAY['Direct injection box','Ground loop','Ground lift','Balanced signal','Impedance','Reamping']::text[],ARRAY['UNSAFE: Lifting a device''s mains safety earth (chassis ground) to cure hum instead of using the DI''s signal ground-lift; defeating the protective earth creates a shock hazard.','UNSAFE: Hot-patching the DI''s XLR while phantom power is live, or sending phantom to a passive DI, which causes loud thumps and can damage gear and startle nearby ears.','Assuming any Y-cable or simple pad gives isolation; only a transformer or active split truly balances the signal and breaks ground loops.']::text[],ARRAY['Recording a bass guitar''s clean DI and a miked amp at the same time.','Feeding a keyboard to both stage backline and front-of-house through an isolated split.','Curing hum between a guitar amp and the PA on a live stage.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f7a39d5e-c290-513a-9ca9-c7dd958f9637' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('DI–amplifier split'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f7a39d5e-c290-513a-9ca9-c7dd958f9637','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
