INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '096750ca-b74a-57d5-b5e1-878b1ced21a6','Desk-pair spot microphone','In orchestral recording, a spot (accent) microphone assigned to a single desk - the shared music stand of two string players - positioned close to reinforce that pair''s contribution within the main pickup. Like other spot mics it supplements a main stereo array, is usually delay-compensated to align with the mains, and is mixed low to add presence without collapsing the natural stage perspective.','In an orchestra, two string players share one music stand, called a desk. A desk-pair spot mic is a close mic set at one desk. It gently lifts those players inside the wider orchestra sound.','It exists to add local clarity or presence to a specific pair of players or an inner line, while the main array still provides the overall balance and stereo image.','A classical engineer places a small mic just above a front violin desk, then delays it to match the main pair so it reinforces that line without smearing the image.','Orchestral Miking',ARRAY['Spot microphone','Main microphone array','Delay compensation','Decca tree','Accent microphone','Precedence effect']::text[],ARRAY['Bringing the spot up too loud, which pulls the desk unnaturally forward and breaks the orchestra''s depth and image.','Failing to time-align the spot to the main array, causing comb-filtering and a smeared image.','Placing the mic so close it favours one player of the pair and unbalances the desk.']::text[],ARRAY['Reinforcing a violin section''s front desk in a concerto recording.','Adding presence to a quiet inner-string line under a Decca tree.','Spot-miking a wind or string desk for a live orchestral broadcast.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='096750ca-b74a-57d5-b5e1-878b1ced21a6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Desk-pair spot microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '096750ca-b74a-57d5-b5e1-878b1ced21a6','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='096750ca-b74a-57d5-b5e1-878b1ced21a6' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '87bdfcd2-b068-53a9-a205-a3172b4f7c9d','Double-bass bridge–f-hole balance','A double-bass close-miking balance achieved by positioning the microphone between the bridge and an f-hole so the captured sound blends the string and bow bite that radiates near the bridge with the low-frequency body resonance that emerges from the f-hole. Moving toward the bridge favours attack and definition; moving toward the f-hole adds volume, warmth and body.','A double bass makes a sharp attack near the bridge. It also makes a deep boom from its f-hole, the shaped opening in the top. Placing the mic between them balances punch and body. Move toward the bridge for bite and toward the f-hole for more low end.','It exists to get an even, usable bass tone from close range - enough attack to cut through a mix without the boom and honk that pointing straight at the f-hole causes.','A recordist places a mic between the bridge and the nearer f-hole, then slides it toward the bridge for more definition or toward the hole for more warmth until the tone sits right.','String Miking',ARRAY['Proximity effect','Double-bass endpin microphone','F-hole','Bridge','Clip-on instrument microphone','Omnidirectional']::text[],ARRAY['Pointing the mic straight into the f-hole, producing a boomy, one-note low end and lost definition.','Using a directional mic very close and blaming muddiness on the bass, when it is proximity-effect bass build-up.','Clipping the mic where the bow or hand strikes it, causing handling noise and thumps.']::text[],ARRAY['Amplifying an upright bass in a jazz trio with minimal feedback.','Recording double bass in a studio and dialling attack versus body by mic position.','Miking an orchestral bass section for reinforcement.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='87bdfcd2-b068-53a9-a205-a3172b4f7c9d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Double-bass bridge–f-hole balance'),'[^a-z0-9]','','g'));
