SELECT '87bdfcd2-b068-53a9-a205-a3172b4f7c9d','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='87bdfcd2-b068-53a9-a205-a3172b4f7c9d' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '306aadb4-1141-5bb9-bb52-b9fc26da2d75','Double-bass endpin microphone','A double-bass miking approach in which a small microphone is mounted at or near the instrument''s endpin - the adjustable spike at the base - to capture body resonance and low-frequency output from below while keeping the mic out of the player''s bowing and fingering path. The position favours warmth and body and offers good gain-before-feedback on stage, at the cost of the string attack captured nearer the bridge.','The endpin is the metal spike at the bottom of a double bass. Mounting a small mic there keeps it out of the player''s way. It picks up deep, warm body sound, but less of the string attack.','It exists to give a discreet, feedback-resistant mounting that captures the bass''s body warmth, useful live where a bridge or f-hole mic would be knocked or would feed back.','A live engineer fixes a miniature cardioid near the endpin so the bassist can move freely, then adds a little presence EQ to make up for the reduced attack.','String Miking',ARRAY['Double-bass bridge–f-hole balance','Endpin','Proximity effect','Feedback','Clip-on instrument microphone','Body resonance']::text[],ARRAY['Expecting crisp string attack from an endpin mic; the position favours body warmth and loses bite.','Letting the endpin mic pick up floor rumble and footfalls transmitted through the spike and stage.','Mounting the mic so it rattles against the instrument or spike, adding mechanical noise.']::text[],ARRAY['Miking an upright bass on a loud stage where feedback is a risk.','Giving a bassist freedom to move while keeping a consistent low-end tone.','Blending an endpin mic with a pickup for a fuller amplified bass sound.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='306aadb4-1141-5bb9-bb52-b9fc26da2d75' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Double-bass endpin microphone'),'[^a-z0-9]','','g'));
