INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9aa5a3ca-c136-5fc9-ba6e-fd6b68a06639','Double-tracked acoustic spread','A production technique in which an acoustic part, often a rhythm guitar, is performed twice as separate takes and the two takes are panned apart - commonly hard left and right - to create a wide, immersive stereo image. The natural timing and tuning differences between two genuine performances, rather than a copied track, are what produce the width and richness.','You record the same acoustic guitar part twice, as two real takes. Then you pan one take left and the other right. The tiny differences between them make a wide, full stereo sound. Copying one take will not work the same way.','It exists to widen and thicken an acoustic part so it fills the stereo field and leaves the centre open for vocals and other lead elements.','An engineer records two passes of a strummed acoustic, pans them left and right, and matches their consonant and transient timing so the strums lock together instead of flamming.','Double-Tracking',ARRAY['Double-tracking','Consonant matching','Stereo width','Panning','Comb filtering','Haas effect']::text[],ARRAY['Copying one take to both sides instead of playing two; a duplicate pans as mono in the centre and adds no width.','Letting the two takes drift badly out of time, so strums flam instead of tightening.','Summing the wide pair to mono without checking; loosely matched takes can partly cancel and thin out.']::text[],ARRAY['Widening a strummed acoustic in a pop or singer-songwriter mix.','Building a big acoustic bed under a chorus while keeping the centre clear.','Doubling a fingerpicked part for a lush stereo intro.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9aa5a3ca-c136-5fc9-ba6e-fd6b68a06639' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Double-tracked acoustic spread'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9aa5a3ca-c136-5fc9-ba6e-fd6b68a06639','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9aa5a3ca-c136-5fc9-ba6e-fd6b68a06639' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '15166417-db46-5f3d-b0cb-4c56bc981586','Drum crush channel','A parallel processing channel carrying a heavily (crushed) compressed copy of the drum mix, blended underneath the dry drums to add weight, sustain and aggression without sacrificing the transients of the main signal. Also called a parallel or New York compression channel, it uses a high ratio and hard gain reduction and is mixed in to taste.','This is a second drum channel squashed hard with a compressor. You blend it under the normal, punchy drums. It adds body and power while the main drums keep their snap. Engineers call it parallel or New York compression.','It exists to raise the low-level detail and sustain of a kit and add density, while the parallel blend preserves the natural attack that heavy compression alone would flatten.','An engineer sends the drum bus to an aux, crushes it with a fast, high-ratio compressor, and rides the aux fader up until the kit gains punch and body without losing its snap.','Parallel Processing',ARRAY['Parallel compression','Drum crush microphone','Aux send','Compression ratio','Make-up gain','Drum bus']::text[],ARRAY['Blending the crush channel so loud it swamps the dry drums, killing the very transients parallel compression is meant to keep.','Leaving latency between the parallel and dry paths, which causes phase cancellation; the two must stay time-aligned.','UNSAFE: Auditioning crushed drums at high monitoring levels for long periods, risking hearing fatigue and damage; monitor at safe levels.']::text[],ARRAY['Adding punch to a thin drum recording in a rock mix.','Gluing a drum kit together with a blended crushed aux on the mix bus.','Creating an aggressive, in-your-face drum sound for pop or hip-hop.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='15166417-db46-5f3d-b0cb-4c56bc981586' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Drum crush channel'),'[^a-z0-9]','','g'));
