SELECT '15166417-db46-5f3d-b0cb-4c56bc981586','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='15166417-db46-5f3d-b0cb-4c56bc981586' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3f55d279-bebd-5a2a-a505-895f9d04e03a','Drum crush microphone','A microphone, usually a mono or room mic on the kit, recorded and processed to be heavily compressed and often driven into saturation to provide a crushed, aggressive drum texture blended under the close mics. The crush mic contributes attitude, room ambience and sustain rather than clean detail, and is mixed in behind the main drum sound.','This is one microphone on the drums pushed hard and squashed until it sounds gritty and huge. It is not meant to be clean. You blend it under the main drum mics to add power and room.','It exists to give a single dramatic, compressed room or kit sound that adds size and energy the clean close mics cannot, without needing many microphones.','An engineer sets a mono mic in front of or above the kit, slams it with a compressor and sometimes distortion, and blends it under the close mics for weight and ambience.','Drum Miking',ARRAY['Room microphone','Drum crush channel','Parallel compression','Mono overhead','Saturation','Compression ratio']::text[],ARRAY['Placing the crush mic without regard to the 3:1 rule and phase, so it comb-filters against the close mics and overheads.','Expecting clean detail from a crush mic; its job is grit and size, not accuracy.','UNSAFE: Exposing ears to sustained high drum levels at close range while auditioning a crush mic, without hearing protection or level discipline.']::text[],ARRAY['Capturing an aggressive room-drum sound for a rock record with few mics.','Adding a compressed mono kit texture under a multi-mic drum setup.','Recreating classic slammed-room drum sounds in a modern session.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3f55d279-bebd-5a2a-a505-895f9d04e03a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Drum crush microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3f55d279-bebd-5a2a-a505-895f9d04e03a','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3f55d279-bebd-5a2a-a505-895f9d04e03a' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b4deb130-3f81-5552-beb4-ad84a6312316','Drum head-baffle technique','A close-miking isolation method in which a small acoustic baffle or gobo is placed near a drum''s head to shield that drum''s microphone from the spill of cymbals and adjacent drums and to control nearby reflections, improving separation between kit channels. It supplements directional-mic and 3:1 techniques where placement alone cannot achieve enough isolation.','A baffle is a small sound-blocking panel. You place one near a drum''s skin to block spill from cymbals and other drums. That gives the drum''s mic a cleaner, more isolated sound.','It exists to add physical isolation between loud, closely spaced kit elements so each close mic captures mainly its own drum, easing mixing and gating.','An engineer stands a small gobo between the hi-hat and a snare mic, or around a tom, to cut spill that mic placement alone cannot reject.','Drum Miking',ARRAY['Bleed','Gobo','3:1 rule','Cymbal rejection miking','Isolation','Cardioid']::text[],ARRAY['Placing a baffle so close it changes the drum''s tone or reflects sound back into the head, colouring the sound.','Relying on baffles alone while ignoring mic pattern and the 3:1 rule, which do most of the isolation work.','Creating a hard reflective surface right next to the mic, which causes comb filtering instead of cleaner isolation.']::text[],ARRAY['Isolating drums from a loud amp in the same tracking room.','Reducing hi-hat spill into a snare mic during a live recording.','Separating kit elements in a small studio with limited space.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b4deb130-3f81-5552-beb4-ad84a6312316' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Drum head-baffle technique'),'[^a-z0-9]','','g'));
