WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9253d937-6497-58ba-b3d6-9dc3d4673097' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2dc07f00-83af-57f6-9707-5993147a6425','F-hole-axis miking','Aligning a microphone with the axis of a violin-family instrument’s f-hole, pointing at or into the sound hole. The f-holes radiate a strong low-frequency air resonance, so this position gives high output and a powerful low end, but pointing directly into the hole can sound boomy or boxy, especially with a directional mic’s proximity effect.','The f-holes are the two carved slots on a violin, viola, cello, or bass. A lot of low sound comes out of them. Aiming a mic straight at an f-hole gives loud, deep tone. But it can turn boomy and boxy up close.','It maximises level and low-end output by facing the instrument’s strongest bass radiator, useful when more volume is needed. Knowing its boomy tendency lets the engineer back off or angle away to balance the tone.','Needing more level from a quiet string instrument, a technician edges the mic toward the f-hole for output, then angles slightly off the hole to tame the boom.','String Miking',ARRAY['Endpin-side cello miking','Fingerboard-end miking','Proximity effect','Helmholtz resonance','Endpin-floor coupling capture','Close miking']::text[],ARRAY['Pointing a close directional mic straight into the f-hole and ending up with a boomy, honky low-mid sound.','Ignoring proximity effect, which piles even more bass onto an already bass-heavy position.','Assuming the f-hole gives a balanced tone; it favours low resonance over string clarity.']::text[],ARRAY['Boosting the level of a soft-playing double bass in a loud ensemble.','Reinforcing a cello where more low-end body is wanted.','Troubleshooting a boomy string sound traced to a mic aimed into the f-hole.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2dc07f00-83af-57f6-9707-5993147a6425' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('F-hole-axis miking'),'[^a-z0-9]','','g'));
