SELECT '2dc07f00-83af-57f6-9707-5993147a6425','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2dc07f00-83af-57f6-9707-5993147a6425' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7a572e87-147c-5eef-a8bb-597a67a5ba13','Fingerboard-end miking','Placing the microphone near the end of the fingerboard, where it overhangs the body, rather than at the bridge. This position gives a warmer, rounder, more blended tone with less bow bite than the brighter, more detailed sound found closer to the bridge.','On a string instrument, the fingerboard is where the player presses the strings. Miking near the end of it, over the body, gives a soft, warm tone. It has less scratch than miking right at the bridge.','It captures a smoother, more rounded blend of the strings and body, useful when the bridge position sounds too harsh or scratchy. It gives the engineer a warmer tonal option.','If a bridge-side mic sounds too edgy, a technician moves the mic toward the fingerboard end for a warmer, more forgiving tone on violin, viola, or cello.','String Miking',ARRAY['Fingerboard-side miking','Endpin-side cello miking','F-hole-axis miking','Bridge','Close miking','Proximity effect']::text[],ARRAY['Moving too far up the neck and losing the string detail and presence the part needs.','Expecting full low-end body here; the fingerboard end favours warmth and blend over deep resonance.','Catching finger and left-hand noise by placing the mic too close to the playing hand.']::text[],ARRAY['Softening a bright violin that sounds harsh when miked at the bridge.','Recording a warm, blended viola tone for a chamber session.','Choosing a forgiving mic position for an amateur string player.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7a572e87-147c-5eef-a8bb-597a67a5ba13' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fingerboard-end miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7a572e87-147c-5eef-a8bb-597a67a5ba13','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7a572e87-147c-5eef-a8bb-597a67a5ba13' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '63b1b0ec-51c7-5454-89bd-18d2377c6b15','Fingerboard-side miking','Miking a string instrument from the fingerboard and neck side of the bridge, rather than the tailpiece or bridge side. This captures more of the strings and left-hand articulation with a generally warmer, less aggressive tone than positions close to the bridge and bow-contact point.','The bridge splits a string instrument into two sides. The fingerboard side is toward the neck. Miking from this side gives a warmer, softer sound than the sharp tone near the bridge.','It offers a warmer, smoother perspective and captures the playing-hand articulation, giving the engineer an alternative to the brighter bridge-side sound. Position choice is a key tone control on strings.','A technician who finds the bridge side too scratchy moves the mic to the fingerboard side of the instrument for a rounder, more musical tone.','String Miking',ARRAY['Fingerboard-end miking','Endpin-side cello miking','F-hole-axis miking','Bridge','Off-axis rejection','Close miking']::text[],ARRAY['Placing the mic so near the hand that finger and shift noise become obvious.','Expecting maximum brightness and attack here; those live nearer the bridge.','Ignoring how far off-axis the bow strokes sit, which changes the captured balance.']::text[],ARRAY['Choosing a warmer perspective on a solo violin.','Balancing tone on a cello that sounds too edgy from the bridge side.','Setting a smoother string sound to sit in a dense mix.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='63b1b0ec-51c7-5454-89bd-18d2377c6b15' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fingerboard-side miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '63b1b0ec-51c7-5454-89bd-18d2377c6b15','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='63b1b0ec-51c7-5454-89bd-18d2377c6b15' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4faee4c2-4507-532c-9fbb-15c10ee492f2','Flute body-axis miking','Positioning the microphone along the axis of the flute’s body, typically behind and slightly above the player’s head pointing at the finger and tone holes, rather than at the embouchure hole. This captures a clear, bright flute tone with high isolation and much less breath noise than a mic in front of the mouthpiece.','A flute is a long tube with holes along it. Aim a mic at the body and its holes. Place it just above and behind the player. That gives a clear, bright sound. It also avoids the breathy noise from blowing across the mouthpiece.','It captures the flute’s tone-hole radiation for a clean, sparkling sound with good separation, while keeping the mic out of the breath stream. This gives clarity and isolation on stage or in the studio.','A technician places the mic behind and above the flautist, aimed at the finger holes, to get a clear, isolated flute sound with little wind noise.','Woodwind Miking',ARRAY['Flute embouchure-hole miking','Flute breath-stream avoidance','Off-axis rejection','Close miking','Proximity effect','Overhead microphone']::text[],ARRAY['Aiming at only one part of the body, so notes that favour other holes drop in level.','Expecting the breathy, intimate character; the body axis trades that for clarity and isolation.','Placing the mic where the swaying flute drifts out of its coverage as the player moves.']::text[],ARRAY['Miking a flute in a loud stage mix where isolation and clarity matter.','Recording a bright, clean flute tone with minimal breath noise.','Capturing a flute in a section where spill from neighbours must stay low.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4faee4c2-4507-532c-9fbb-15c10ee492f2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flute body-axis miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4faee4c2-4507-532c-9fbb-15c10ee492f2','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4faee4c2-4507-532c-9fbb-15c10ee492f2' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e083d057-0bdb-5fbd-ac71-079caa863eba','Flute breath-stream avoidance','Positioning the microphone out of the jet of air the flautist blows across the embouchure hole, so the mic does not pick up wind blasts, pops, and turbulence. It is achieved by placing the mic above, behind, or to the side of the air stream, by aiming along the body, or by using an omnidirectional mic, which is less sensitive to wind and pops.','A flute player blows a fast stream of air across the mouth hole. If a mic sits in that stream, it makes loud puffing and popping noises. Keeping the mic out of the air path, or using an omni mic, stops this.','It prevents wind noise and pops from spoiling an otherwise clean flute capture, so the recorded tone stays usable. Avoiding the air jet is a basic requirement of good flute miking.','A technician checks where the player’s breath exits, then moves the mic above or behind that jet, or switches to an omni, until the puffing stops.','Woodwind Miking',ARRAY['Flute embouchure-hole miking','Flute body-axis miking','Pop filter','Omnidirectional microphone','Wind noise','Close miking']::text[],ARRAY['Putting a directional mic right in front of the embouchure hole and getting constant wind blasts.','Blaming the noise on the mic or preamp instead of the air stream hitting the capsule.','Forgetting the player moves, so a spot that was clear drifts back into the breath jet.']::text[],ARRAY['Setting a flute mic that keeps popping from the player’s breath.','Choosing an omni to reduce wind noise on a close flute mic.','Repositioning a headworn flute mic to escape the air stream.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e083d057-0bdb-5fbd-ac71-079caa863eba' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flute breath-stream avoidance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e083d057-0bdb-5fbd-ac71-079caa863eba','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e083d057-0bdb-5fbd-ac71-079caa863eba' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9bf550a1-5886-549e-9427-a0a60836401a','Flute embouchure-hole miking','Placing the microphone near the embouchure (mouth) hole of the flute’s headjoint, often about 5–10 cm away and aimed between the mouthpiece and the left hand. It captures an intimate, breathy character with the attack of the air jet, but sits close to the breath stream, so wind noise must be managed.','The embouchure hole is the hole the player blows across at the top of the flute. Miking close to it gives a breathy, up-close sound with lots of air. Because it is near the breath, you must watch for wind noise.','It captures the airy, intimate side of the flute — breath and attack — for a close, expressive sound. Engineers choose it when they want character and presence rather than maximum isolation.','For an intimate solo flute, a technician sets the mic about 5–10 cm from the headjoint, aimed between the mouthpiece and the hands, then guards against wind pops.','Woodwind Miking',ARRAY['Flute body-axis miking','Flute breath-stream avoidance','Pop filter','Proximity effect','Close miking','Omnidirectional microphone']::text[],ARRAY['Sitting the mic directly in the air jet, so breath blasts overwhelm the tone.','Getting too close with a directional mic, so proximity effect and key noise dominate.','Chasing breathiness so hard that the note itself loses body and focus.']::text[],ARRAY['Recording an intimate, breathy solo flute for a ballad.','Capturing the airy attack of a jazz flute close up.','Adding expressive breath detail that a distant mic would miss.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9bf550a1-5886-549e-9427-a0a60836401a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flute embouchure-hole miking'),'[^a-z0-9]','','g'));
