SELECT '9bf550a1-5886-549e-9427-a0a60836401a','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9bf550a1-5886-549e-9427-a0a60836401a' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '94e63685-2832-5963-a1fb-91507524b835','French-horn rear-bell miking','Miking the French horn from behind the player, where the bell faces, since the horn’s bell points backward and to the player’s right. This captures the horn’s direct, brighter high-frequency radiation from the bell, giving more edge and level than a mic placed in front of the player.','A French horn’s bell points backward, not forward. So the clearest, brightest sound comes out behind the player. Placing a mic back there catches that direct bell tone with more edge and volume.','It captures the horn’s direct bell radiation and brightness, which a front mic misses because the bell faces away from the audience. This gives the engineer level and presence on a naturally rear-firing instrument.','A technician places a mic behind and slightly to the right of the horn player, toward the bell, to get a direct, present horn sound with more high-end.','Brass Miking',ARRAY['French-horn wall-reflection capture','Off-axis rejection','Close miking','Bell','Proximity effect','Overhead microphone']::text[],ARRAY['UNSAFE: Placing a mic and monitoring close behind a loud horn without hearing protection; brass peaks can exceed 140 dB sound pressure level, so protect your ears and limit exposure.','Getting the mic too close to the bell, so the sound turns harsh and brassy and valve noise intrudes.','Miking only from the front and wondering why the horn sounds dull and distant.']::text[],ARRAY['Close-miking a horn for a pop or film session that needs presence.','Reinforcing a horn player on a loud stage from the bell side.','Capturing a brighter, more direct horn sound for a solo line.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='94e63685-2832-5963-a1fb-91507524b835' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('French-horn rear-bell miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '94e63685-2832-5963-a1fb-91507524b835','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='94e63685-2832-5963-a1fb-91507524b835' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6966c42b-b03b-56f7-9764-9d2ccdd50660','French-horn wall-reflection capture','Capturing the French horn’s sound after it reflects off a hard surface behind the player, since the bell fires backward. Orchestral horns are often seated in front of a reflective wall or riser that returns their sound toward the audience and the main microphones; this technique deliberately uses that reflected energy rather than direct bell pickup.','Because a horn’s bell points backward, players often sit in front of a hard wall. The wall bounces the sound forward to the audience. Miking that reflected sound is a natural way to record the horn.','It gives a blended, natural horn tone by using the reflection the players already rely on, instead of a close, edgy bell mic. This suits orchestral and film-score recording where section blend matters.','Recording an orchestra, an engineer lets the main or section mics pick up the horns’ sound reflected off the rear wall or a placed reflector, keeping a warm, blended tone.','Brass Miking',ARRAY['French-horn rear-bell miking','Boundary microphone','Room reflection','Close miking','Off-axis rejection','Overhead microphone']::text[],ARRAY['Removing or missing the reflective surface behind the horns, so the section sounds weak and distant to the front mics.','Relying on a reflection off an untreated, boomy wall that colours the tone badly.','Expecting close-mic edge from a reflected capture; it trades bite for blend.']::text[],ARRAY['Recording an orchestral horn section that plays into a hard rear wall.','Using a placed reflector behind horns on a scoring stage.','Capturing a warm, blended horn tone for a film cue.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6966c42b-b03b-56f7-9764-9d2ccdd50660' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('French-horn wall-reflection capture'),'[^a-z0-9]','','g'));
