WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6966c42b-b03b-56f7-9764-9d2ccdd50660' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '18fd33bc-2ff9-5561-a086-3fe40bedab25','Front-of-kit microphone','A microphone placed out in front of the whole drum kit, typically at around waist to chest height and a short distance from the drums, to capture a balanced, blended picture of the kit rather than one drum. It is often a single mono mic used to add body, weight, and attack, and is sometimes heavily compressed for effect, as distinct from the close shell mics and the overheads.','A front-of-kit mic sits out in front of the whole drum set, not on one drum. It hears the kit as one blended sound. Engineers mix it in to add weight and a sense of the room.','It captures the drums as a whole from the audience side, adding glue, body, and impact that spot mics on single drums do not give. This blended perspective ties the close mics and overheads together.','A technician stands a mic a few feet in front of the kit at chest height, then blends it — often compressed — under the overheads and shell mics for added weight and punch.','Drum Miking',ARRAY['Overhead microphone','Drum-shell microphone','Close miking','Parallel compression','Room microphone','Proximity effect']::text[],ARRAY['Adding the front mic without checking phase against the overheads and shell mics, so the whole kit thins out.','Placing it too close to the kick, so it just becomes another boomy kick mic instead of a balanced kit picture.','UNSAFE: Standing at the front mic position for long during a loud kit sound-check without hearing protection; wear earplugs and limit exposure to established noise limits.']::text[],ARRAY['Blending a compressed front mic to add weight and glue to a rock drum sound.','Capturing an audience-side picture of the kit to complement close mics.','Adding a mono front mic for extra body on a live drum submix.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='18fd33bc-2ff9-5561-a086-3fe40bedab25' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Front-of-kit microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '18fd33bc-2ff9-5561-a086-3fe40bedab25','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='18fd33bc-2ff9-5561-a086-3fe40bedab25' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e151b6f6-da03-51ce-b5bf-4da8b211e27c','Glockenspiel off-axis miking','Placement of a microphone off the direct radiating axis of a glockenspiel''s metal bars so the harsh, high-frequency attack transients and ringing overtones are attenuated. Because directional microphones roll off high frequencies as the angle to the source increases, angling the capsule away from a straight-on aim tames the instrument''s percussive brightness while retaining pitch and body.','A glockenspiel is a set of tuned metal bars hit with mallets. It makes a very bright, sharp, ringing sound. Pointing the mic slightly to the side, not straight at the bars, softens that harsh edge.','It uses a microphone''s natural high-frequency loss at wide angles to control an instrument whose metallic transients can sound piercing on-axis. This yields a more musical, less brittle tone without added equalization.','A recording engineer angles a small-diaphragm condenser above the glockenspiel, aiming off to one side rather than straight down, then fine-tunes the angle by ear to trade brightness against attack.','Percussion Miking',ARRAY['Off-axis coloration','Polar pattern','Small-diaphragm condenser','Transient response','High-frequency roll-off','Spot microphone']::text[],ARRAY['Aiming the microphone straight on-axis and then cutting highs with EQ, when a small angle change would tame the harshness more naturally.','Placing the mic so close that mallet and bar contact noise dominates the tuned tone.','UNSAFE: Monitoring a bright metallic source like this at high headphone or speaker levels for long stretches, risking hearing damage; keep levels moderate and take breaks.']::text[],ARRAY['Recording an orchestral percussion overdub where the glockenspiel is too shrill when miked straight on.','Capturing a glockenspiel in a pop production so it sits under vocals without piercing the mix.','Tracking a marimba-and-glockenspiel percussion setup where each metal instrument needs a controlled top end.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e151b6f6-da03-51ce-b5bf-4da8b211e27c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Glockenspiel off-axis miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e151b6f6-da03-51ce-b5bf-4da8b211e27c','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e151b6f6-da03-51ce-b5bf-4da8b211e27c' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6d9fb65e-1960-5077-8833-68ded98b5242','Glyn Johns side microphone','The second overhead microphone in the Glyn Johns drum-recording method, placed low to the drummer''s right near the floor tom and aimed across the kit toward the hi-hat and snare. It is positioned the same distance from the snare as the main overhead so the snare stays phase-coherent and centered when the two mics are combined.','This is one mic used in a famous drum recording setup. It sits low by the floor tom and looks across the kit. It is kept the same distance from the snare as the main overhead mic. That equal spacing keeps the drums sounding solid and centered.','It supplies the second channel of a two-microphone kit image, adding width and capturing the toms and hi-hat side of the kit. Matching its snare distance to the main overhead prevents phase cancellation of the snare.','An engineer measures from the snare to the main overhead with a cable or tape, then sets the side mic the same distance away, low by the floor tom, and checks snare phase in mono before tracking.','Drum Miking',ARRAY['Glyn Johns technique','Overhead microphone','3:1 rule','Phase coherence','Mono compatibility','Snare microphone']::text[],ARRAY['Setting the side mic a different distance from the snare than the main overhead, which thins or hollows the snare in mono.','Forgetting to check the two overheads summed to mono for phase problems before committing.','UNSAFE: Positioning your head at the kit to place mics while a drummer plays at full volume without hearing protection; wear earplugs around loud drums.']::text[],ARRAY['Recording a rock drum kit with a vintage, minimal-mic aesthetic.','Tracking drums in a good-sounding room where kit balance matters more than isolation.','Setting up a two-overhead image that must fold down to mono for broadcast.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6d9fb65e-1960-5077-8833-68ded98b5242' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Glyn Johns side microphone'),'[^a-z0-9]','','g'));
