INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd160d631-f3df-5cd9-86b5-7509080ea836','Glyn Johns technique','A minimal drum-recording method, popularized by engineer Glyn Johns, that captures a full kit with roughly three to four microphones: one overhead above and slightly in front of the snare, a second overhead low to the drummer''s right by the floor tom, plus close mics on the kick and snare. The two overheads are placed equidistant from the snare so the whole kit images coherently and folds down to mono without phase cancellation.','A simple way to record a whole drum kit with only a few mics. One mic hangs above the kit and one sits low by the floor tom. Both are placed the same distance from the snare. Close mics on the kick and snare add punch. The equal spacing keeps the drums sounding clear and solid.','It trades many close mics for a phase-coherent, natural kit sound built mostly from two overheads, letting the room and the kit''s own balance do the work. The equal-distance rule keeps the snare centered and phase-stable across the overheads.','An engineer sets one overhead about a stick-length or more above the snare, sets the side overhead the same distance from the snare by the floor tom, adds kick and snare mics, then balances the kit almost entirely with the two overheads.','Drum Miking',ARRAY['Glyn Johns side microphone','Overhead microphone','3:1 rule','Phase coherence','Kick microphone','Room microphone']::text[],ARRAY['Not keeping both overheads equidistant from the snare, which collapses the snare in mono.','Relying on close mics for balance and losing the coherent, room-driven sound the method is meant to give.','UNSAFE: Working close to a loudly played kit while positioning mics without ear protection, risking noise-induced hearing loss.']::text[],ARRAY['Recording a drummer whose kit already sounds great in a live room.','Producing a retro rock or blues record that wants a vintage drum sound.','Tracking drums quickly with limited inputs while keeping a natural stereo image.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d160d631-f3df-5cd9-86b5-7509080ea836' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Glyn Johns technique'),'[^a-z0-9]','','g'));
