INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a5874b5c-cc56-55a7-8481-d7a056c91bdc','Gong center miking','Positioning a microphone near the central striking area of a gong or tam-tam to emphasize its fundamental and low-frequency bloom. Compared with edge placement, center miking captures more body, weight, and the initial impact, with relatively less of the high shimmer that develops toward the rim.','A gong is a large metal disc that rings when struck. Miking near its middle captures the deep, full, low tones. You get more body and impact and less bright shimmer.','It targets the region of the gong that radiates the strongest low-frequency energy, giving a fuller, darker capture. This suits parts that need weight and impact rather than airy wash.','A percussion engineer aims a large-diaphragm condenser or dynamic at the gong''s center from a safe distance, adjusting distance to control the low-end bloom and avoid overload on hard strikes.','Percussion Miking',ARRAY['Gong edge miking','Large-diaphragm condenser','Proximity effect','Sound pressure level','Transient response','Spot microphone']::text[],ARRAY['Placing the mic too close to a hard-struck gong and overloading the capsule or preamp on peaks.','Expecting shimmer and wash from a center position, which favors body and fundamental instead.','UNSAFE: Standing directly in front of a struck gong at close range; large gongs produce very high sound pressure levels, so use hearing protection and distance.']::text[],ARRAY['Recording a dramatic orchestral gong hit that needs deep, powerful low end.','Capturing a tam-tam accent in a film score for weight and impact.','Layering a gong under a mix where body matters more than high-frequency wash.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a5874b5c-cc56-55a7-8481-d7a056c91bdc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gong center miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a5874b5c-cc56-55a7-8481-d7a056c91bdc','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a5874b5c-cc56-55a7-8481-d7a056c91bdc' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0920fef3-deab-5f43-9e54-a7f1702a4fdd','Gong edge miking','Positioning a microphone toward the outer rim of a gong or tam-tam to emphasize its high overtones, shimmer, and the swelling wash that builds after the strike. Compared with center placement, edge miking captures less fundamental weight and more of the bright, complex upper harmonics.','Placing the mic near the outer rim of the gong. This catches the bright, shimmering wash of the sound. It has more high overtones and less deep body than miking the middle.','It targets the rim region where high-frequency overtones and the characteristic wash are strongest, giving a shimmering, airy capture. This suits parts that need sparkle and swell rather than deep impact.','A percussion engineer aims a condenser toward the gong''s edge from a safe distance, blending it with a center mic to balance shimmer against body.','Percussion Miking',ARRAY['Gong center miking','Overtone','Small-diaphragm condenser','Sound pressure level','Spot microphone','Off-axis coloration']::text[],ARRAY['Expecting deep body and impact from an edge position, which favors high shimmer and wash.','Getting so close to the rim that the swelling overtones overload the mic on loud strikes.','UNSAFE: Miking a large gong at close range without hearing protection; the high sound pressure levels can damage hearing.']::text[],ARRAY['Recording a cymbal-like shimmering gong swell for an ambient track.','Capturing the airy wash of a tam-tam to layer with a punchier center mic.','Tracking a gong crescendo where the rising overtone wash is the featured sound.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0920fef3-deab-5f43-9e54-a7f1702a4fdd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gong edge miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0920fef3-deab-5f43-9e54-a7f1702a4fdd','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0920fef3-deab-5f43-9e54-a7f1702a4fdd' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f7d53b3e-8e98-5d61-a073-fc16e61fd220','Guitar-cabinet rear miking','Placing a microphone behind an open-back guitar speaker cabinet to capture the rear radiation of the speaker. Because the back of the cone moves opposite to the front, the rear signal is polarity-inverted relative to a front mic and is normally polarity-flipped before it is blended, adding low-end and a different tonal color.','A mic placed behind an open-back guitar amp speaker. The back of the speaker pushes air the opposite way to the front. So engineers usually flip this mic''s signal before blending it with a front mic. This can add fullness and a different flavor to the tone.','It captures tonal energy the front of the cabinet does not, especially added low-end and body, giving the engineer more blend options. Flipping its polarity keeps it in phase with the front mic so the two reinforce rather than cancel.','An engineer sets a mic behind an open-back combo, engages polarity invert on that channel, and blends it with a front mic while listening for the fullest, most in-phase combined tone.','Guitar Amp Miking',ARRAY['Polarity inversion','Phase coherence','3:1 rule','Open-back cabinet','Close miking','Comb filtering']::text[],ARRAY['Blending the rear mic without flipping its polarity, which cancels low end and hollows the tone.','Assuming rear miking works on a closed-back cabinet, which has no useful rear radiation to capture.','UNSAFE: Reaching behind a live, loud cabinet without ear protection or awareness of high sound pressure levels at the speaker.']::text[],ARRAY['Recording an open-back combo amp and wanting extra low-end from a rear capture.','Blending front and rear mics on an electric guitar cab for a thicker tone.','Troubleshooting a thin blended guitar sound caused by an un-flipped rear mic.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f7d53b3e-8e98-5d61-a073-fc16e61fd220' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Guitar-cabinet rear miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f7d53b3e-8e98-5d61-a073-fc16e61fd220','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f7d53b3e-8e98-5d61-a073-fc16e61fd220' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7b58ed9a-955d-5f77-b177-5e9a7fe8e617','Guitar-cabinet room reinforcement','The use of one or more distant room microphones alongside the close mic on a guitar cabinet to add natural reflections, depth, and size to the recorded tone. The room mic captures the cabinet blended with the acoustics of the space, and is mixed under the close mic to taste.','Adding a second mic farther back in the room from a guitar amp. It picks up natural echoes off the walls. Blending it with the close mic adds size and depth to the sound.','It reintroduces the natural ambience and sense of space that close miking removes, letting an engineer control how big or roomy the guitar sounds. Balancing room against close mic sets the perceived distance.','An engineer places a mic several feet from the cabinet, observes the 3:1 spacing relative to the close mic, checks the two summed in mono for phase, and blends in the room mic for depth.','Guitar Amp Miking',ARRAY['Room microphone','3:1 rule','Close miking','Phase coherence','Reverberation','Ambience']::text[],ARRAY['Ignoring the 3:1 spacing between close and room mics, causing comb filtering when they are combined.','Adding so much room mic that the guitar loses focus and sits back too far in the mix.','UNSAFE: Cranking the amp to fill the room while working close to it without hearing protection, risking hearing damage.']::text[],ARRAY['Recording electric guitar in a live-sounding room to capture natural depth.','Blending a room mic under a close mic to make a rhythm guitar sound bigger.','Adding ambience to a solo without relying only on artificial reverb.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7b58ed9a-955d-5f77-b177-5e9a7fe8e617' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Guitar-cabinet room reinforcement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7b58ed9a-955d-5f77-b177-5e9a7fe8e617','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7b58ed9a-955d-5f77-b177-5e9a7fe8e617' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '67149e2b-b20e-5a9f-a535-dddb51ea590f','Guitar-speaker phase-center alignment','Aligning the arrival times of multiple microphones on a single guitar speaker so their signals sum coherently rather than comb-filter. In practice this means matching the distance from each capsule to the speaker (or time-aligning the tracks afterward) so peaks and troughs line up and the combined tone stays full.','When you use more than one mic on a guitar amp, their signals can clash. This happens when the mics sit at different distances from the speaker. Lining them up so sound reaches them at the same time keeps the tone strong and clear.','It prevents comb filtering, the hollow, phasey thinning that occurs when two mics at unequal distances capture the same source. Aligning the capsules or time-shifting the tracks makes multiple mics reinforce one another.','An engineer positions two mics with their capsules the same distance from the speaker grille, checks the summed signal for phase, and nudges one mic or slides a track in the DAW until the tone is fullest.','Guitar Amp Miking',ARRAY['Comb filtering','Phase coherence','3:1 rule','Time alignment','Polarity inversion','Close miking']::text[],ARRAY['Placing two mics at different distances from the cone and getting a thin, hollow combined sound.','Confusing a polarity flip with true time alignment; flipping polarity does not fix a time offset between mics.','Assuming a single mic needs phase alignment, when the issue only arises with two or more mics on the same source.']::text[],ARRAY['Blending a dynamic and a condenser on one guitar speaker without phase cancellation.','Time-aligning a close mic and a room mic on an amp inside a DAW.','Fixing a thin two-mic guitar tone traced to unequal mic distances.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='67149e2b-b20e-5a9f-a535-dddb51ea590f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Guitar-speaker phase-center alignment'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '67149e2b-b20e-5a9f-a535-dddb51ea590f','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='67149e2b-b20e-5a9f-a535-dddb51ea590f' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '26dd43b3-6db4-5d6b-96ff-383d2683138b','Hand-percussion underside miking','Placing a microphone beneath or at the resonant opening of a hand percussion instrument, such as a cajon, frame drum, or conga, to capture the low-frequency body and resonance that radiate from the underside or sound hole. It is often combined with a mic on the striking surface to balance attack against low-end.','Placing a mic under a hand drum, like a cajon or frame drum. The underside or sound hole is where the deep tones escape. This spot captures more low-end body and warmth.','It captures the resonant low-frequency energy that the playing surface alone does not project, adding fullness and body. Pairing it with a front mic lets the engineer blend attack and depth.','A recording engineer positions a mic at a cajon''s rear sound port or under a frame drum, then blends it with a mic on the front head to dial in the ratio of slap to boom.','Percussion Miking',ARRAY['Sound hole','Proximity effect','Resonance','Close miking','Phase coherence','Spot microphone']::text[],ARRAY['Combining underside and top mics without checking polarity, which can cancel the low end.','Placing the underside mic directly in the port''s air blast, causing wind noise and pops.','Relying on the underside mic alone and losing the stick or hand attack that defines the groove.']::text[],ARRAY['Recording a cajon by miking both the front face and the rear sound port.','Capturing the deep resonance of a frame drum for a cinematic percussion layer.','Adding low-end body to congas by miking underneath as well as on top.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='26dd43b3-6db4-5d6b-96ff-383d2683138b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hand-percussion underside miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '26dd43b3-6db4-5d6b-96ff-383d2683138b','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='26dd43b3-6db4-5d6b-96ff-383d2683138b' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '338d84e8-8242-5f5a-83e3-dc7b51526b06','Hi-hat bell miking','Aiming a hi-hat microphone over the bell, the raised central cup of the cymbal, to emphasize a defined stick attack and the tighter, more focused character of that region. It captures a crisper ''chick'' with less of the wash produced toward the outer edge.','Aiming the hi-hat mic over the raised center cup, called the bell. This captures a clear, bright stick attack. It gives a tight, defined tick sound.','It targets the part of the hi-hat that produces the clearest transient and least air movement, giving a controlled, articulate sound. This helps the hi-hat cut through a busy mix without excess sizzle.','A drum engineer positions a small-diaphragm condenser a few centimeters above the bell area, angled away from the snare, to capture stick definition while rejecting kit bleed.','Drum Miking',ARRAY['Hi-hat edge rejection','Small-diaphragm condenser','Off-axis coloration','Cardioid','Spill','Transient response']::text[],ARRAY['Aiming at the outer edge instead of the bell and capturing air blast and excessive sizzle.','Positioning the mic where it sees the snare, increasing snare bleed into the hi-hat channel.','UNSAFE: Placing your head at cymbal level to set the mic while the drummer plays loudly without ear protection.']::text[],ARRAY['Recording a tight, articulate hi-hat for a pop or funk groove.','Isolating hi-hat stick attack from snare bleed on a busy kit.','Capturing a defined hi-hat that sits cleanly under vocals in a dense mix.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='338d84e8-8242-5f5a-83e3-dc7b51526b06' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hi-hat bell miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '338d84e8-8242-5f5a-83e3-dc7b51526b06','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='338d84e8-8242-5f5a-83e3-dc7b51526b06' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e87d9bb0-2b4d-5966-af31-74f003a74bcb','Hi-hat edge rejection','Positioning a hi-hat microphone so its capsule avoids the outer edge of the cymbals, where opening and closing the hi-hat forces a blast of air outward that causes wind pops and excessive sizzle. Angling the mic away from the edge, and away from the snare, rejects this air blast and reduces harshness.','When hi-hat cymbals open and close, the edges push out a puff of air. That air can thump or pop the mic. Angling the mic away from the edge avoids this and cuts harsh sizzle.','It keeps the moving air at the cymbal edge from hitting the diaphragm, preventing pops and an overly sizzly tone. Angling the capsule also uses the mic''s less sensitive side to reject snare and kit bleed.','A drum engineer places the hi-hat mic a few centimeters above the cymbal, over the bell or middle rather than the edge, angled so it cannot see the snare, to avoid the air blast and reduce spill.','Drum Miking',ARRAY['Hi-hat bell miking','Wind pop','Polar pattern','Spill','Off-axis coloration','3:1 rule']::text[],ARRAY['Aiming the mic straight at the hi-hat edge and capturing a puff of air every time it closes.','Angling the mic so it faces the snare, which raises snare bleed in the hi-hat track.','UNSAFE: Working with your ears close to loud cymbals while setting the mic without hearing protection.']::text[],ARRAY['Eliminating a thumping pop that appears whenever the drummer closes the hi-hat.','Reducing snare bleed and sizzle in a close-miked drum recording.','Setting up hi-hat capture on a loud kit where edge air blast is a problem.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e87d9bb0-2b4d-5966-af31-74f003a74bcb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hi-hat edge rejection'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e87d9bb0-2b4d-5966-af31-74f003a74bcb','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e87d9bb0-2b4d-5966-af31-74f003a74bcb' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4154cf0f-f33a-5046-ba30-aeddae51bca3','Inside–outside string-section spots','Accent, or spot, microphones placed at inner and outer positions across a string section so the ensemble can be reinforced and balanced under a main stereo array. Inner spots pick up players toward the center of the section and outer spots pick up the far side, letting the engineer even out level and presence across the desk of players.','Extra close ''spot'' mics placed along a string section in an orchestra. Some sit toward the inner players and some toward the outer players. They add clarity and balance under the main room mics.','Spot mics add presence and control to a section that the distant main array captures too weakly or unevenly. Splitting them inside and outside lets the engineer balance near and far players within the section.','A classical engineer sets a few spot mics along the violins, some toward the inner stands and some toward the outer, then mixes them low under the main pair, delaying them to align with the main array.','String Miking',ARRAY['Spot microphone','Main microphone array','Time alignment','Decca tree','3:1 rule','Off-axis coloration']::text[],ARRAY['Mixing spot mics in too loudly, which shrinks the natural depth and blend of the main array.','Failing to time-align the spots with the main array, causing phase smearing on the strings.','Placing spots so close that bow and rosin scratch dominate the natural section tone.']::text[],ARRAY['Reinforcing a string section under a Decca tree on an orchestral scoring session.','Balancing near and far violins that the main array captures unevenly.','Adding presence to strings in a film score without losing the room''s natural blend.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4154cf0f-f33a-5046-ba30-aeddae51bca3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Inside–outside string-section spots'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
