INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5e9b4dee-9141-59b2-9915-3ea0e740cd8e','Keywork-noise control','Techniques for minimizing the mechanical clatter of keys, pads, and valves picked up when close-miking woodwind and brass instruments. Control methods include increasing mic distance, angling the capsule away from the keywork toward the tone holes or bell, and choosing placement that favors the radiated tone over mechanical noise.','Woodwind keys and valves make clicks and clacks when pressed. Close mics can pick up this noise. Careful mic placement, distance, and angle keep the clatter out of the recording.','It keeps distracting mechanical noise from contaminating an otherwise clean instrument capture, which becomes worse the closer the mic sits. Thoughtful placement preserves tone while reducing clicks.','An engineer recording a clarinet or saxophone backs the mic off slightly and angles it toward the tone holes rather than straight at the keys, checking that pad and key noise stays low in the recording.','Wind Miking',ARRAY['Keywork-side miking','Tone hole','Close miking','Off-axis coloration','Proximity effect','Spot microphone']::text[],ARRAY['Placing the mic directly over the keys, which maximizes the click and clatter that is hardest to remove later.','Getting so close that every pad slap is captured, then trying to fix it with editing.','Assuming key noise can be fully removed in the mix rather than avoided at the source.']::text[],ARRAY['Recording a solo clarinet where audible key clatter would spoil a quiet passage.','Close-miking a saxophone on stage while keeping mechanical noise low.','Tracking a woodwind overdub that must sit exposed in a sparse arrangement.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5e9b4dee-9141-59b2-9915-3ea0e740cd8e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Keywork-noise control'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5e9b4dee-9141-59b2-9915-3ea0e740cd8e','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5e9b4dee-9141-59b2-9915-3ea0e740cd8e' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a4ade1b6-c20e-5c81-858f-5063ef21d5ea','Keywork-side miking','Aiming a microphone toward the keywork side of a woodwind instrument, rather than the bell, to capture a more balanced, natural tone that includes the sound radiating from the open tone holes. The trade-off is greater pickup of mechanical key and pad noise than a bell-oriented position.','Pointing the mic toward the key side of a woodwind, not the bell. This gives a balanced, natural tone from the open holes. The trade-off is that it may catch more key-click noise.','It captures the tone as it radiates from the tone holes along the body, which sounds more natural than the bell alone, especially on instruments whose bell only projects the lowest notes. It balances presence against mechanical noise.','A recording engineer aims a small-diaphragm condenser at the upper tone holes of a saxophone or clarinet, adjusting angle and distance to trade natural tone against key noise.','Wind Miking',ARRAY['Keywork-noise control','Tone hole','Bell miking','Close miking','Off-axis coloration','Small-diaphragm condenser']::text[],ARRAY['Miking only the bell and getting an unnatural, uneven tone because most notes radiate from the tone holes.','Aiming so close to the keys that mechanical noise overwhelms the tone.','Ignoring the extra key noise this position captures and failing to control it with angle or distance.']::text[],ARRAY['Recording a clarinet with a natural, even tone across its range.','Miking a saxophone for a balanced sound rather than a bell-heavy honk.','Capturing a flute or oboe where the tone-hole radiation carries the character.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a4ade1b6-c20e-5c81-858f-5063ef21d5ea' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Keywork-side miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a4ade1b6-c20e-5c81-858f-5063ef21d5ea','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a4ade1b6-c20e-5c81-858f-5063ef21d5ea' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6be73296-9611-5be0-931b-43e99ad745e2','Kick beater bleed','Unwanted leakage of the kick drum''s beater impact into other microphones on the kit, or excess beater-attack transient captured within the kick channel itself. Because the beater strike is a sharp, loud transient, it spills into nearby snare and tom mics and can muddy or double the kick attack when those tracks are combined.','The beater is the pad that strikes the kick drum. Its sharp thump can leak into nearby drum mics. This leaked attack is called beater bleed.','Naming this bleed helps engineers trace an unexpected ''click'' or doubled kick attack in other drum tracks to its source. Managing it with placement and the 3:1 rule keeps the kick clean and phase-coherent.','An engineer who hears a kick click in the snare track repositions mics to respect the 3:1 rule, uses gating, or angles the null of nearby mics away from the kick to reduce beater bleed.','Drum Miking',ARRAY['Spill','3:1 rule','Kick microphone','Noise gate','Phase coherence','Polar pattern']::text[],ARRAY['Blaming a muddy kick on EQ when the real cause is beater bleed adding a second, offset attack from other mics.','Placing kit mics too close together and violating the 3:1 rule, which worsens bleed and comb filtering.','Gating tracks so hard to remove bleed that natural cymbal and drum decay is chopped off.']::text[],ARRAY['Diagnosing a doubled or phasey kick attack traced to bleed in the tom mics.','Setting mic spacing on a kit to keep beater bleed under control.','Deciding whether to gate drum tracks to reduce kick beater spill.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6be73296-9611-5be0-931b-43e99ad745e2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kick beater bleed'),'[^a-z0-9]','','g'));
