SELECT '6be73296-9611-5be0-931b-43e99ad745e2','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6be73296-9611-5be0-931b-43e99ad745e2' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ca2f4523-ae5d-5acf-8ebd-de23376ca322','Kick beater-side microphone','A microphone positioned on the batter (beater) side of the bass drum, close to where the pedal beater strikes the head, to capture the attack transient and click of each stroke. It emphasizes high-frequency attack and definition over low-frequency body, and typically uses a dynamic capsule rated for high sound pressure levels.','This mic sits near where the pedal hits the kick drum head. It grabs the sharp click of each hit. Engineers use it to make the kick cut through a loud mix.','It isolates the percussive beater attack of the kick drum so the drum stays defined within a dense mix, letting engineers blend punch against low-end body captured by other mics.','A technician places a dynamic mic a few centimetres from the beater impact point, inside the shell or just off the batter head, and blends it with an outside low-end mic. On stage it helps the kick punch through guitars and cymbals.','Kick drum miking',ARRAY['Kick-in microphone','Kick-out microphone','Kick port miking','Kick-drum cavity microphone','Proximity effect','3:1 rule']::text[],ARRAY['Aiming the mic directly in line with the beater, capturing excessive mechanical click instead of a musical attack.','Forgetting to check polarity against the outside or front mic, causing low-end cancellation when the two are summed.','UNSAFE: Kick drums generate very high peak sound levels; working at close range without hearing protection risks permanent noise-induced hearing loss.','UNSAFE: Hot-patching a phantom-powered condenser with the channel fader up, which can produce a damaging loud transient and stress equipment and ears.']::text[],ARRAY['Tracking a rock kit where the kick must punch through distorted guitars.','Live front-of-house work, adding beater click so the kick reads on a large PA system.','Metal recording needing a tight, defined attack for fast double-kick passages.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ca2f4523-ae5d-5acf-8ebd-de23376ca322' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kick beater-side microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ca2f4523-ae5d-5acf-8ebd-de23376ca322','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ca2f4523-ae5d-5acf-8ebd-de23376ca322' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9a42461b-b675-56f7-a9e3-504a49bd424d','Kick port miking','A close-miking technique in which a microphone is inserted through the port hole, a cut vent in the bass drum''s resonant (front) head, allowing placement inside or at the mouth of the drum. Depth and angle relative to the port control the balance between beater attack and low-frequency body.','Many kick drums have a hole cut in the front skin. Engineers push a mic through that hole to record inside. Moving the mic in or out changes how much thump versus click you hear.','The port lets air escape and gives access to the drum''s interior, so a mic placed there captures a focused, adjustable blend of attack and low end that a sealed front head would not allow.','A technician feeds a dynamic kick mic on a short stand through the port and sets depth: deeper toward the beater for click, near the port edge for more low end. Wind blast from the escaping air is tamed by angling the mic off-axis.','Kick drum miking',ARRAY['Kick-in microphone','Kick-out microphone','Kick beater-side microphone','Kick-drum cavity microphone','Proximity effect','Resonant head']::text[],ARRAY['Aiming the mic straight through the port at the beater, producing wind blasts and low-frequency pumping from moving air.','Assuming every kick has a port; a sealed front head needs a front-head mic or a different technique.','UNSAFE: The interior of a kick drum reaches very high sound levels; extended close work without hearing protection risks hearing damage.']::text[],ARRAY['Studio kick tracking through a ported front head.','Live sound where a ported head allows a quick, repeatable mic placement.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9a42461b-b675-56f7-a9e3-504a49bd424d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kick port miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9a42461b-b675-56f7-a9e3-504a49bd424d','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9a42461b-b675-56f7-a9e3-504a49bd424d' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4b6f5100-73e0-5e80-bfa8-f7c905a8ad4e','Kick-drum cavity microphone','A microphone placed within the internal air cavity of the bass drum, mounted or suspended inside the shell so it sits in the drum''s resonant chamber. This position captures a blend of shell resonance, beater attack and internal low-frequency build-up while rejecting outside bleed.','This mic sits inside the drum, in the hollow space between the two skins. It hears the drum''s inner boom and the beat of the pedal. An internal mount holds it steady so it does not rattle.','Placing a mic inside the cavity captures the drum''s internal resonance and attack while blocking spill from cymbals and other drums, giving an isolated, punchy kick signal.','Technicians use an internal shock-mount system to fix a mic inside the shell, avoiding a floor stand and reducing bleed. It is common on touring kits for fast, repeatable setup.','Kick drum miking',ARRAY['Kick-in microphone','Kick port miking','Kick beater-side microphone','Kick-drum tunnel','Resonant head','Bleed']::text[],ARRAY['Mounting the mic so it touches the shell or a lug, transmitting mechanical rattle into the signal.','Leaving the internal mic without a shock-mount, so pedal vibration colours the sound.','UNSAFE: The sealed interior produces very high sound levels; placing and checking the mic without hearing protection risks hearing loss.']::text[],ARRAY['A touring act needing a stand-free, low-profile kick mic for fast changeovers.','A studio session where an internal mic isolates the kick from nearby toms and hi-hats.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4b6f5100-73e0-5e80-bfa8-f7c905a8ad4e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kick-drum cavity microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4b6f5100-73e0-5e80-bfa8-f7c905a8ad4e','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4b6f5100-73e0-5e80-bfa8-f7c905a8ad4e' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '149fac26-c9f6-5432-9dd7-57efcdc69982','Kick-drum tunnel','An acoustic enclosure, typically built from moving blankets, foam or a purpose-made shell, placed in front of the bass drum''s resonant head to form a tunnel around the front microphone. It isolates that mic from cymbal and room bleed and lets it sit at a chosen distance while controlling low-frequency reflections.','A kick tunnel is a small blanket-covered box built in front of the drum. The front mic sits inside it, shielded from cymbals and the room. It works like a tiny isolation booth just for the kick.','The tunnel shields the front mic so it captures mostly the drum''s low end rather than spill from cymbals and the room, letting engineers place the mic further back without picking up bleed.','A technician drapes packing blankets over a frame or two mic stands between the kick and the front mic, forming a tunnel, then places the outside mic inside it. It is a staple of studio drum tracking for a clean, deep kick.','Kick drum miking',ARRAY['Kick-drum tunnel microphone','Kick-out microphone','Kick-front microphone','Bleed','Isolation','Sub-kick']::text[],ARRAY['Building the tunnel from thin, reflective material that fails to block cymbal bleed.','Sealing the tunnel so tightly that trapped low-frequency resonance makes the kick boomy.','UNSAFE: Draping blankets over hot lighting instruments or other heat sources near the kit, creating a fire hazard.']::text[],ARRAY['Studio drum tracking where a deep, isolated kick is wanted.','Live-to-tracking sessions in an untreated room needing extra kick isolation.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='149fac26-c9f6-5432-9dd7-57efcdc69982' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kick-drum tunnel'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '149fac26-c9f6-5432-9dd7-57efcdc69982','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='149fac26-c9f6-5432-9dd7-57efcdc69982' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6ce93852-1948-5741-b760-22b8de8cf7b9','Kick-drum tunnel microphone','The microphone placed at or within a kick-drum tunnel, the blanket or enclosure built in front of the resonant head, usually positioned some distance back from the head to capture the bass drum''s low-frequency body with minimal bleed. It is typically a large-diaphragm condenser or dedicated sub-kick style transducer.','This is the mic that lives inside the kick tunnel. It sits back from the front skin, shielded from cymbals. Its job is to capture the big, deep low end of the kick.','Sitting inside the tunnel, this mic captures a full, weighty low-frequency image of the kick while the enclosure blocks bleed, complementing a close inside mic that supplies the attack.','A technician places a large-diaphragm condenser or sub-kick mic a foot or more from the resonant head inside the tunnel, then time-aligns it with the inside mic and blends it underneath for depth.','Kick drum miking',ARRAY['Kick-drum tunnel','Kick-out microphone','Kick-front microphone','Sub-kick','Phase alignment','3:1 rule']::text[],ARRAY['Not time- or phase-aligning the distant tunnel mic with the close mic, causing low-end cancellation.','Choosing a mic that cannot handle high sound levels, so it distorts on loud hits.','UNSAFE: Prolonged close-range exposure to loud kick levels during setup without hearing protection risks hearing damage.']::text[],ARRAY['Adding weight and sub-bass content to a studio kick sound.','Blending a distant, isolated low-end capture under a punchy inside mic.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6ce93852-1948-5741-b760-22b8de8cf7b9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kick-drum tunnel microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6ce93852-1948-5741-b760-22b8de8cf7b9','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6ce93852-1948-5741-b760-22b8de8cf7b9' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '98ffebc0-722f-58fe-a79a-a5e3092d12b7','Kick-front microphone','A microphone positioned outside the bass drum facing the resonant (front) head, capturing the drum''s overall tone, body and low-frequency resonance rather than the beater attack. Distance and on- or off-axis angle to the head set the balance of low end against room sound.','This mic points at the front skin of the kick, from outside the drum. It picks up the drum''s full, round tone and low end. It hears the boom more than the click.','The front mic captures the resonant head''s tone and low-frequency body that an inside attack mic misses, so the two together give both punch and weight.','A technician stands a large-diaphragm mic in front of the resonant head, often within a tunnel, and blends it with the inside mic. Moving it closer adds low end through proximity effect; further back adds room.','Kick drum miking',ARRAY['Kick-out microphone','Kick-drum tunnel microphone','Kick-in microphone','Resonant head','Proximity effect','3:1 rule']::text[],ARRAY['Placing the front mic where port wind noise causes low-frequency pumping.','Ignoring polarity with the inside mic, cancelling the low end when the two are summed.','UNSAFE: Working at close range to a loud kit without hearing protection risks permanent hearing loss.']::text[],ARRAY['Capturing a full, deep kick tone in the studio.','Reinforcing low-end weight on a large live PA system.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='98ffebc0-722f-58fe-a79a-a5e3092d12b7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kick-front microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '98ffebc0-722f-58fe-a79a-a5e3092d12b7','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='98ffebc0-722f-58fe-a79a-a5e3092d12b7' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '75a7061c-44aa-5871-b83d-e3898d553e4f','Kick-in microphone','The microphone placed inside the bass drum, close to the batter head near the beater impact, to capture the attack and click of each stroke. It provides the transient definition of a multi-mic kick setup and typically uses a dynamic capsule rated for high sound pressure levels.','The in mic sits inside the kick drum, near where the pedal strikes. It captures the sharp attack of each hit. Engineers pair it with an out mic that adds low end.','The inside mic supplies the beater attack and definition that lets the kick cut through a mix, forming the attack half of a classic in-and-out pair.','A technician places a dynamic kick mic inside the shell a few centimetres from the beater and blends it against the out or front mic for body. It is the workhorse close mic on almost every rock and pop kit.','Kick drum miking',ARRAY['Kick-out microphone','Kick-front microphone','Kick beater-side microphone','Kick port miking','Phase alignment','Proximity effect']::text[],ARRAY['Aiming straight at the beater, producing an overly clicky, mechanical sound.','Neglecting to align polarity or phase with the out mic, cancelling low end when summed.','UNSAFE: Prolonged close-range exposure to a loud kit without hearing protection risks noise-induced hearing loss.','UNSAFE: Hot-patching a phantom-powered mic with the fader up, risking a damaging transient and speaker and ear stress.']::text[],ARRAY['Standard rock and pop kick close-miking for attack.','Live sound where the kick must punch through a full band.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='75a7061c-44aa-5871-b83d-e3898d553e4f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kick-in microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '75a7061c-44aa-5871-b83d-e3898d553e4f','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='75a7061c-44aa-5871-b83d-e3898d553e4f' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9895fd03-b7b7-577c-a05e-21da28d59d83','Kick-out microphone','The microphone placed outside the bass drum, in front of or near the resonant head, to capture low-frequency body and sustain; the low-end counterpart to the inside kick-in attack mic. It is often a large-diaphragm condenser or sub-kick placed a short distance from the front head, sometimes within a tunnel.','The out mic sits outside the kick, near the front skin. It captures the deep low end and boom of the drum. It teams up with the inside in mic for a full sound.','The out mic delivers the low-frequency weight and sustain the inside mic lacks, completing a full-range kick when the two signals are combined.','A technician positions a large-diaphragm mic just off the resonant head, time-aligns it with the in mic, and blends the two. Distance is adjusted to dial low end via proximity effect.','Kick drum miking',ARRAY['Kick-in microphone','Kick-front microphone','Kick-drum tunnel microphone','Sub-kick','Proximity effect','3:1 rule']::text[],ARRAY['Forgetting to check polarity with the in mic, thinning the low end when the two are summed.','Placing it where escaping port air blasts cause low-frequency pumping.','UNSAFE: Close-range work on a loud kit without hearing protection risks permanent hearing damage.']::text[],ARRAY['Building a full-range studio kick from an in-and-out pair.','Adding low-end reinforcement to a live kick sound.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9895fd03-b7b7-577c-a05e-21da28d59d83' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kick-out microphone'),'[^a-z0-9]','','g'));
