INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '25f90e48-0b2d-5274-a7f6-335076f6cbae','Lower-bout miking','A close-miking placement aimed at the lower bout, the wider lower half of an acoustic guitar''s or bowed-string instrument''s body below the waist, to emphasize low-frequency body and resonance rather than string attack. It is used alongside a brighter mic near the neck to balance warmth against clarity.','The lower bout is the wide bottom part of a guitar or violin body. Aiming a mic there captures the instrument''s warm, low tones. Engineers use it to add body without too much boom from the sound hole.','Miking the lower bout captures the body''s low-frequency radiation and warmth, balancing a brighter mic aimed near the neck or twelfth fret and helping shape overall tonal balance.','A technician aims a small-diaphragm condenser at the lower bout, off the sound hole, to add warmth, often pairing it with a mic near the twelfth fret. On cello or double bass the same idea captures body resonance.','String instrument miking',ARRAY['Sound hole miking','12th-fret miking','Proximity effect','3:1 rule','Spaced pair','Off-axis']::text[],ARRAY['Aiming at the sound hole instead of the bout, producing a boomy, bass-heavy tone.','Placing two mics too close together, causing comb filtering by ignoring the 3:1 rule.','Assuming closer is always better, so proximity effect overloads the low end.']::text[],ARRAY['Recording a warm, full acoustic-guitar tone.','Miking a cello or double bass for body and low-end resonance.','Balancing a bright neck mic with a warm body mic in a stereo pair.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='25f90e48-0b2d-5274-a7f6-335076f6cbae' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lower-bout miking'),'[^a-z0-9]','','g'));
