SELECT '25f90e48-0b2d-5274-a7f6-335076f6cbae','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='25f90e48-0b2d-5274-a7f6-335076f6cbae' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cf98b5c5-4663-571a-8135-67a15a2e83ae','Lower-joint miking','A close-miking placement aimed at the lower joint of a clarinet, the section between the upper joint and the bell where the lower tone holes radiate sound, capturing the instrument''s lower register and a natural blend rather than the bell alone. Typical placement is toward the tone holes about a third of the length up from the bell, at 15 to 20 centimetres.','The lower joint is the bottom section of a clarinet, above the bell. Sound comes out of its finger holes, not just the bell. Aiming a mic there gives a natural, balanced clarinet tone.','The lower tone holes radiate much of the clarinet''s sound, so miking the lower joint captures an even tone across registers instead of the harsh, uneven sound of aiming into the bell.','A technician aims a small-diaphragm condenser at the lower-joint tone holes, roughly a third up from the bell at 15 to 20 centimetres, or clips an instrument mic near the bell angled toward the keys.','Woodwind miking',ARRAY['Tone hole','Bell miking','Off-axis','Proximity effect','Instrument clip microphone','Spaced pair']::text[],ARRAY['Aiming straight into the bell, which over-emphasizes the highest notes and sounds unnatural.','Placing the mic so close that key and finger noise dominates the signal.','Using a very directional mic that sounds too focused to blend naturally.']::text[],ARRAY['Studio recording of a solo clarinet for an even, natural tone.','Amplifying a clarinet on stage with a clip-on mic at the lower joint and bell.','Section recording where each clarinet needs balanced pickup.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cf98b5c5-4663-571a-8135-67a15a2e83ae' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lower-joint miking'),'[^a-z0-9]','','g'));
