INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8153712d-dea2-522d-9e14-cf168a1c1913','Marimba bar-side miking','A miking approach that positions microphones to the side of the marimba''s bars rather than directly overhead, aiming across or along the rows of bars to capture the instrument while reducing mallet-attack harshness and keeping the mic clear of the player''s motion. It is used where overhead placement is impractical.','This mics a marimba from the side of the wooden bars instead of straight above. It keeps the mic out of the player''s way. It softens the hard mallet click while still catching the notes.','Side placement keeps mics clear of the player and music stand while still capturing the bars, and angling off the direct strike tames attack transients, serving as a practical alternative to overhead miking.','A technician places condenser mics on stands at bar height to the side of the instrument, angled across the bars, when overheads would block sightlines or catch too much bleed. It is common in pit and live settings.','Mallet percussion miking',ARRAY['Marimba resonator miking','Marimba low-end outrigger','Spaced pair','Overhead miking','Off-axis','3:1 rule']::text[],ARRAY['Placing the mic so far to one side that low bars are much quieter than high bars, unbalancing the range.','Ignoring the 3:1 rule between multiple mics, causing comb filtering.','Getting too close to the bars, so mallet attack and player movement dominate.']::text[],ARRAY['Pit-orchestra marimba where overhead mics are impractical.','Live percussion where sightlines and bleed force side placement.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8153712d-dea2-522d-9e14-cf168a1c1913' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Marimba bar-side miking'),'[^a-z0-9]','','g'));
