SELECT '8153712d-dea2-522d-9e14-cf168a1c1913','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8153712d-dea2-522d-9e14-cf168a1c1913' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f498eef1-2e62-5c54-872b-3df3034fdca3','Marimba low-end outrigger','A supplementary microphone placed out toward the low (bass) end of the marimba to reinforce the longer, lower-pitched bars and their resonators, whose fundamentals radiate less efficiently and can be under-represented by a central or overhead pair. It balances level across the instrument''s range.','The lowest marimba bars are big and quieter than the high ones. An outrigger is an extra mic placed out at that bass end. It boosts the deep notes so the whole range sounds even.','Because the low bars produce weaker, lower-radiating fundamentals, an outrigger mic at the bass end lifts their level so the marimba sounds balanced from top to bottom.','A technician adds a third mic on a stand at the bass end of the marimba, blended under the main pair, when the low register sounds thin. It is common on wide-range concert marimbas.','Mallet percussion miking',ARRAY['Marimba resonator miking','Marimba bar-side miking','Spaced pair','Resonator tube','Fundamental frequency','3:1 rule']::text[],ARRAY['Adding too much outrigger level, making the bass end boomy and unbalanced.','Not phase-checking the outrigger against the main pair, thinning the low end.','Aiming it at a single bar rather than the low-register group, causing uneven pickup.']::text[],ARRAY['Concert marimba recording where the low bars sound weak.','Reinforcing the bass register of a five-octave marimba live.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f498eef1-2e62-5c54-872b-3df3034fdca3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Marimba low-end outrigger'),'[^a-z0-9]','','g'));
