SELECT 'f498eef1-2e62-5c54-872b-3df3034fdca3','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f498eef1-2e62-5c54-872b-3df3034fdca3' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '03d1f0f3-1c4a-591c-ad1e-a2454bd76823','Marimba resonator miking','A miking approach that targets the marimba''s resonator tubes, the tuned pipes suspended beneath each bar that reinforce each note''s fundamental, usually by placing or angling mics toward the tube openings to capture a fuller, rounder low end. It emphasizes fundamental tone over bar attack.','Under each marimba bar hangs a tuned tube that boosts that note''s main pitch. Aiming a mic at these tube openings captures a fuller, rounder sound. It brings out warmth rather than the hard mallet click.','The resonator tubes amplify each bar''s fundamental, so miking near their openings captures the instrument''s warmth and body rather than only the bright bar attack.','A technician places or angles mics toward the resonator-tube mouths, often from below the frame, to add body, blending with an overhead or side mic for attack. It is useful when an overhead-only sound is too clicky.','Mallet percussion miking',ARRAY['Marimba low-end outrigger','Marimba bar-side miking','Resonator tube','Spaced pair','Fundamental frequency','Overhead miking']::text[],ARRAY['Placing the mic at one tube, over-emphasizing a single note instead of the whole range.','Miking only the resonators, losing the mallet attack and definition.','Blocking or detuning resonator tubes with a mic clamp mounted on the frame.']::text[],ARRAY['Studio marimba recording needing warmth and body.','Blending a resonator mic under a brighter overhead for a full tone.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='03d1f0f3-1c4a-591c-ad1e-a2454bd76823' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Marimba resonator miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '03d1f0f3-1c4a-591c-ad1e-a2454bd76823','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='03d1f0f3-1c4a-591c-ad1e-a2454bd76823' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '46fa71a0-d1fb-5db1-8b42-7422adfa22b2','Microphone working','The performer''s or engineer''s real-time technique of controlling the distance and angle between a sound source and the microphone during performance, often called working the mic or managing working distance, to regulate level, tame transients, and exploit or avoid proximity effect. Moving in adds level and low end; backing off reduces level and bass build-up.','Working a mic means moving closer or farther as you play or sing. Getting close makes the sound louder and bassier. Backing off softens loud notes. Performers do this to control their own volume and tone.','Adjusting working distance lets a performer control dynamics and tone at the source, smoothing loud peaks and shaping warmth without a fader move, making it a core microphone technique for consistent capture.','A vocalist moves in for intimate lines and pulls back on belted notes to avoid overload, while an engineer sets a starting working distance to balance proximity-effect bass against clarity. Technicians coach performers on it during soundcheck.','Microphone technique',ARRAY['Proximity effect','Working distance','Off-axis','3:1 rule','Plosive','Pop filter']::text[],ARRAY['Assuming a fixed mic position, so loud notes overload and quiet notes disappear.','Moving so far off-axis that the tone dulls and the level drops unpredictably.','Ignoring proximity effect, so leaning in makes the voice boomy and muddy.','UNSAFE: Cupping the capsule grille to change the tone, which invites feedback that can drive a PA to damaging levels and risk hearing.']::text[],ARRAY['A live vocalist controlling dynamics by moving on and off the mic.','A studio singer working distance to manage plosives and belted peaks.','A broadcaster holding a consistent working distance for even level.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='46fa71a0-d1fb-5db1-8b42-7422adfa22b2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Microphone working'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '46fa71a0-d1fb-5db1-8b42-7422adfa22b2','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='46fa71a0-d1fb-5db1-8b42-7422adfa22b2' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '029ed0e5-5472-593e-b467-4fa967c570ca','Nashville tuning','A guitar stringing and tuning method in which the lower four strings (E, A, D and G) are replaced with the thin octave strings from a 12-string set and tuned one octave above standard, while the top two strings (B and E) stay at normal pitch. Also called high-strung tuning, it produces a bright, shimmering timbre with no low fundamentals and is typically layered against a standard-tuned guitar in recording.','Nashville tuning swaps a guitar''s four thickest strings for thin ones tuned an octave higher. This gives a bright, sparkly sound with no deep low notes. Players record it on top of a normal guitar to add shimmer.','It exists to add high-register sparkle and 12-string-like shimmer to a recorded guitar part without the mud of doubled low strings, letting a second, standard-tuned guitar own the low end.','An engineer double-tracks a rhythm part with one guitar in standard tuning and a Nashville-tuned guitar, pans them apart, and blends them to imitate a 12-string or thicken the arrangement.','Guitar tuning',ARRAY['Double-tracking','Twelve-string guitar','Standard tuning','High-strung tuning','Layering']::text[],ARRAY['UNSAFE: Fitting standard-gauge lower strings and simply tuning them up an octave, which raises string tension far too high and can snap a string and whip toward the eyes or damage the neck.','Expecting Nashville tuning to work as a stand-alone rhythm sound; it is thin on its own and is meant to be layered with a standard-tuned guitar.','Confusing Nashville tuning with capo tricks or open tunings; it changes which octave the strings sound, not the pitch relationships between them.']::text[],ARRAY['Double-tracking an acoustic strum part to imitate the shimmer of a 12-string guitar.','Adding a bright, bell-like high layer under a lead vocal in a pop or country production.','Recording a jangly arpeggio to sit above a standard-tuned rhythm guitar in a mix.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='029ed0e5-5472-593e-b467-4fa967c570ca' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Nashville tuning'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '029ed0e5-5472-593e-b467-4fa967c570ca','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='029ed0e5-5472-593e-b467-4fa967c570ca' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '30190b34-6fcf-560b-b830-3a86357607f9','Oboe key-column miking','A close-miking approach for oboe and similar conical woodwinds in which the microphone is aimed at the column of keys and tone holes along the instrument''s body rather than at the bell. Because most of an oboe''s sound radiates from the first open tone holes for all but its lowest notes, placing the mic over the upper-middle body captures a more even, natural timbre and steadier level across the range.','An oboe makes most of its sound from the open finger holes along its body, not the end bell. So the mic is aimed at that row of keys and holes. This gives a fuller, more even sound than pointing at the end.','It exists to capture the oboe''s true tone and keep the volume even from note to note, since aiming only at the bell over-emphasizes the lowest notes and thins out the rest.','A classical engineer places a small cardioid or clip-on mic a short distance above the oboe''s upper body, angled at the key column, to get a balanced sound with minimal key noise.','Woodwind miking',ARRAY['Close miking','Off-bell miking','Proximity effect','Spot microphone','Cardioid pattern']::text[],ARRAY['Aiming the mic straight into the bell, which over-emphasizes the lowest notes and gives an uneven, honky tone across the range.','Placing the mic too close, which exaggerates mechanical key clatter and breath noise.','Assuming the oboe radiates from its bell like a trumpet; most of its sound leaves through the open tone holes.']::text[],ARRAY['Spot-miking a principal oboe within an orchestral recording to add presence without excess spill.','Close-miking an oboe in a small studio for a chamber or solo recording.','Reinforcing an oboe on a live stage where a clip-on mic must reject nearby instruments.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='30190b34-6fcf-560b-b830-3a86357607f9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Oboe key-column miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '30190b34-6fcf-560b-b830-3a86357607f9','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='30190b34-6fcf-560b-b830-3a86357607f9' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e9eab83d-235f-557d-89ab-4d3964c9e7d5','Off-axis guitar-cabinet miking','A technique for miking a guitar loudspeaker in which the microphone is angled away from, or moved off, the on-axis center of the speaker cone (the dust cap) rather than pointed straight at its middle. Because a speaker radiates its most intense high frequencies directly on-axis at the dust cap and rolls them off toward the cone edge and off-axis, off-axis placement yields a warmer, darker, less harsh tone.','A guitar speaker is brightest right at its center. Pointing the mic there gives a sharp, cutting sound. Aiming it off-center, toward the cone''s edge, rolls off the harsh highs. This gives a warmer, smoother tone.','It exists to tame the harsh, fizzy top end of a guitar cabinet and shape its tone, letting the engineer dial in brightness by choosing how far off-axis the mic sits.','An engineer angles a dynamic mic roughly off-axis on a 4x12 cabinet or slides it between the dust cap and the cone edge, listening until the recorded tone balances bite and warmth.','Amp/cabinet miking',ARRAY['Close miking','Dynamic microphone','Proximity effect','3:1 rule','Off-bell miking']::text[],ARRAY['Believing off-axis means far away; it refers to the mic''s angle and position relative to the cone, not its distance from the grille.','UNSAFE: Standing in front of a loud guitar cabinet for long sessions without hearing protection; close cabinet levels can exceed safe exposure limits and damage hearing.','Moving the mic randomly instead of making small angle and position changes to fine-tune brightness.']::text[],ARRAY['Taming a bright, fizzy high-gain amp so the recorded guitar sits well in a dense mix.','Blending an on-axis and an off-axis mic on the same cabinet to balance attack and warmth while watching phase.','Reducing harshness on a combo amp in a small room without changing the amp settings.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e9eab83d-235f-557d-89ab-4d3964c9e7d5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Off-axis guitar-cabinet miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e9eab83d-235f-557d-89ab-4d3964c9e7d5','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e9eab83d-235f-557d-89ab-4d3964c9e7d5' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '61099505-9e2a-51b0-af54-1f2231ac6d55','Off-bell miking','A brass and wind miking technique in which the microphone is placed to the side of, or angled away from, the direct axis of the instrument''s bell rather than pointed straight into it. The on-axis bell produces the brightest, most directional high-frequency output and the highest sound-pressure levels, so moving off the bell axis yields a warmer, less harsh tone and reduces the risk of overloading the microphone.','A trumpet or trombone shoots its brightest, loudest sound straight out of the bell. Aiming a mic right into it sounds harsh and can overload. Placing the mic off to the side gives a warmer, smoother sound.','It exists to soften the piercing on-axis high end of brass, protect the microphone from extreme sound-pressure peaks, and produce a more natural, blended tone.','An engineer positions a mic roughly 30 to 50 cm from a trumpet bell and angles it off-center, tilting the mic''s bright axis down or to the side to warm the tone.','Brass/wind miking',ARRAY['Off-axis guitar-cabinet miking','Proximity effect','Sound pressure level','Oboe key-column miking','Cardioid pattern']::text[],ARRAY['UNSAFE: Aiming a microphone straight into a brass bell at close range without adequate headroom or hearing protection; peak levels can exceed 140 dB, risking mic overload and hearing damage.','Pointing the mic directly at the bell and then blaming the microphone for a harsh, edgy tone that off-axis placement would fix.','Placing the mic so close that the player''s aim drifts on and off the diaphragm and the level jumps around.']::text[],ARRAY['Recording a trumpet solo where straight-on placement sounds too bright and brittle.','Miking a trombone section on a live stage to control level peaks and harshness.','Capturing a warm, vintage brass tone by working off the bell axis.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='61099505-9e2a-51b0-af54-1f2231ac6d55' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Off-bell miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
