WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='61099505-9e2a-51b0-af54-1f2231ac6d55' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '855bb5d8-f083-5fb7-ace9-00db246c849d','Off-f-hole miking','A string-instrument miking technique in which the microphone is aimed slightly off, rather than directly at, an f-hole, the f-shaped sound port of archtop guitars, violins, cellos and double basses. Because the f-holes radiate strong low-frequency body resonance, pointing straight at one produces a boomy, uneven tone; placing the mic off the f-hole, toward the bridge or fingerboard, captures a more balanced, natural sound.','The f-shaped holes on a violin or archtop guitar pump out strong low notes. Aiming a mic right at one sounds boomy and uneven. Pointing the mic a little off the hole, toward the bridge, gives a more balanced sound.','It exists to avoid the boomy low-end buildup and one-note resonance that come from miking straight into an f-hole, giving a more even, natural capture of the instrument.','An engineer recording a cello or archtop places the mic a short distance out and angles it off the f-hole toward the bridge, adjusting until the low end is full but not boomy.','String miking',ARRAY['Proximity effect','Off-bell miking','Close miking','Spot microphone','Cardioid pattern']::text[],ARRAY['Aiming straight into the f-hole for more body, which produces a boomy tone dominated by one resonant frequency.','Placing a directional mic very close to the f-hole, where proximity effect piles on even more unwanted low end.','Assuming every string instrument is miked the same way; f-hole radiation differs from a flat-top guitar''s round sound hole.']::text[],ARRAY['Close-miking a cello or double bass in a studio without a boomy, one-note low end.','Recording an archtop jazz guitar acoustically for a natural, balanced tone.','Spot-miking a violin in an ensemble where direct f-hole aim would sound harsh and uneven.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='855bb5d8-f083-5fb7-ace9-00db246c849d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Off-f-hole miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '855bb5d8-f083-5fb7-ace9-00db246c849d','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='855bb5d8-f083-5fb7-ace9-00db246c849d' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '73b1d8c1-22b8-5aa2-83e3-6c95b0febcb6','Overhead equidistance','The practice of positioning stereo overhead microphones so each is the same physical distance from a chosen reference point, usually the snare drum, so that reference arrives at both mics at the same time, level and phase. Equidistant placement keeps the snare and kit center phase-coherent and centered in the stereo image and avoids comb-filtering when the two overheads are summed.','When two overhead mics sit above a drum kit, each should be the same distance from the snare. Then the snare''s sound reaches both mics at the same moment. This keeps it centered and avoids a hollow, phasey sound when the mics are mixed together.','It exists to keep the most important drum, the snare, arriving in phase and centered in both overheads, preventing the comb-filtering and off-center image that unequal distances cause.','An engineer runs a cable or tape measure from the snare to each overhead capsule, sets both to an identical length, and only then fine-tunes the stereo width.','Overhead miking',ARRAY['3:1 rule','Comb filtering','Phase cancellation','Overhead-and-shoulder array','Spaced pair','Stereo imaging']::text[],ARRAY['Setting the two overheads by eye instead of measuring, leaving the snare off-center and slightly phasey in the mix.','Matching distance to the kick or cymbals instead of the snare, so the dominant snare sound smears.','Ignoring phase when combining the overheads with the close snare mic, which thins and hollows the snare.']::text[],ARRAY['Setting up a spaced overhead pair for a rock drum recording.','Checking overhead phase before printing drum tracks in a session.','Troubleshooting a snare that sounds thin and off-center once the overheads are added.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='73b1d8c1-22b8-5aa2-83e3-6c95b0febcb6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Overhead equidistance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '73b1d8c1-22b8-5aa2-83e3-6c95b0febcb6','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='73b1d8c1-22b8-5aa2-83e3-6c95b0febcb6' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3c825327-585e-561d-9a70-76487a8b19bd','Overhead-and-shoulder array','A drum-miking array that combines conventional overhead microphones with a pair of shoulder mics placed near or just above the drummer''s shoulders, looking down and forward over the kit. The shoulder pair captures the kit roughly from the player''s own perspective, closer to snare and toms than high overheads, while the overheads provide cymbal balance and stereo width, together giving a fuller, more present picture of the whole kit.','This drum setup uses high overhead mics plus two more near the drummer''s shoulders. The shoulder mics hear the kit the way the drummer does. Together they give a full, natural picture of the drums, with clear cymbals and punchy toms.','It exists to blend the wide, airy cymbal sound of overheads with a closer, more balanced view of snare and toms from the drummer''s vantage, reducing the need for many close mics.','An engineer sets a spaced overhead pair for cymbals and adds shoulder mics angled down over each of the drummer''s shoulders, keeping all capsules equidistant from the snare to stay phase-coherent.','Drum miking',ARRAY['Overhead equidistance','Spaced pair','3:1 rule','Spot microphone','Phase cancellation']::text[],ARRAY['Placing the shoulder mics at unequal distances from the snare, which throws the kit off-center and smears phase with the overheads.','Treating the shoulder mics as spot mics on single drums instead of as a balanced pair over the whole kit.','UNSAFE: Working close to a loud drum kit for long periods without hearing protection; kit peaks are high enough to threaten hearing over time.']::text[],ARRAY['Recording drums with a minimal mic count while still getting a full kit sound.','Capturing a natural, drummer''s-perspective kit balance for jazz or acoustic sessions.','Adding shoulder mics to reinforce toms and snare when overheads alone sound too distant.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3c825327-585e-561d-9a70-76487a8b19bd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Overhead-and-shoulder array'),'[^a-z0-9]','','g'));
