INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0b58a573-499b-5cad-adca-de91e517aae9','Parallel Vocal Compression','A vocal mixing technique in which a heavily compressed copy of a vocal is blended with the unprocessed dry vocal, rather than compressing the vocal fully in line. The dry path preserves the natural transients and dynamics while the compressed path adds density, sustain and low-level detail; the two are mixed to taste. It is also called parallel or New York compression.','This mixes two versions of a vocal together. One is left untouched, keeping its natural punch. The other is squashed hard, which lifts up the quiet parts. Blending them makes the voice fuller and steadier without losing its life.','It exists to make a vocal sound thicker, more consistent and more present while keeping its natural attack and dynamics, which heavy in-line compression would flatten.','An engineer sends the vocal to an aux with a compressor set for strong gain reduction, then blends that return under the dry vocal until the voice gains body and the quiet words come forward.','Compression technique',ARRAY['Parallel compression','Gain reduction','Compression ratio','Serial compression','Makeup gain','Dynamic range']::text[],ARRAY['Compressing the parallel bus so lightly that it adds nothing; the copy should be squashed hard to do its job.','Ignoring latency and phase alignment between the dry and compressed paths, which can hollow out the vocal.','Pushing the blend so far the vocal loses its natural dynamics, defeating the point of the parallel path.']::text[],ARRAY['Thickening a lead pop vocal so quiet words stay audible in a dense mix.','Adding sustain and density to a rap vocal without killing its punch.','Evening out a dynamic performance while preserving its natural attack.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0b58a573-499b-5cad-adca-de91e517aae9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parallel Vocal Compression'),'[^a-z0-9]','','g'));
