INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f049fbb5-f7b0-5a45-a487-808c78d8d245','Percussion-tree spot microphone','A spot (accent) microphone dedicated to the auxiliary-percussion rack or tree, the cluster of small tuned and untuned percussion such as triangle, glockenspiel, crotales, bells and wind chimes in an orchestral or film session. Placed close to that group and mixed subtly beneath the main array, often with delay compensation, it reinforces the presence, attack and detail of quiet percussion that the distant main mics under-capture.','An orchestra''s small percussion, like triangle and bells, is often grouped on a rack called a tree. A close spot mic is added just for it. Mixed quietly under the main mics, it brings out these delicate sounds that faraway mics would miss.','It exists to add presence and clarity to quiet, high-detail percussion that the main pickup captures too weakly, without changing the overall room balance.','A scoring engineer sets a small-diaphragm condenser over the percussion tree, aligns its timing to the main array with delay, and rides it up only where the triangle or glockenspiel needs to cut through.','Spot miking',ARRAY['Spot microphone','Overhead equidistance','Delay compensation','Close miking','Small-diaphragm condenser']::text[],ARRAY['Mixing the spot mic too loud, which pulls the percussion unnaturally forward and breaks the ensemble''s depth and balance.','Failing to time-align the spot mic to the main array, causing comb-filtering and a smeared image.','Aiming the spot mic so broadly that it picks up spill from loud neighboring instruments instead of isolating the tree.']::text[],ARRAY['Reinforcing a triangle or glockenspiel part in a film-score recording.','Adding detail to orchestral auxiliary percussion mixed under a main tree array.','Capturing wind chimes or crotales that the room mics render too distant.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f049fbb5-f7b0-5a45-a487-808c78d8d245' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Percussion-tree spot microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f049fbb5-f7b0-5a45-a487-808c78d8d245','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
