INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '97fff62f-b630-5420-953e-e01a54b367f7','Pre-compressor vocal riding','The practice of manually adjusting (riding) a vocal track''s level with a fader or clip-gain automation before the signal reaches a downstream compressor, so the compressor receives a more consistent input and applies gentler, more even gain reduction. It moves coarse level control to the engineer''s hand and leaves the compressor to handle only fine, fast dynamics.','A singer''s volume jumps around a lot. Before the sound hits a compressor, the engineer moves the fader by hand to even it out. Then the compressor has less work to do and sounds more natural.','It reduces how hard the compressor must work, so gain reduction stays light and transparent instead of clamping down on loud phrases. This preserves tone and avoids the pumping or dulling that heavy compression can cause.','An engineer draws clip-gain or fader automation to lift quiet words and tame shouted ones, then feeds that evened signal into a compressor set for gentle control.','Vocal Technique',ARRAY['Gain riding','Gain staging','Compression','Automation','Makeup gain','Fader riding']::text[],ARRAY['Riding the level so aggressively that all natural dynamics are flattened before the compressor even acts.','Confusing pre-compressor riding with post-compressor automation; ride before the compressor to change how much it grabs, ride after to set the final blend.','Relying on the compressor alone to fix huge level swings, which forces heavy gain reduction and audible artifacts.']::text[],ARRAY['Smoothing an emotional lead vocal that whispers in verses and belts in choruses before it hits the vocal chain.','Preparing a voice-over so a single compressor setting works across the whole take.','Taming inconsistent mic technique from a singer who drifts toward and away from the microphone.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='97fff62f-b630-5420-953e-e01a54b367f7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pre-compressor vocal riding'),'[^a-z0-9]','','g'));
