INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5b469265-c612-5332-b236-ebe91da40934','Resonant-head proximity miking','A close-miking approach in which a directional microphone is placed near a drum''s resonant (non-batter) head, using the proximity effect to reinforce low-frequency body along with the resonant head''s sustain and pitch. It is common on the front head of a kick drum or the bottom head of toms.','A drum has two heads. The one you do not strike is the resonant head. Placing a directional mic close to it adds deep, full low tones, because close mics boost bass. This captures the drum''s ring and body.','It captures the sustain, pitch and low-end weight the resonant head produces, which a batter-side mic often misses. Working close lets the proximity effect add warmth and fullness.','An engineer places a mic just off the front kick head or under a tom''s bottom head to add low-end body, checking polarity against the top mic.','Drum Miking',ARRAY['Proximity effect','Resonant head','Batter head','Kick drum miking','Phase alignment','Close miking']::text[],ARRAY['Forgetting to check polarity between the resonant-head mic and the batter-head mic, causing low-end cancellation.','Placing the mic so close that proximity effect makes the drum boomy and muddy.','Ignoring the air blast from the resonant head, which can overload the capsule without a pad or windscreen.']::text[],ARRAY['Adding low-end body to a kick drum with a second mic near the front head.','Reinforcing tom sustain with a bottom-head mic in a studio session.','Capturing the ring of a floor tom''s resonant head for a fuller recorded sound.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5b469265-c612-5332-b236-ebe91da40934' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Resonant-head proximity miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5b469265-c612-5332-b236-ebe91da40934','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5b469265-c612-5332-b236-ebe91da40934' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ae5d284c-7d0f-5f24-8972-19ea2cec7285','Ride-bell spot microphone','A dedicated spot microphone positioned close to and aimed at the bell (cup) of a ride cymbal, used to capture the bright, defined ''ping'' of bell strikes separately from the wash of the bow. It supplements overhead and hi-hat mics when the bell needs extra presence and articulation.','A ride cymbal has a raised cup in the middle called the bell. Hitting it makes a clear ping sound. A close mic aimed at the bell captures that ping, so it stands out in the mix.','It isolates the bell''s cutting attack so an engineer can raise its level without turning up the whole cymbal wash. This gives the ride pattern clarity and rhythmic definition in dense mixes.','In jazz or fusion sessions an engineer sets a spot mic near the ride bell so the ping can be mixed up for drive without boosting bleed from the rest of the kit.','Cymbal Miking',ARRAY['Spot microphone','Overhead miking','Ride cymbal','Hi-hat miking','Bleed','Off-axis rejection']::text[],ARRAY['Placing the spot mic so close it captures mostly bleed from nearby cymbals and snare instead of the bell.','UNSAFE: Positioning your head close to loud cymbals for long periods without hearing protection; cymbal peaks can exceed safe noise-exposure limits and cause hearing damage.','Ignoring the phase relationship with the overheads, which can thin the cymbal sound when the mics are combined.']::text[],ARRAY['A jazz session where the ride bell pattern must cut through the arrangement.','A live fusion gig needing extra ride definition without raising overall cymbal wash.','Reinforcing a specific bell accent that the overheads capture too distantly.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ae5d284c-7d0f-5f24-8972-19ea2cec7285' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ride-bell spot microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ae5d284c-7d0f-5f24-8972-19ea2cec7285','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ae5d284c-7d0f-5f24-8972-19ea2cec7285' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1de94315-6769-5de5-b22d-ea198ccd6cc7','Rim-plane snare miking','A snare close-miking placement in which the microphone sits in or near the plane of the drum''s rim, angled across the head so its directional null points at a bleed source such as the hi-hat. Keeping the capsule at rim height balances head attack and body while maximising rejection of adjacent instruments.','The snare''s metal edge is called the rim. Placing the mic level with the rim and angling it lets the mic''s deaf spot point at the hi-hat. That keeps the snare loud in the mic and the hi-hat leakage low.','It exploits a directional microphone''s off-axis null to reject hi-hat and cymbal bleed while still capturing the snare''s crack and body. This improves separation for cleaner mixing and gating.','An engineer sets the snare mic just above the rim, tilts it toward the drum''s center, and rotates it so a null faces the hi-hat, checking bleed by soloing the channel.','Drum Miking',ARRAY['Off-axis rejection','Polar pattern','Bleed','Hi-hat miking','Cardioid','Spot microphone']::text[],ARRAY['Aiming the mic''s front at the snare without checking where the null points, so hi-hat bleed stays high.','Placing the mic in the drummer''s stick path at rim height, risking a struck and damaged microphone; keep it clear of the playing zone.','Setting the capsule so far over the rim that rim clicks and shell tone dominate over head attack.']::text[],ARRAY['Recording a drum kit where hi-hat bleed into the snare mic must be minimised.','Live sound reinforcement needing a tight, gateable snare signal.','A compact kit setup where the hi-hat sits close to the snare.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1de94315-6769-5de5-b22d-ea198ccd6cc7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rim-plane snare miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1de94315-6769-5de5-b22d-ea198ccd6cc7','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1de94315-6769-5de5-b22d-ea198ccd6cc7' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '318f431d-a5c8-582a-86a4-336d491abae5','Rosin-noise control','Techniques for reducing the harsh, scratchy bow noise—caused by rosin on the bow hair gripping the string—that close microphones on violins, violas, cellos and basses tend to exaggerate. Control relies on increasing working distance, aiming the mic off the bowing point, and placing it over the body rather than directly at the bow contact.','Players rub sticky rosin on the bow so it grips the string. Up close, a mic can pick up a harsh scratchy sound from this. Moving the mic back a little and aiming it away from the bow makes the tone smoother.','It keeps close string recordings warm and musical by taming the abrasive high-frequency noise that appears when a mic sits too near the bow contact point. This preserves the instrument''s natural tone.','When a spot mic on a violin sounds scratchy, the engineer backs it off slightly, moves it toward the body or f-holes, and angles it away from the exact bowing point.','String Miking',ARRAY['Spot microphone','Working distance','Off-axis coloration','Close miking','String section miking','Proximity effect']::text[],ARRAY['Placing the mic directly over the bow contact point, which captures the most rosin scratch.','Trying to fix scratchy tone only with EQ instead of first improving mic distance and angle.','Miking too close on solo strings, which exaggerates both bow noise and proximity-effect boom.']::text[],ARRAY['Close-miking a solo violin that sounds harsh and scratchy on playback.','Spot-miking a string section for a film score without capturing bow noise.','Recording a cello where the engineer must balance warmth against bow articulation.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='318f431d-a5c8-582a-86a4-336d491abae5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rosin-noise control'),'[^a-z0-9]','','g'));
