SELECT '318f431d-a5c8-582a-86a4-336d491abae5','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='318f431d-a5c8-582a-86a4-336d491abae5' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '828ceaee-9367-5196-9221-46b042c61815','Saxophone bell–key split','A dual-capture approach to miking a saxophone that combines one microphone (or aim) on the bell with another on the key/tone-hole area, then blends the two to balance the bright, projecting low notes leaving the bell against the fuller body tone radiating from the open tone holes. It addresses the fact that a saxophone radiates different notes from different points along its body.','A saxophone does not send all its sound out of the bell. Higher notes leave through the open finger holes up the body. Using one mic at the bell and one at the keys, then mixing them, captures the whole instrument evenly.','It evens out the saxophone''s uneven radiation so low bell notes do not overpower the mid-body notes coming from the tone holes. Blending the two positions yields a natural, consistent tone across the range.','A studio engineer places one mic angled at the bell edge and another over the upper keys, then balances them so bell honk and key-note body sit in proportion.','Woodwind Miking',ARRAY['Sound radiation','Spot microphone','Off-axis coloration','Saxophone key-cup noise capture','Bell miking','Blend']::text[],ARRAY['Pointing a single mic straight into the bell, which over-captures loud low notes and misses upper-register body.','Blending the two mics without checking polarity, thinning the tone through phase cancellation.','Setting the key mic so close it emphasises pad and key-cup clatter over musical tone.']::text[],ARRAY['Recording a tenor sax solo that must sound even from low honks to high wails.','Miking a saxophone in a horn section for a balanced studio tone.','Capturing both bell projection and body warmth for a jazz ballad.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='828ceaee-9367-5196-9221-46b042c61815' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Saxophone bell–key split'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '828ceaee-9367-5196-9221-46b042c61815','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='828ceaee-9367-5196-9221-46b042c61815' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bd913381-9b10-573b-87b8-cee7d1cadc52','Saxophone key-cup noise capture','The pickup of the mechanical clicking and thumping produced by a saxophone''s key cups and pads seating against the tone holes, which close microphones near the keys readily capture. Depending on intent, engineers either embrace this noise for an intimate, realistic close sound or minimise it through mic distance and angle.','A saxophone''s keys have padded cups that slap shut over the holes. Up close, a mic hears these clicks and thumps. Sometimes engineers keep this for a real, intimate feel, and sometimes they move the mic to reduce it.','Naming this noise lets an engineer decide whether the mechanical key sound adds intimacy or distracts, and place the mic accordingly. It explains why very close saxophone mics capture clatter a distant mic would not.','For a breathy, up-close sax sound an engineer keeps a mic near the keys to include pad noise; to clean it up, they move the mic toward the bell or add distance.','Woodwind Miking',ARRAY['Close miking','Saxophone bell–key split','Working distance','Bleed','Off-axis coloration','Sound radiation']::text[],ARRAY['Miking extremely close for a big tone and then being surprised by loud, distracting key clatter.','Trying to remove key noise entirely with EQ, which also dulls the instrument''s natural tone.','Assuming all key noise is a fault; a controlled amount can add realism to a solo recording.']::text[],ARRAY['Recording an intimate solo saxophone where some key noise adds character.','Cleaning up a pop horn overdub where pad clatter distracts from the line.','Choosing mic distance on a woodwind session to control mechanical noise.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bd913381-9b10-573b-87b8-cee7d1cadc52' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Saxophone key-cup noise capture'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bd913381-9b10-573b-87b8-cee7d1cadc52','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bd913381-9b10-573b-87b8-cee7d1cadc52' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '71712fa3-26ce-543b-9c39-221013e9bc9d','Section spot miking','The use of close or medium-distance spot microphones on individual instrumental sections—such as strings, brass or woodwinds—within a larger ensemble captured mainly by a distant main array. The spot signals are blended in to reinforce clarity, balance and presence for sections the main pickup renders too weak or distant.','A single pair of far mics may not catch every group in an orchestra clearly. You add close mics on each section, like the brass or strings. That lets the engineer lift a group that is too quiet. These extra mics are mixed in gently.','Spot mics give the engineer control over the balance and detail of sections a main stereo array captures too distantly. They add clarity and presence without discarding the natural hall sound of the main pickup.','On an orchestral session the engineer places spot mics over each section, blends them low under the main array, and delays them to time-align with the distant pickup.','Ensemble Miking',ARRAY['Spot microphone','Main microphone array','Time alignment','3:1 rule','Section-leader spot','Bleed']::text[],ARRAY['Mixing spot mics in too loud, collapsing the natural depth and hall sound of the main array.','Failing to time-align (delay) spot mics to the main array, causing smearing and comb filtering.','Ignoring the 3:1 spacing guideline between spots, so bleed between them combs and colors the sound.']::text[],ARRAY['Recording a film-score orchestra where individual sections need balance control.','Reinforcing a distant main array on a live symphonic broadcast.','Bringing out a weak woodwind line buried under brass in an orchestral take.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='71712fa3-26ce-543b-9c39-221013e9bc9d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Section spot miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '71712fa3-26ce-543b-9c39-221013e9bc9d','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='71712fa3-26ce-543b-9c39-221013e9bc9d' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dd7cfbcd-69f8-55f8-a099-d9fac7fb9f42','Section-leader spot','A spot microphone placed on the principal player, or section leader, of an orchestral section so their part can be featured—such as a concertmaster''s solo—or used to anchor and characterise the section''s tone. It provides a close, present signal for the lead chair, distinct from the section''s overall spot or the main array.','Each orchestra section has a lead player called the section leader. Putting a close mic on that player lets the engineer feature their solos. It also gives the section a clear, present anchor in the mix.','It lets the engineer highlight the principal''s solos and lend the section a defined focal tone, without raising the level of the whole section. This matters when the lead chair has exposed passages.','For a concertmaster solo, the engineer places a spot mic on the first-chair violinist and rides it up during the solo, blending it back afterward.','Ensemble Miking',ARRAY['Spot microphone','Section spot miking','Main microphone array','Concertmaster','Time alignment','Fader riding']::text[],ARRAY['Leaving the leader spot up at section level, making one player unnaturally louder than the rest.','Forgetting to time-align the leader spot with the main array, smearing the solo.','Placing the mic so close it loses the surrounding section sound needed for blend.']::text[],ARRAY['Featuring a concertmaster''s solo within an orchestral recording.','Anchoring a string section''s tone around its principal player.','Highlighting a principal wind player''s exposed passage in a live broadcast.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dd7cfbcd-69f8-55f8-a099-d9fac7fb9f42' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Section-leader spot'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dd7cfbcd-69f8-55f8-a099-d9fac7fb9f42','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dd7cfbcd-69f8-55f8-a099-d9fac7fb9f42' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '961b7439-d0c0-511d-97f2-629c23d4bf24','Section-over-bell array','A microphone array positioned above the bells of a brass or horn section so the mics capture the combined output radiating upward and forward from the instruments'' bells. Spacing and height are set to balance blend and separation across the section while following spacing guidelines that control comb filtering.','Brass instruments send their sound out of the bell, which points up and forward. Hanging a row of mics above the bells catches the whole section evenly. Spacing the mics apart keeps their signals from clashing.','It captures a brass or horn section as a blended group from the direction where the bells project most energy, giving a full, even section sound. Proper spacing keeps the mics from combing against each other.','An engineer flies a spaced array a set distance above the section''s bells, following the 3:1 spacing guideline, then blends it for a cohesive brass sound.','Ensemble Miking',ARRAY['Spot microphone','3:1 rule','Sound radiation','Section spot miking','Comb filtering','Overhead miking']::text[],ARRAY['Spacing the mics too closely relative to their distance from the bells, causing comb filtering between them.','Aiming straight into the bells at close range, capturing harsh, blaring high frequencies.','UNSAFE: Working with your head beside loud brass bells for long stretches without hearing protection, which can exceed safe noise-exposure limits.']::text[],ARRAY['Miking a big-band brass section for a balanced, blended sound.','Capturing a trumpet and trombone section from above their forward-facing bells.','Recording a horn-section overdub where separation between players matters.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='961b7439-d0c0-511d-97f2-629c23d4bf24' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Section-over-bell array'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '961b7439-d0c0-511d-97f2-629c23d4bf24','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='961b7439-d0c0-511d-97f2-629c23d4bf24' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9261cb86-c1e4-5141-81c9-4e4154cc871f','Shoulder miking','A microphone placement in which the mic is positioned above and behind the performer''s shoulder, aimed down at the instrument, so it captures roughly the blend the player hears. It is used chiefly on acoustic guitar and similar instruments to obtain a natural, balanced tone that avoids the boom and boxiness of a mic aimed straight at the sound hole.','This means putting the mic just over the player''s shoulder, pointing down at the instrument. It hears the sound much as the player does. That gives a natural, balanced tone and avoids the boomy sound of miking the hole.','It gives an engineer a balanced, whole-instrument pickup from the player''s own perspective, avoiding the exaggerated low end and boxiness a close sound-hole mic produces. It suits instruments the performer hears from above.','On an acoustic guitar overdub the engineer places a small-diaphragm mic over the player''s shoulder pointing down at the strings, then adjusts height for the right balance of body and string detail.','Instrument Miking',ARRAY['Close miking','Proximity effect','Sound hole','Spot microphone','Working distance','Off-axis coloration']::text[],ARRAY['Aiming the shoulder mic at the sound hole, reintroducing the boom the technique is meant to avoid.','Placing the mic so high it captures mostly room and string squeak instead of full body.','Assuming one fixed shoulder position suits every instrument; height and angle must be tuned by ear.']::text[],ARRAY['Recording a solo acoustic guitar with a natural, balanced tone.','Capturing a singer-songwriter''s guitar from the player''s own perspective.','Miking an instrument where a sound-hole mic sounds too boomy.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9261cb86-c1e4-5141-81c9-4e4154cc871f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Shoulder miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9261cb86-c1e4-5141-81c9-4e4154cc871f','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9261cb86-c1e4-5141-81c9-4e4154cc871f' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '07306c84-f843-5787-ae3d-ce981ac114cc','Sibilance steering','Adjusting microphone position and angle to control the amount of vocal sibilance—the concentrated high-frequency energy of ''s'', ''sh'' and ''t'' sounds—reaching the capsule. Because sibilant energy projects forward and narrowly from the mouth, tilting or offsetting the mic off the direct mouth axis reduces captured sibilance at the source.','The sharp ess and shh sounds in singing shoot straight out of the mouth. Aiming the mic a little off to the side catches fewer of them. This softens harsh sibilance at the source instead of fixing it later.','It reduces harsh sibilance at capture, lightening or removing the need for later de-essing that can dull a vocal. Working with the directional nature of sibilant sounds keeps the recorded tone natural.','When a vocal track is spitty, the engineer offsets the mic slightly above or to the side of the mouth so the sibilant energy passes to the side of the capsule.','Vocal Miking',ARRAY['Sibilance','De-essing','Off-axis response','Pop filter','Proximity effect','Working distance']::text[],ARRAY['Aiming the mic straight at the mouth, then relying entirely on heavy de-essing that dulls the vocal.','Offsetting the mic so far that the whole vocal goes dull and loses air, not just the sibilance.','Confusing sibilance with plosive pops; a pop filter handles blasts of air, steering handles ess sounds.']::text[],ARRAY['Taming a spitty lead vocal during tracking rather than in the mix.','Recording a voice-over artist with naturally strong sibilance.','Positioning a mic on a singer whose ess sounds overload the high end.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='07306c84-f843-5787-ae3d-ce981ac114cc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sibilance steering'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
