WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='07306c84-f843-5787-ae3d-ce981ac114cc' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '10f2e035-d331-5f24-84ab-6d34397bb63a','Slide-path clearance','The practice of positioning a trombone microphone (and its stand) so the instrument''s slide can move through its full range of travel without striking the mic. Because the slide extends well forward in the outer positions, the mic must sit to the side of or safely beyond the slide''s arc while still capturing the bell.','A trombone''s slide shoots forward and back as the player works it. You must place the mic so the slide can never hit it. Set the mic off to the side or beyond the slide''s reach, while still aiming at the bell.','It prevents the moving slide from colliding with the microphone, protecting both the instrument and the mic while keeping a usable pickup. It reconciles close miking with the trombone''s large physical movement.','An engineer sets the trombone mic off-axis to the side of the bell, checks the player''s fullest slide extension, and confirms nothing obstructs the slide before the take.','Brass Miking',ARRAY['Spot microphone','Bell miking','Working distance','Off-axis coloration','Mic stand','Close miking']::text[],ARRAY['Placing the mic directly in front of the bell, where the extended slide can strike it and the instrument.','Setting clearance for a resting slide only, forgetting the player reaches full extension in performance.','Moving the mic so far aside to clear the slide that it no longer captures the bell tone well.']::text[],ARRAY['Close-miking a trombone soloist who uses full slide extension.','Setting up a trombone section on a crowded live stage.','Recording a big band where trombone mics sit near other players and stands.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='10f2e035-d331-5f24-84ab-6d34397bb63a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Slide-path clearance'),'[^a-z0-9]','','g'));
