INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7b43f540-de75-57c3-b0d4-877cc9155de0','Snare buzz suppression','Methods for reducing the unwanted sympathetic rattle of a snare drum''s wires (snares) buzzing in response to other instruments—such as toms, kick drum or bass—rather than to intentional snare hits. Approaches include adjusting snare-wire tension, retuning the resonant head, damping, and, at the console, gating or editing the snare mic signal.','A snare has metal wires under it that rattle when you strike it. They also buzz on their own when nearby drums or bass notes ring. Suppressing this means tuning, tensioning, or damping the snare so it only rattles when meant to.','It removes distracting sympathetic buzz that muddies recordings and live mixes, so the snare responds mainly to its own hits. This cleans up the drum sound and makes gating the snare mic easier.','When the snare buzzes under the toms, an engineer or drummer adjusts the snare-wire tension and resonant-head tuning first, then may gate the snare mic to reject remaining buzz.','Drum Miking',ARRAY['Snare wires','Resonant head','Noise gate','Sympathetic resonance','Bleed','Close miking']::text[],ARRAY['Cranking snare-wire tension to kill buzz, which chokes the drum''s natural sound and sustain.','Reaching for a gate before addressing tuning and tension, so the underlying buzz still bleeds into other mics.','Blaming the mic for buzz that is actually the snare wires resonating with the kick or bass.']::text[],ARRAY['A recording where the snare rattles every time the floor tom is struck.','A live mix where the snare buzzes in sympathy with the bass guitar.','Tracking drums in a room where the snare responds to low-frequency stage rumble.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7b43f540-de75-57c3-b0d4-877cc9155de0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Snare buzz suppression'),'[^a-z0-9]','','g'));
