SELECT '7b43f540-de75-57c3-b0d4-877cc9155de0','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7b43f540-de75-57c3-b0d4-877cc9155de0' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
